WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[59894] = { title = "The Golden Dawn", description = "The machinations of war commence. Gharmal's crimes are now evident to all of the Shadowlands.\n\nBastion demands vengeance, and we shall share it with them. Only our combined forces will defeat the Constructs once and for all.\n\nMeet Draka at the overlook. Your presence there will help solidify an agreement.", objectives = "Teleport to the Overlook to meet with Draka.", completion = "An alliance is secured. Now we plan the attack." }
WordHunterWoW_QuestEN[59897] = { title = "Seeking the Baron", description = "Take this amulet. One like it is carried by each of the Four Horsemen.\n\nThe amulets are imbued with a power that links them to one another. That connection should help you locate Darion Mograine.\n\nNo doubt Darion has witnessed countless horrors in the Maw. Perhaps he has caught sight of the missing baron.\n\nLet us hope he can lead you to our Azerothian allies as well.", objectives = "Enter the Maw." }
WordHunterWoW_QuestEN[59902] = { title = "A Curious Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[59903] = { title = "Split Blob Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[59904] = { title = "A Curious Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[59905] = { title = "A Curious Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[59907] = { title = "Mawsworn Menace", description = "Our knights are strong, but they don't stand much chance scattered against such an opponent.\n\nWe need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.", objectives = "Defeat 8 Mawsworn enemies in the Crucible of the Damned.", progress = "Let your blade do the talking!", completion = "Our enemy is relentless, but we will continue to drive them back.\n\nStand vigilant, <class>." }
WordHunterWoW_QuestEN[59910] = { title = "Fight and Flight", description = "Mograine and Emeni will lead the assault on the western gate. \n\nYou and Xandria will advance from the east. Secure the area and slay all who oppose you. \n\nOnce we have them surrounded, we can strike the final blow against Gharmal.", objectives = "Fly with Xandria to the House of Constructs.", completion = "This place is mired with atrocities. They must be purged." }
WordHunterWoW_QuestEN[59912] = { title = "[OLD NOT USED]", description = "Now that you have seen the basics it is time for us to expand your understanding.\n\nI hope your little mind will be able to hold this information.\n\nYou seem capable so far, but you are so small. I'll be intrigued to see if you are bigger on the inside.\n\nFirst. You need to learn more about the catalysts. There should be a small number growing in this very grove. Fetch me some and I can explain what they are.", objectives = "" }
WordHunterWoW_QuestEN[59914] = { title = "Fear to Tread", description = "It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies.\n\nWe will draw less attention alone. The Ebon Blade will hold back, awaiting my signal.\n\nCome, let us see what awaits us in this hellscape.", objectives = "Scout Calcis for any signs of your allies.", progress = "Champion? Tell me this is not an illusion.", completion = "Praise the Light! I... I'd almost given up hope.\n\n<Jaina looks upon the Ebon Blade knights.> \n\nIs this... all that remains of your forces?" }
WordHunterWoW_QuestEN[59915] = { title = "Soul in Hand", description = "My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent.\n\nIt will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care.\n\nLet's bring our prize to the Lord Admiral.", objectives = "Return to Lady Jaina Proudmoore in Forlorn Respite.My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent.\n\nIt will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care.\n\nLet's bring our prize to the Lord Admiral.", completion = "It seems your search was a success.\n\nEnough rest. There's much to be done." }
WordHunterWoW_QuestEN[59916] = { title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure that they meet it!", objectives = "Kill 10 House of Constructs forces in the Separation Chamber.", completion = "This bloodshed will not bring them back... but it may spare others from the same fate." }
WordHunterWoW_QuestEN[59917] = { title = "Kill Them, Of Course", description = "These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources.\n\nTheir presence here is inconvenient, to put it mildly.\n\nThey tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher.\n\nExactly the sort of work you're accustomed to, yes?", objectives = "Slay 8 Enraged Gluttons.", progress = "How did the hunting go?", completion = "Nicely done. You've bought us precious time." }
WordHunterWoW_QuestEN[59919] = { title = "An Earned Bond", description = "There is one more thing you should do, Maw Walker.\n\nIn rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you.\n\nGiven his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.", objectives = "Soulbind with Mikanikos.", progress = "This is a moment to remember.", completion = "Never in all my millennia did I think I would see the day a steward would soulbind with an outsider. Times are certainly changing, are they not?" }
WordHunterWoW_QuestEN[59920] = { title = "Light the Forge, Forgelite", description = "I think we have the materials I will need to light the forge, at long last.\n\nI am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands.\n\nI would very much appreciate your help to get the place in order while I coax the forge to life once more.", objectives = "Help Forgelite Sophone.", completion = "I am deeply grateful for your help. Now I can practice my craft again!" }
WordHunterWoW_QuestEN[59921] = { title = "All I Ever Will Be", description = "This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary.\n\nMany of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage.\n\nAccompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies.\n\nHe will learn that this afterlife is not the one suited for him.", objectives = "Reflect on the Scrolls of Remembrance with Alexandros Mograine.", progress = "What have you learned?", completion = "Did this venture enlighten you?" }
WordHunterWoW_QuestEN[59922] = { title = "Do Not Forget", description = "The Arbiter's judgment was, as always, infallible.\n\nThough Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus, not Bastion.\n\nNonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted.\n\nGo now. Return to your leader with news of our victory today.\n\nAnd tomorrow, we shall purge our foes once and for all.", objectives = "Return to Draka in the Seat of the Primus.", completion = "So we have proven our honor... and gained a new ally." }
WordHunterWoW_QuestEN[59925] = { title = "[OLD NOT USED]", description = "Let's see how much more we can push into that little brain of yours.", objectives = "" }
WordHunterWoW_QuestEN[59926] = { title = "Warming Up", description = "We're nearing the island where the Horde's last expedition was lost. \n\nYou need to be prepared for what's out there. Warm up on these combat dummies.", objectives = "Warm up by fighting a Combat Dummy.", progress = "Do not bother me! Go and attack those combat dummies. Show me your power.", completion = "Good, you've kept training since we set sail.\n\nI need to speak with the crew about this storm. \n\nSpar with Throg. He will assess your skills and decide on your role once we make landfall." }
WordHunterWoW_QuestEN[59927] = { title = "Stand Your Ground", description = "Lok-tar! Nothing quite like a good fight in the rain. \n\nWe will spar together and take the measure of your strength!", objectives = "Spar with Grunt Throg.", completion = "You show promise, <class>. Perhaps you too will find glory on the island!" }
WordHunterWoW_QuestEN[59928] = { title = "Brace for Impact", description = "Well fought, {name}. You bring strength and honor to the Horde!\n\nNow we just--wait...\n\nDo you hear that?", objectives = "Find Thrall.Well fought, <name>. You bring strength and honor to the Horde!\n\nNow we just--wait...\n\nDo you hear that?", completion = "This ship won't make it to the island in one piece.\n\nHold on to something, and pray that the elements will spare us from a grim death at sea." }
WordHunterWoW_QuestEN[59929] = { title = "Murloc Mania", description = "The shore is littered with shipwrecks. This must be where the lost expedition crashed.\n\nWe'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up.\n\nSlay those murlocs to get back what belongs to the Horde.", objectives = "Recover 6 First Aid Kits from Murlocs.", progress = "The murlocs are carrying our first aid kits. Slay them and bring all of the kits to me.", completion = "Excellent work. Let's get the survivors back on their feet." }
WordHunterWoW_QuestEN[59930] = { title = "Emergency First Aid", description = "We must treat our wounded before we can begin for the missing expedition.\n\nTake this first aid kit and tend to the survivors. I'll handle the others nearby.", objectives = "Use a First Aid Kit on Bo, Mithdran Dawntracker, and Lana Jordan.", progress = "Use your first aid kit to help the others.", completion = "We're back on our feet. Now let's move. The lost expedition is somewhere on this island." }
WordHunterWoW_QuestEN[59931] = { title = "Finding the Lost Expedition", description = "Breka Grimaxe went north to look for survivors. Join her to see what she's found.\n\nI'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.", objectives = "Search the nearby camp for expedition survivors.", completion = "So... hungry...\n\nDey took... everyone else... I be... da last one..." }
WordHunterWoW_QuestEN[59932] = { title = "Cooking Meat", description = "This is Won'sa, a shaman who was with the expedition.\n\nShe is dying of starvation. A death unfit for the Horde!\n\nSlay some of the nearby wildlife for their meat and cook it over the fire.\n\nWon'sa can tell us what happened to the missing expedition after she eats.", objectives = "Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire.", progress = "Please... I be needin'... food...", completion = "<Won'sa quickly eats the meat that you cooked.>\n\nLooks I not gonna be knockin' on Bwonsamdi's door, after all.\n\nYa best hurry. Da quilboar took Shuja and da rest of da expedition!" }
WordHunterWoW_QuestEN[59933] = { title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", objectives = "Spar with Warlord Grimaxe.", completion = "You're ready to slaughter the quilboar! Let's speak to Won'sa and see what she knows." }
WordHunterWoW_QuestEN[59934] = { title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition... including my daughter.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", objectives = "Spar with Warlord Grimaxe.", completion = "You're ready to slaughter the quilboar! Let's speak to Won'sa and see what she knows." }
WordHunterWoW_QuestEN[59935] = { title = "Northbound", description = "Da quilboar kidnapped da rest of da expedition and took dem north.\n\nDey said dey gonna use da expedition for some sorta sacrifice! \n\nYa gotta head north as fast as ya can ta stop dem!", objectives = "Scout northward and find Mithdran Dawntracker.", completion = "I have good news... and most unfortunate news." }
WordHunterWoW_QuestEN[59937] = { title = "Taming the Wilds", description = "A hunter like yourself needs a good pet by your side. Did you not bring one with you?\n\nHmm. I suppose I shall have to compensate for your lack of training.\n\nListen closely and learn quickly. I will teach you how to tame a beast and make it your pet.\n\nYou will need one if you are to fight the quilboar.", objectives = "Learn Tame Beast from Mithdran Dawntracker, then use Tame Beast on any nearby wildlife.", progress = "I will teach you how to tame beasts. Then, you will need to tame any of the surrounding wildlife.", completion = "Fine work. The lessons you learn from the inimitable Mithdran Dawntracker will last you a lifetime.\n\nNow, down to the business of our quilboar foes..." }
WordHunterWoW_QuestEN[59938] = { title = "Down with the Quilboar", description = "I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition.\n\nThe ritual is being performed by the tribe's leader, Geolord Grek'og. \n\nSlay Grek'og and save the survivor.\n\nShow this brute that the Horde is not to be trifled with.", objectives = "Slay Geolord Grek'og.", completion = "You sure got some guts! I respect that. I joined this expedition thinkin' it'd be a quick and easy way to make a little profit.\n\nBut now with all this necromancy and crazy ogres... maybe I can make a LOT of profit!" }
WordHunterWoW_QuestEN[59939] = { title = "Forbidden Quilboar Shadow Magic", description = "Quilboar are savage and violent. I did not think they knew how to use shadow magic.\n\nObviously, we cannot allow them to continue their rituals. And certainly not on members of the Horde.\n\nSlay the quilboar in the den. They must learn the fatal error of their ways.", objectives = "Slay 7 Quilboar within the Quilboar Briarpatch.", completion = "A fine job. The quilboar seem to be keeping their distance. Perhaps they learned their lesson." }
WordHunterWoW_QuestEN[59940] = { title = "The Choppy Booster Mk. 5", description = "You're in luck, 'cause I'm the ONE goblin who can help you find the rest of the expedition!\n\nFeast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own!\n\nI call it the Choppy Booster Mk. 5. Use it to find Shuja and the others.", objectives = "Use the Choppy Booster Mk. 5 to find Shuja Grimaxe.", progress = "Why are you gabbing at me? Hop on the Choppy Booster Mk. 5 and get going!", completion = "All right, time to bend some rules and make a giant boar!" }
WordHunterWoW_QuestEN[59941] = { title = "Re-sizing the Situation", description = "I call this gadget \"the Re-Sizer.\" It's what I used to unshrink the Choppy Booster Mk. 5.\n\nLook, I'm gonna be honest. I got, at best, a passing understandin' of how this thing works.\n\nThat means I'm gonna be pushing a lot of buttons to see what happens.\n\nI'm sure we'll figure out how to upsize one of these boars. Then we'll use it to trample those undead goons!\n\nYou hold the Re-Sizer while I fiddle with it. Then just press the button and, uh... hope for the best?", objectives = "Use the Re-Sizer on 3 Wandering Boars.", progress = "Just don't point the Re-Sizer at me, okay? Use it on the boars.", completion = "So the giant boar was a fool's errand, and you turned the device into a weapon instead?\n\nGood work. Let's see if you can pull this off." }
WordHunterWoW_QuestEN[59942] = { title = "The Re-Deather", description = "I got the perfect plan. You're gonna ride the Choppy Booster Mk. 5 and BLAST those walkin' cadavers from the sky!\n\nI hereby dub the Re-Sizer the \"Re-Deather.\" We're gonna show them where the undead belong!\n\nEr, except for OUR undead. They're totally fine.\n\nAnyway, hop on the Choppy Booster Mk. 5 and I'll pilot it.\n\nOnce we save Wrathion, we'll blast our way to all the other survivors!", objectives = "Ride the Choppy Booster Mk. 5 and blow up the undead army.", completion = "Thank you, stranger. I failed the Horde... I was not strong enough to stop this threat on my own." }
WordHunterWoW_QuestEN[59943] = { title = "The Harpy Problem", description = "The ogres are planning to sacrifice the rest of the expedition to fuel this ritual to control Kalecgos, leader of the blue dragonflight.\n\nIt seems one of the survivors was taken to the hills north of here. Bo scouted ahead to investigate.\n\nCome, we'll see what he has found.", objectives = "Meet with Bo near the Harpy Roost.", completion = "I have found the missing member of the expedition... but we have many problems to deal with first." }
WordHunterWoW_QuestEN[59944] = { title = "The Rescue of Herbert Gloomburst", description = "The harpies plan to sacrifice the expedition's mage, a Forsaken by the name of Herbert Gloomburst.\n\nHerbert's ethics are... questionable, but he always strives to serve the Horde. We'll need his magic to stop the ogres.\n\nLet's move.", objectives = "Rescue Herbert Gloomburst from the harpies' necromantic ritual", completion = "Thanks for the save! They must be desperate for sacrifices if they wanted to use someone who's already dead.\n\nIf anyone is going to drain my life essence to use in a forbidden ritual, it's going to be me!" }
WordHunterWoW_QuestEN[59945] = { title = "Harpy Culling", description = "The harpies seem to be in league with the ogres. Many of them are gathering to attack our camp.\n\nWe must thin their numbers and thwart their attempts to eliminate us.\n\nPerhaps they will learn it is best to leave the Horde be.", objectives = "Defeat 10 harpies and their allies.", completion = "The harpies seem to be retreating to their roost. That should give us time to stop the ogres." }
WordHunterWoW_QuestEN[59946] = { title = "Purge the Totems", description = "The harpies have placed vile totems throughout the area to attain more power.\n\nWe must destroy those totems in order to debilitate our foes.\n\nTake this torch and burn any totems you see. It is wise to weaken one's enemy before the fight even begins.", objectives = "Set fire to 5 Harpy Totems.", completion = "The harpies grow weaker with their totems destroyed. Let us hope they realize that the Horde is a force to be reckoned with." }
WordHunterWoW_QuestEN[59947] = { title = "Message to Base", description = "Let us return to camp with Herbert in tow.\n\nWe're one step closer towards thwarting the ogres and their plans.", objectives = "Return to the Horde Camp and speak with Thrall.", completion = "It is good to see you all back in one piece. You are testament to the Horde's strength of will!\n\nLet's hope Gloomburst is as powerful as he is unhinged." }
WordHunterWoW_QuestEN[59948] = { title = "Westward Bound", description = "Thrall wants us to search west of here for the site of the next ritual.\n\nWe could use your help. I've already died once. It's not an experience I'd care to repeat.", objectives = "Meet Lana Jordan west of the Horde Camp.", completion = "A giant pit filled with necrotic energy and spiders.\n\nI used to hate spiders. Now that I'm Forsaken, I don't think they're all that bad.\n\nThey will still definitely kill you, though." }
WordHunterWoW_QuestEN[59949] = { title = "Who Lurks in the Pit", description = "There's a whole lot of shadow energy coming from this pit. I'm guessing a ritual is being performed down there. And that means a sacrifice.\n\nDo you hear that? I've got the best hearing around, ever since I got this new ear sewn onto me.\n\nIt sounds like there are some more of our soldiers trapped down there. Probably all webbed up.\n\nWon'sa and I will... stay up here and help anyone who gets out.\n\nYou should jump in and rescue anyone who is left down there!", objectives = "Rescue 5 Trapped Expedition Members", completion = "Crenna Earth-Daughter will be vital to our cause. Her connection to nature will help us understand what the ogres have done to this island.\n\nGood work, recruit." }
WordHunterWoW_QuestEN[59950] = { title = "Stocking Up on Supplies", description = "Provisioner Jin'hake managed to recover some other supplies from the shipwreck.\n\nTake a look at what he has before heading out.", objectives = "Purchase any item from Provisioner Jin'hake and sell any of your items to him.", progress = "Provisioner Jin'hake should have some supplies that you can use.", completion = "I hope you have what you need. \n\nThrog found this bag nearby and thought you might have use of it." }
WordHunterWoW_QuestEN[59951] = { title = "A Druid's Form", description = "Thank you for rescuing me, {name}. Allow me to aid you in your druidic studies.\n\nTo escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same.\n\nCome with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", objectives = "Commune with the nearby druid stone.", progress = "Come. We have no time to lose.", completion = "Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form." }
WordHunterWoW_QuestEN[59952] = { title = "A Hunter's Trap", description = "If you want to be called a true hunter, you'll need to learn the art of trapping.\n\nFortunately, I happen to be an expert in it.\n\nFirst, you will need to gather supplies from the surrounding area so you can fashion a proper freezing trap.\n\nHerbert can supply you with a mote of ice. Scavenge the area for other materials.\n\nYou will need the trap to handle another issue that has recently arisen.", objectives = "Scavenge parts in the area to create a Freezing Trap.", progress = "Did you acquire the necessary supplies? Herbert should have the ice mote, while the other two should be nearby.", completion = "With a little work, this can become an effective trap.\n\nPart of what makes a real <class> is the resourcefulness to use what your environment provides." }
WordHunterWoW_QuestEN[59953] = { title = "Hunting the Stalker", description = "Now that you have your trap, we can move onto the true problem at hand.\n\nA strange creature not native to this island has been stalking our camp.\n\nI think we should capture it and see how it can help us.\n\nSet the freezing trap within these ruins to lure it out. We'll see just what we are dealing with.", objectives = "Use your Freezing Trap within the Ogre Ruins to lure out the beast stalking the camp.", completion = "I admit, I am rather ashamed I did not immediately recognize this beast.\n\nIt must be quite resilient if it was able to survive this long on its own!\n\nHere, let me teach you another trick. You'll want to have multiple pets to switch between if you're to be a <class> of any worth." }
WordHunterWoW_QuestEN[59954] = { title = "A Mage's Knowledge", description = "You've got some good spells for a novice mage. There are a few things holding you back, though.\n\nFor instance, it's absolutely clear to me you don't know Polymorph.\n\nIf you did, you would've been using it on the harpies that were attacking us!\n\nLet's fix that. My spellbook has details on how to cast it... but my captors threw it into the nearby lake. \n\nGrab it for me, would you? Oh, and don't look through the book beforehand.\n\nYou will almost certainly regret it if you do.", objectives = "Recover Herbert Gloomburst's book at the bottom of the nearby lake.", progress = "Hopefully my book isn't too damaged from sitting at the bottom of the lake.", completion = "Perfect! The page for Polymorph is smudged, but a little guesswork never stopped me from figuring out a spell.\n\nIt'll be quick for me to show you how to cast this properly." }
WordHunterWoW_QuestEN[59955] = { title = "The Best Way to Use Sheep", description = "I can't send you off without making sure you can cast Polymorph correctly.\n\nWhy, if you messed it up you may transform someone into something completely different!\n\nI want to make sure I'm around to take notes if that happens.\n\nLet's see... ah, Throg will do nicely! I can spot a prime test subject from a mile away.\n\nShall we begin?", objectives = "Practice using Polymorph against Herbert and Grunt Throg.", progress = "This will be so exciting! Let me know when you're ready to test polymorph.", completion = "You've got the hang of Polymorph. Make sure to use it whenever you're faced with more than one foe!" }
WordHunterWoW_QuestEN[59956] = { title = "A Monk's Focus", description = "You fought well against the harpies, but you'll need even more skill to best the challenges ahead.\n\nWe must meditate and focus if we are to gain more strength.\n\nCome. I know of a place we can go.", objectives = "Follow Bo and meditate with him.", completion = "I can sense a change within you, <name>. Let's see what it is." }
WordHunterWoW_QuestEN[59957] = { title = "One Last Spar", description = "Let's have a quick sparring session before returning to camp.\n\nI can sense new power rising from within you. I want to see it in action!", objectives = "Spar with Bo.", completion = "You look stronger! Good. We'll need such strength if we're to crush these ogres." }
WordHunterWoW_QuestEN[59958] = { title = "A Paladin's Service", description = "While you were destroying that army of the undead, the ghost of a paladin approached me... and asked for you!\n\nThey floated over to the ruins nearby.\n\nYou should see what this ghost wants. I do not know much about the Light... but I know not to ignore a ghost.", objectives = "Speak with the ghost paladin.", progress = "Greetings, <name>. It is good to finally see you.", completion = "Those who serve the Light will know its blessing. Accept this gift, <class>.\n\nCall upon it when your strength fails and when hope seems lost. The Light will protect you from harm." }
WordHunterWoW_QuestEN[59959] = { title = "The Brand Holds the Key", description = "<Darion is unresponsive. The cage is locked, and doesn't appear easily broken.\n\nPerhaps the holder of the key is this \"Brand\" he mentioned.>", objectives = "Find the key to free Darion.", progress = "Are you willing to listen to my proposition?", completion = "My, my. Today certainly has been full of surprises!\n\nNow, mortal, I'm curious what has brought you back to the Maw." }
WordHunterWoW_QuestEN[59960] = { title = "A Cooling Trail", description = "<The amulet burns hot in your hand. The magic that runs through it tugs slightly at your grip.\n\nPerhaps the enchantment spoken of by Bolvar can now be used to find Mograine.>", objectives = "Use the Amulet of the Horsemen to find Darion Mograine.", completion = "<Darion is trapped within the cage. He appears unconscious.>" }
WordHunterWoW_QuestEN[59961] = { title = "A Priest's End", description = "You're a trained priest, right {name}? I have a grim request for you.\n\nI passed by some injured members of the first expedition. I did what I could... but they were too far gone.\n\nCan you perform a ritual to lay them to rest? \n\nTheir spirits deserve to rest with honor.", objectives = "Find the corpses of the first expedition recruits.", completion = "Dere be no time ta talk. Dese recruits barely be alive!\n\nI gonna teach ya how ta cast resurrection. It be da only ting dat can bring dem back.\n\nYa best be a wise <class>, 'cause dis be a powerful spell ta be knowin'." }
WordHunterWoW_QuestEN[59962] = { title = "Hope Never Dies", description = "So, mortal, you are here looking for someone. Well it just so happens that, clever as I am, it's quite possible I know where they are.\n\nAllow me to propose a trade. That amulet you carry... it holds an interesting power.\n\nYou give me the amulet, and I will help you find this Maldraxxi baron.\n\nAnd then you will leave. I don't mean to be rude, but I really prefer to keep a low profile.\n\nAllow me to speed things along.", objectives = "Follow Ve'nari.", completion = "Keep up. We have little time." }
WordHunterWoW_QuestEN[59965] = { title = "Resurrecting the Recruits", description = "Ya gotta cast Resurrection on dese recruits ta be savin' dem.\n\nDa necrotic magic of dis place be tuggin' at deir souls.\n\nQuickly, now!", objectives = "Cast Resurrect on 3 First Expedition Recruits", progress = "Go on, use ya resurrection ta help de recruits.", completion = "Ya got da mojo ta be a great <class>. \n\nMe task be done. It be time for me ta see da Other Side." }
WordHunterWoW_QuestEN[59966] = { title = "Delving Deeper", description = "It's quite a thrill to have a mortal for a business partner! The amulet really is intriguing.\n\nWhat's that? Oh yes, that baron you're searching for...\n\nWell it so happens that I learned of a Maldraxxi warlord being held in the lower courtyard of Perdition Hold. As you might guess by the name, it's not the most charming of places.\n\nI would prefer to avoid the attention of the Jailer's forces. Fortunately, I have just the thing.\n\nGive the word, and I will conceal us from the Mawsworn.", objectives = "Follow Ve'nari to Perdition Hold.", completion = "My father... Alexandros Mograine. The Ashbringer.\n\nI... never expected to see him again." }
WordHunterWoW_QuestEN[59967] = { title = "A Rogue's End", description = "Shuja mentioned a rogue from the first expedition. Goes by Drizza Sidestabber.\n\nDrizza was last seen heading northwest... towards a large bear's den.\n\nNone of us can sneak around like you. See if you can find Drizza and bring her back here.", objectives = "Use Stealth to sneak around and find the first expedition's rogue.", progress = "Did you get the roots? Make sure that bear is far away when you pick them.", completion = "Here's the secret to making these poisons. It took me a long time to figure it out.\n\nNow that you know how to make 'em, you can kill that ogre for me!" }
WordHunterWoW_QuestEN[59968] = { title = "The Deadliest of Poisons", description = "You've got the poison. Now you gotta to take out that ogre. Goon's name is Gutgruk the Tough.\n\nHe usually patrols around the citadel. I betcha it's lookin' for your expedition right now!\n\nPoison your blades, then take that monster down. Show him he ain't so tough!", objectives = "Kill Gutgruk the Tough.", completion = "Drizza Sidestabber's died with honor. She will be remembered as a hero of the Horde.\n\nAnd now you know how to make poison. Just... keep it away from me." }
WordHunterWoW_QuestEN[59969] = { title = "A Shaman's Duty", description = "Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman.\n\nThe necrotic energies of this island have ensnared my pack. I need your aid to free them.\n\nGather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke.\n\nThen you will be able to see my packmates and release them from their bonds.", objectives = "Gather 4 ghost blossoms to burn on the campfire in order to rescue the ghost wolf's companions." }
WordHunterWoW_QuestEN[59970] = { title = "A Warlock's Bargain", description = "While scouting the area, I saw an open portal near the bridge up the hill. That does not bode well for any of us.\n\nIt seemed like another warlock tried to seal the portal, but failed.\n\nI know you dabble in such... affairs. Perhaps you could put your knowledge to good use and close that portal.", objectives = "Investigate the first expedition warlock's corpse.", progress = "I see you have the grimoire that enacted the binding ritual.", completion = "Our bargain has been struck.\n\nCall upon me from the Void, and I will answer.\n\n<The voidwalker looks at the goblin's corpse.>\n\nLet us see if you are stronger than those who came before you." }
WordHunterWoW_QuestEN[59971] = { title = "A Warrior's End", description = "Hail, {name}! You've grown stronger since we sparred on the boat. You may one day become a warrior of great renown!\n\nSpeaking of which...\n\nI encountered a ghost on the bridge to the north that demands to meet a true warrior.\n\nPerhaps you can see what it wants.\n\nIt did not seem hostile. It might even be willing to help us.", objectives = "Speak with the strange ghost at the Darkmaul Bridge.", completion = "You are no hero of myth and legend... but I see potential within you.\n\nStand still, and I shall share with you my mightiest technique.\n\nAnd then I implore you to end my suffering." }
WordHunterWoW_QuestEN[59972] = { title = "Hjalmar's Final Execution", description = "You now wield my most powerful skill, young warrior. \n\nNow use it to finish me! These ogres trapped my spirit here long ago for daring to defy them.\n\nOnly through a glorious death will I finally be allowed to rest. \n\nIt is the only way I will see my brothers and sisters in the afterlife.", objectives = "Slay Hjalmar the Undying. You must use Execute in order to truly kill him.", completion = "You seem stronger! If only all ghosts were as honorable as that one..." }
WordHunterWoW_QuestEN[59973] = { title = "A Bond Beyond Death", description = "Since crossing into the Shadowlands, I've been so focused on our mission that I never even considered the souls of my family being here somewhere.\n\nWhatever this realm called Maldraxxus is, I hope it is worthy of my father's service!\n\nWe must free him, {name}. There is... much I need to say to him.", objectives = "Protect Darion while he frees Alexandros.", progress = "Every moment spent here tears at one's soul.", completion = "I cannot thank you enough, <name>." }
WordHunterWoW_QuestEN[59974] = { title = "A Soul Saved", description = "Vyraz... all this time...\n\nThis cannot stand, {name}. We must avenge Krexus and cut him down!\n\nHe must have sent you to the Maw expecting that you would never return. He underestimated you. A fatal mistake.\n\nGo with Mograine and claim Vyraz's head. I will warn our forces at the Seat of the Primus.", objectives = "Meet Alexandros Mograine at the House of the Chosen in Maldraxxus.", completion = "I cannot allow this wound to fester any longer. I will burn it closed here and now!" }
WordHunterWoW_QuestEN[59975] = { title = "To Darkmaul Citadel", description = "The last remaining survivor is being held within the ogre's citadel.\n\nCrenna and Herbert have a plan to get us inside.\n\nA small group of us will gather up north. You're coming with us.\n\nIf we fail here, the ogres will gain control of Kalecgos and his powerful blue dragon magic.", objectives = "Meet Thrall outside of Darkmaul Citadel.", completion = "Darkmaul Citadel looms ahead. \n\nHerbert's proposed plan is... unconventional." }
WordHunterWoW_QuestEN[59978] = { title = "Right Beneath Their Eyes", description = "We need to get into Darkmaul Citadel, rescue the last survivor, and stop Gor'groth.\n\nHerbert and Crenna are going to cast a spell to make you look an ogre... and then you're going to take us in as your \"prisoners.\"\n\nSpeak with Herbert when you're ready.", objectives = "Have Herbert Gloomburst transform you into an ogre, then scout the nearby ogre citadel.", completion = "There may just be a way that we can save Warlord Thunderwalker." }
WordHunterWoW_QuestEN[59979] = { title = "Like Ogres to the Slaughter", description = "This is worse than I thought. The ogres were counting on us to stage a rescue attempt.\n\nIt seems that they plan to attack our camp while they near completion of the ritual.\n\nWe can't let that happen. Crush the ogres! Show them the strength of the Horde!", objectives = "Slay 8 ogres within Darkmaul Citadel.", progress = "Show the ogres no mercy!", completion = "That should weaken the ogres long enough for us to put an end to their plotting." }
WordHunterWoW_QuestEN[59980] = { title = "Catapult Destruction", description = "As we snuck in here I noticed the ogres erecting catapults to destroy our camp.\n\nCork must have anticipated this and gave me several explosives to use, \"just in case\".\n\nTake these explosives and blow up those catapults!\n\nAlso don't shake them too hard.", objectives = "Blow up 4 catapults within Darkmaul Citadel.", progress = "Make sure to give the explosives a nice wave goodbye when you use them on the catapult. \n\nIt'll make them feel appreciated before they explode.", completion = "Good work! You didn't happen to save any of those explosives, did you?\n\n...I didn't think so. Oh well! I have plenty of other ways to blow up my enemies." }
WordHunterWoW_QuestEN[59981] = { title = "Controlling their Stones", description = "Warlord Thunderwalker won't last much longer. Soon, his life essence will be completely drained. \n\nGor'groth mentioned that they are keeping him captive through the use of ward stones.\n\nI want you to recover these ward stones and bring them here so we can release Thunderwalker.", objectives = "Recover the Ward Stones from Jugnug, Wug, and Grunk, then use them to free Warlord Thunderwalker.", progress = "These were the ward stones used to bind me? Perhaps even the ogres have heard tale of my strength!", completion = "Thank you for the aid, but saving me will not stop the ogres. \n\nThey already have enough life essence to complete the ritual!" }
WordHunterWoW_QuestEN[59984] = { title = "Dungeon: Darkmaul Citadel", description = "Gor'groth seeks to use shadow magic to gain control of Kalecgos, the aspect of the Blue Dragonflight.\n\nHe's collected enough life essence to attempt to finish the ritual. I do not know what will happen, but we cannot let him complete it!\n\nGor'groth will not stop until he is slain!\n\nYou must storm the citadel and slay Gor'groth before he can complete his ritual!\n\nI would charge in beside you, were I not still recovering from his dark magic.", objectives = "Complete the dungeon, \"Darkmaul Citadel\".", completion = "Victory for the Horde! It is time we returned to Orgrimmar as heroes and conquerors." }
WordHunterWoW_QuestEN[59985] = { title = "An End to Beginnings", description = "You've done well here, {name}. Kalecgos and Wrathion are planning to continue on to the Dragon Isles.\n\nI must return to Orgrimmar. This shadow magic is concerning... and requires that I look into it more.\n\nTalk with Kalecgos. He'll get you to the Dragon Isles and inform you about what's going on there.", objectives = "Speak with Kalecgos to travel to the Dragon Isles.", completion = "It's good to be back in Orgrimmar. \n\nI must report to the warchief, but I know what you can do in the meantime..." }
WordHunterWoW_QuestEN[59986] = { title = "Wide Worlds of Catalysts", description = "Catalysts come in different forms, for now we shall introduce you to two of them.\n\nSpeed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover.\n\nQuality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. \n\nReturn to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.", objectives = "Identify the different types of Catalysts" }
WordHunterWoW_QuestEN[59994] = { title = "Trust Fall", description = "Let us ponder the meaning of the Archivist's last words: \"Victory only belongs to those brave enough to fall.\"\n\nHmm. It could be reference to the Volume of Victory. That is the most well-known of all the writings said to be kept in this tower.\n\nThat book is priceless, {name}. I mean that almost literally. We must do whatever is necessary to find it!\n\nBut, uh... What do you suppose \"brave enough to fall\" refers to?", objectives = "Jump from the tower.", progress = "You have it?", completion = "This is it... the Volume of Victory! The single most important compendium of Maldraxxus military history ever assembled.\n\nIt must be mine! Uh, ours. I mean ours!" }
WordHunterWoW_QuestEN[59999] = { title = "Rebirth of the Grove", description = "Though not yet withered, the conservatory wilts amidst the drought. This grove is not what it once was.\n\nAs warden, I bear the twin burdens of guilt and shame. Fate saw to this grove's decay and my failure to prevent it.\n\nBut fate has also seen to hope in its renewal. Hope in you.\n\nI beseech you, mortal, to seek out Zayhad in the Heart of the Forest and restore what has been lost.\n\nFor as the wounded spirits must be reborn, so too must this grove.", objectives = "Upgrade the Queen's Conservatory to Tier Two.", completion = "The forest sings in gratitude, Maw Walker. \n\nMy Queen is wise to place her faith in you." }
WordHunterWoW_QuestEN[60001] = { title = "[NYI] The Sword in the Stone", description = "Mortal! \n\nKnow this: only one who is deemed worthy may draw me from this stone.\n\nHowever, since you are clearly not that, and I really am bored, I want you to go find some dredgers to break the stone apart so you can carry me with you.\n\nGet to it.", objectives = "" }
WordHunterWoW_QuestEN[60003] = { title = "A Valiant Effort", description = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.\n\nWhile we managed to escort many to safety, there are some who were wounded in the chaos.\n\nSearch the training grounds for any survivors from the onslaught.\n\nWe need all the help we can get.", objectives = "Rescue 6 Wounded Valiants from the training grounds.", progress = "Any word on survivors?", completion = "We'll see to it they receive proper attention." }
WordHunterWoW_QuestEN[60004] = { title = "A Valiant Effort", description = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.\n\nWhile we managed to escort many to safety, there are some who were wounded in the chaos.\n\nSearch the training grounds for any survivors from the onslaught.\n\nWe need all the help we can get.", objectives = "Rescue 6 Wounded Valiants from the training grounds.", progress = "Any word on survivors?", completion = "We'll see to it they receive proper attention." }
WordHunterWoW_QuestEN[60005] = { title = "Imminent Danger", description = "The Temple of Courage must not fall!\n\nAll kyrian learn to fight in its hallowed halls. Not only to protect Bastion, but to ensure their own safety when retrieving souls from across the veil. \n\nTravel there at once. Seek out Thanikos, the Paragon of Courage's loyal hand.", objectives = "Seek out Thanikos at Xandria's Vigil.", completion = "Not quite the army I hoped would come, but I welcome your blade by my side." }
WordHunterWoW_QuestEN[60006] = { title = "Now or Never", description = "In a fair fight our warriors could stand against countless swarms of these Maldraxxi.\n\nThis was no fair fight, outsider.\n\nThey came without warning. Without cause. We were caught unprepared.\n\nThey must not be allowed to encroach any further. This stops here.", objectives = "Reclaim Xandria's Vigil.", progress = "We will not go down without a fight.", completion = "We have bought a staging ground, but much remains to be done." }
WordHunterWoW_QuestEN[60007] = { title = "Stay Scrappy", description = "I can rebuild this colossus's core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise.\n\nReplacements are in order!\n\nI require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom!\n\nI'll take care of the rest. Quickly, now!", objectives = "Recover the Anima Conflux, Eternity Plating, and Archonic Resonator.", progress = "Do you have the parts?", completion = "That was fast! Well done, well done indeed!" }
WordHunterWoW_QuestEN[60008] = { title = "Rip and Tear", description = "We will show these Maldraxxi insurgents the price for their betrayal.\n\nThe northern grounds have been taken by the House of Constructs, home to Maldraxxus' most resilient warriors.\n\nThey have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.", objectives = "Slay House of Constructs forces.", progress = "This is what must be done.", completion = "You fight with the poise of a true kyrian, outsider." }
WordHunterWoW_QuestEN[60009] = { title = "Fight Another Day", description = "Some of our brethren are still alive in there!\n\nWhile many were lost in the initial assault, they seem keen on taking any survivors prisoner. I know not what they intend, but given their mastery of corpses we must assume the worst.\n\nSome have already been taken to their necropolis above, but others remain in cages on the ground. Free all you can.", objectives = "Save 6 captured kyrian.", progress = "The kyrian leave none behind on the field of battle.", completion = "You are a true ally, outsider. Thank you." }
WordHunterWoW_QuestEN[60013] = { title = "Leave it to Mnemis", description = "I have deduced by the urgency in your collective voices that you wish to leave.\n\nI will expedite your exit. There is a transport pad in the antechamber. I will ensure that the chamber is sealed once again on your exit.\n\nPlease accompany me.", objectives = "Use the Transport Pad in the Vault of the Archon.", completion = "We must hurry. The Archon must know what transpired here." }
