WordHunterWoW_QuestEN[60041] = { title = "Build-A-Bomination", description = "We need to get to work, every soul here needs a body.\n\nWe have the parts to build a body for Chordy. Chordy is a great scavenger, rebuilding him could allow us to find more construct parts easier.\n\nWould you help me to rebuild him?", objectives = "Help Rathan to create a new construct body for Chordy.", progress = "It will be nice to have Chordy back to his old self!", completion = "We were successful, Chordy is whole again!" }
WordHunterWoW_QuestEN[60042] = { title = "May I Take Your Order?", description = "Chordy is just the first success, there will be many more!\n\nAs free souls show up here, speak with them and take their requests for new construct bodies. We'll soon have lots of new constructs to work on!", objectives = "Take the construct requests from the souls present.", completion = "So many powerful souls, we must get to work immediately." }
WordHunterWoW_QuestEN[60043] = { title = "Justice from Above", description = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts.\n\nThe Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once.\n\nI shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", objectives = "Destroy 5 Maldracite Cores.", completion = "You have done a great service here." }
WordHunterWoW_QuestEN[60044] = { title = "Charging The Blade", description = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest one, but conventional weapons do nothing against their imbued hides.\n\nThankfully, I have an idea.\n\nYour runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", objectives = "Charge your runeblade by killing enemy constructs in the Stitchyard.", completion = "This may not work... but it may also be our only chance at victory." }
WordHunterWoW_QuestEN[60048] = { title = "Stitching Time", description = "With the proper resources we can build a force of construct warriors greater than anything ever seen in the Shadowlands.\n\nVisit Arkadia Moa and see if you can secure the resources we need.", objectives = "Upgrade Abominaton Factory to Tier 1", completion = "You have acquired all the resources we needed." }
WordHunterWoW_QuestEN[60049] = { title = "At Your Service", description = "I suppose I should commend you. You certainly exceeded my expectations.\n\nRathan can be sentimental, but he is right. This place can be our new home, and here we can construct new bodies for the souls you freed.\n\nInform Baroness Draka that she has earned the allegiance of Princess Emeni and the constructs of Butchers Block! We stand ready for whenever she has need of our strength.", objectives = "Check in with Baroness Draka back in the Seat of The Primus.", completion = "Well done. Emeni and her constructs will make for powerful allies.\n\nThey will, however, need your assistance to reach their full potential." }
WordHunterWoW_QuestEN[60050] = { title = "Trouble on the Western Front", description = "The Ashbringer and your fellow Maldraxxi need reinforcements at the western gate. They are barely holding on!\n\nXandria and my kin will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks, we cannot hope to achieve victory.", objectives = "Fly with Kynthia to report to Alexandros at the Stitchyard.", completion = "I am glad Kynthia found you so quickly." }
WordHunterWoW_QuestEN[60051] = { title = "A Master of Their Craft", description = "If we wish to get a travel network up and running, we'll need a master mirror maker in our employ. \n\nI've heard rumors that one such tradesman has landed himself in the Ember Ward. I am sure it won't take much cajoling to convince him to join our ranks. \n\nHead back into the Ember Ward and find this master mirror maker.", objectives = "Find Laurent in the Ember Ward.", completion = "Please do excuse my appearance. I assure you, this is not my normal attire." }
WordHunterWoW_QuestEN[60052] = { title = "Double Tap", description = "The House of Rituals occupies the southern half of the temple. Unlike the constructs, their key advantage in battle is their endless army of risen fighters.\n\nThankfully, the Archonic Resonator we recovered will take care of it.\n\nAs we carve our way through their forces, blast their corpses with the resonator. Its energy will sunder their souls, preventing them from being raised to fight again.", objectives = "Use the Archonic Resonator to sunder 12 House of Rituals soldiers' corpses.", progress = "We must ensure our foe stays dead, or our efforts will be futile.", completion = "The Resonator is working at full capacity and our foes are dispatched. Excellent." }
WordHunterWoW_QuestEN[60053] = { title = "Clear as Crystal", description = "This Anima Conflux is completely drained of anima! Just a heavy hunk of metal!\n\nNot your fault, of course. Not at all. But we need to charge it!\n\nThe Maldraxxi have extractors. Big green crystals, can't miss them. They're using it to drain anima from fallen kyrian. Very bad!\n\nWe can use them to charge the conflux, then our colossus here will be functional again!", objectives = "Drain Necrotic Extractors to empower the Anima Conflux.", completion = "Not fully charged, but close enough! May have to disable a few safety features..." }
WordHunterWoW_QuestEN[60054] = { title = "The Final Countdown", description = "If the necromancer's brood descends upon us fully before the colossus is charged, we will perish. There is no question.\n\nWe must keep his attention until Mikanikos's work is complete.\n\nHe believes that the day is already won -- that we are pawns to be toyed with. We can use his hubris to our advantage to buy precious seconds.\n\nMay it be enough.", objectives = "Delay Amarth the Harvester until the Colossus is fully charged.", completion = "Our only move now is forward, outsider." }
WordHunterWoW_QuestEN[60055] = { title = "A Time for Courage", description = "I know not what awaits us across the chasm, outsider. By the Archon's grace I hope that my Paragon yet lives, but I fear the worst.\n\nWe will face this great unknown together, as we have the rest of Maldraxxus's horrors. To be kyrian is to follow the path, no matter how dire the circumstances.\n\nWhatever happens, know that you have earned my undying respect this day.", objectives = "Confront Amarth the Harvester with Thanikos.", completion = "Thanikos... is gone... isn't he." }
WordHunterWoW_QuestEN[60056] = { title = "Follow the Path", description = "Maldraxxus must answer for their crimes against Bastion. There shall be justice!\n\nLet us go to Oribos and speak with the Tal-Inara, the Honored Voice. We will tell her what has transpired this day. Tell her that the kyrian will not stand idle against this aggression.\n\nArtemede will inform the Archon. My brothers and sisters will surely prepare for war.\n\nThat must not come to pass.", objectives = "Inform Tal-Inara in Oribos of Maldraxxus's attack on Bastion.", progress = "You looked troubled, outsider. What ails your mortal frame?", completion = "I know why you have come. This kyrian has explained much." }
WordHunterWoW_QuestEN[60057] = { title = "Necrotic Wake: A Paragon's Plight", description = "Xandria, the mighty Paragon of Courage, is the finest warrior among all the ascended. But even she may be overwhelmed by the strongest of Maldraxxus' forces.\n\nYour fate is intertwined with hers, now. You must gather your allies and plunge into the Necrotic Wake to ensure both Amarth and Nalthor do not make it back to the safety of their realm.\n\nMay the Archon guide your blade into their hearts.", objectives = "Defeat Amarth the Harvester and Nalthor the Rimebinder in the Necrotic Wake.", completion = "Word has spread throughout Bastion of your actions at the Temple of Courage, <name>. Xandria sent word that you were to be amply rewarded for your heroism." }
WordHunterWoW_QuestEN[60058] = { title = "Conquest's Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[60060] = { title = "Mirror Attunement: Pridefall Hamlet", description = "Work has been completed on a mirror that will allow travel between Sinfall and Pridefall Hamlet. However, it has yet to be attuned.\n\nThe attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", objectives = "Enter the mirror in Pridefall Hamlet.", completion = "Well done! The mirrors have been attuned and can be used at your leisure." }
WordHunterWoW_QuestEN[60061] = { title = "Tough as Silk", description = "We are the heart of silk production in Ardenweald, but we can't do our work! \n\nOur grove has been completely taken over by spriggans and these strange shapeshifting... things.\n\nThe silkstriders who spin the silk are very delicate creatures. They need peace and calm, and a little music to keep them happy! But with all these monsters all over the place, they're super stressed out.\n\nPlease, can you get in there and eliminate these hooligans, and see if you can help get us up and running again?", objectives = "Slay attackers, save caretakers, and hatch silkstrider larvae in the Gossamer Cliffs.", progress = "We need to get silk production running again, for Ardenweald!", completion = "Thank you! We are so grateful for your help with slaying those cretins, and rescuing our people." }
WordHunterWoW_QuestEN[60062] = { title = "The Shattered Harp", description = "<The harp lies broken, with pieces missing.\n\nPerhaps you can find more pieces, and get someone to repair it.>", objectives = "Find pieces of the broken harp.", progress = "I lost my harp! It was taken and broken by those terrible creatures.", completion = "You found my harp! And the missing pieces. Just one moment, and I can fix it." }
WordHunterWoW_QuestEN[60063] = { title = "A Song for Silkstriders", description = "There, the harp is fixed. I am too injured to take it to the silkstriders, but you are strong. You can help them.\n\nOur precious silkstriders are all across the cliffs. When you find one, play the harp for them, and they will give you fresh silk. Make sure that there is nothing nearby to stress them out first though!\n\nIf you find yourself in need of a way to move about swiftly, just take a Silk Shooter there, next to me. Aim it where you want to go, and it will shoot silk to pull you there!", objectives = "Collect silk from the silkstriders by playing the harp for them.", progress = "Were you able to help the poor silkstriders calm down, and get their silk?", completion = "Wonderful job! I'm sure the silkstriders appreciated the song you played. You look like someone who appreciates the fine arts." }
WordHunterWoW_QuestEN[60064] = { title = "Save Ol' Gertie", description = "We have to find Ol' Gertie! She is the broodmother of the silkstriders, and is our most reliable producer. We cannot lose her.\n\nBut I cannot get to her and see if she is all right. She is usually at the top of the cliffs, at the highest point. Can you get up there, and make sure that she is safe?\n\nIf she is not... then may justice fall swift and hard on the perpetrator.", objectives = "Slay Noisul of Many Faces", progress = "Have you found Ol' Gertie? Is she safe?", completion = "<Ol' Gertie lies dead of fear. \n\nBut this little silkstrider larvae wiggles happily at you.>" }
WordHunterWoW_QuestEN[60065] = { title = "Thread of Hope", description = "<Gertie Jr. looks up at you with hope. Perhaps you can help get her to safety.>", objectives = "Deliver Gertie Jr. to Lillythistle.", completion = "Ol' Gertie is... dead?\n\nBut you found her baby! Thank you, thank you so much for bringing her safely out of there!" }
WordHunterWoW_QuestEN[60066] = { title = "Silk for Ardenweald", description = "It's clear that we may not be able to consistently supply Ardenweald with silk. But there is something that will help.\n\nTake Gertie Jr. and the silk you collected from the other silkstriders back to the Heart of the Forest. There, she will be safe, and perhaps grow up into a silkstrider as grand and beautiful as her mother!", objectives = "Bring Gertie Jr. to the Heart of the Forest.", completion = "Thank you for this silk! But... I see you brought something extra as well.\n\nThis little silkstrider will be safe now. I swear it." }
WordHunterWoW_QuestEN[60067] = { title = "Pursuit of Justice", description = "Draka stands ready to unleash the power of the necropolis upon Gharmal. We need only buy her time to focus its weaponry.\n\nWhat we do now, we do for all of us. Bastion and Maldraxxus have both lost much to these fiends.\n\nGharmal will not be defeated easily... but united, our forces will finally bring them to justice!", objectives = "Defeat Margrave Gharmal.", completion = "Our fallen finally know justice." }
