WordHunterWoW_QuestEN[60226] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "Speak to Kalisthene.", completion = "You are worthy of Bastion's grace, <name>. May it serve you well." }
WordHunterWoW_QuestEN[60227] = { title = "TBD Soulguard Torch", description = "TBD", objectives = "TBDTBDYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[60228] = { title = "Sinstone Delivery TBD", description = "TBD", objectives = "TBDTBDYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[60229] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "Speak to Kalisthene.", completion = "You are worthy of Bastion's grace, <name>. May it serve you well." }
WordHunterWoW_QuestEN[60230] = { title = "More the Merrier", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "Take the construct requests from the souls present.", completion = "So many souls, we have much work to do!" }
WordHunterWoW_QuestEN[60231] = { title = "State of Decay", description = "", objectives = "" }
WordHunterWoW_QuestEN[60236] = { title = "RSVP: Cryptkeeper Kassir", description = "I would be most honored to attend Prince Renathal's Ember Court.\n\nI prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties.\n\nHowever, the Lord Chamberlain's goons have stolen it once more.\n\nThey hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring.\n\nIt may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.", objectives = "Collect Atonement Crypt Keys from venthyr around the Halls of Atonement and open Atonement Crypts until you find the Lost Cryptkeeper's Ring.", progress = "Desired objects tend to be in the last place we look, do they not? Perhaps we shall be fortunate this time.", completion = "My most gracious gratitudes to you, Maw Walker!\n\n<Cryptkeeper puts the ring into his pocket and pats it comfortably.>\n\nNow I may attend the Ember Court in my finest appearance.\n\nI do hope the Accuser will be performing rituals there..." }
WordHunterWoW_QuestEN[60237] = { title = "Old Stomping Grounds", description = "Once, long ago, I journeyed to Ardenweald to assist in putting down a threat now long forgotten.\n\nI remember that while there, I saw small creatures taking tiny clusters of anima--animacones, the fae called them--and buried them under the soil.\n\nIf those clusters are still there, we must gather them for ourselves!\n\nI should be able to unearth any of the animacones we encounter. Let's go hunt for them!", objectives = "Collect 15 Lost Animacones. Use Toothpick's World Shaker to unearth them.", completion = "Thank you, Maw Walker. This extra anima will tremendously aid our efforts." }
WordHunterWoW_QuestEN[60238] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[60239] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[60242] = { title = "Trading Favors: Necrotic Wake", description = "We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others.\n\nSo let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable.\n\nI hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?", objectives = "Obtain Nalthor's Phylactery Instructions from Nalthor the Rimebinder in the Necrotic Wake.", progress = "Have you found any objects of interest?", completion = "Ah, quite a find, we rarely get a glimpse into the mechanisms by which the House of Rituals enact their dark designs. I am eager to delve into this tome, purely in the interests of knowledge of course.\n\nYou may choose from some of our procured items as a reward." }
WordHunterWoW_QuestEN[60243] = { title = "Trading Favors: Sanguine Depths", description = "The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us.\n\nIt would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.", objectives = "Obtain a Medallion of Orientation from General Kaal in the Sanguine Depths.", progress = "What have you brought before me?", completion = "Yes, yes this is exactly what I was speaking about. The foolish generals of Revendreth would use this medallion to orient themselves during travel in unknown areas, but their ambitions were small.\n\nFor my people, who have traveled beyond the known lands, such a thing is invaluable when attempting to chart a way to return.\n\nWe will make great use of this, it is good to see it returned. Here, a prize for you." }
WordHunterWoW_QuestEN[60244] = { title = "Trading Favors: Halls of Atonement", description = "The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth.\n\nHow they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel.\n\nThey keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.", objectives = "Obtain the Tome of Dredger Alchemy from Lord Chamberlain in the Halls of Atonement.", progress = "Have you found something of interest?", completion = "A tome from Revendreth? Yes, let me see.\n\nIt chronicles the alchemical formulae necessary to form the dredger pools, and various recipes for forming and utilizing the little creatures. They are quite a curiosity, as much a minion as a reagent.\n\nI will gladly take this off of your hands in exchange for a trade. Here, choose." }
WordHunterWoW_QuestEN[60245] = { title = "Trading Favors: De Other Side", description = "Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. \n\nA pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities.\n\nWe would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.", objectives = "Obtain a Golden Death Mask from Mueh'zala in De Other Side.", progress = "You have the stench of death about you.", completion = "Oh, this is quite a find, is it not? Something from De Other Side. We so rarely get to glimpse such things, I shall study this with interest. It would appear to be from a forgotten, primitive race that worshipped Mueh'zala.\n\nA reward, of course, is in order. Make your choice." }
WordHunterWoW_QuestEN[60246] = { title = "Trading Favors: Tirna Scithe", description = "The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest.\n\nOr perhaps, mhm, you do? For some, that is entertainment.\n\nIt is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?", objectives = "Obtain an Engorged Gorm Larva from Tred'ova in the Mists of Tirna Scithe.", progress = "Have you completed the task?", completion = "Oh, what is this? It is so bulbous and squirming, it must be close to the next molting. I am something of an amateur gorm-breeder myself, and will find a proper place to raise this one. \n\nYou may trust that I intend to destroy no worlds, I give you my word.\n\nNow, I must tend to him, gather something from our stocks on your way out." }
WordHunterWoW_QuestEN[60247] = { title = "Trading Favors: Theater of Pain", description = "Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. \n\nThose of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed.\n\nI trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.", objectives = "Obtain a Champion's Coin from Mordretha in the Theater of Pain.", progress = "Six, seven, eight... oh, yes? Do you have an offer of trade? I have much more inventory to catalogue.", completion = "Quite interesting, these coins are only granted to champions of the Maldraxxus arena after a certain amount of time in service. Purely ceremonial, they are worthless to most, but priceless to those that value ceremony. \n\nYou may take something with you in compensation." }
WordHunterWoW_QuestEN[60248] = { title = "Trading Favors: Plaguefall", description = "Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools.\n\nYou would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well.\n\nI am sure she has little use for these possessions in her current state.", objectives = "Obtain one of Stradama's Lost Ledgers from Margrave Stradama in Plaguefall.", progress = "Oh, it is you again.", completion = "Oh my, this is quite a find. It is a catalogue of some of Stradama's procured objects, hidden away within her pools of plague. We will make good use of this, to be sure. \n\nChoose something to take with you, you have earned it." }
WordHunterWoW_QuestEN[60249] = { title = "Trading Favors: Spires of Ascension", description = "The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation.\n\nWe would like to know more about their travels to the realms beyond. \n\nSurely one of them has brought something back from another land? They are, after all, so very interested in memories.", objectives = "Obtain a Strange Doll from Devos, Paragon of Doubt in the Spires of Ascension.", progress = "How may I assist you?", completion = "A strange bauble, likely from another world. Yet, why would the paragon have brought this with her? \n\nPerhaps when carrying the soul of a child, as a reminder of something she had thought lost within herself? I will ponder this.\n\nYou may choose a reward from our stores." }
WordHunterWoW_QuestEN[60250] = { title = "A Valuable Find: Theater of Pain", description = "The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. \n\nWith the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record.\n\nAs such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles.\n\nI would very much like to see such an item.", objectives = "Obtain the Ring of Otherworldly Metal from Mordretha in the Theater of Pain.", progress = "Were you victorious, or have you come to tend to your wounds?", completion = "The fools, giving away an object such as this as a mere trinket to be used in battle. Do they not know of its significance? Clearly not.\n\nLet me explain.\n\nThere is much we do not understand about the workings of this world. This city, Oribos, is made of a strange ore that we have not found anywhere else. Who made this place, and why?\n\nRelics of similar make like this are all that we have to tie together the threads of mystery.\n\nWe thank you for this gift. Please, take a treasure." }
WordHunterWoW_QuestEN[60251] = { title = "A Valuable Find: Plaguefall", description = "Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor.\n\nIt is possible, even probable, that this was the cause of the fate that befell the House of Plagues.\n\nI do not need to tell you how valuable such a rarity would be to us, do I?", objectives = "Obtain A Slimy Correspondence from Margrave Stradama in Plaguefall.", progress = "Yes? I am quite busy here.", completion = "I can only decipher a few words of this missive, give me a moment.\n\nIt appears to be a warning from the Margrave to another lord of Maldraxxus, or perhaps another place.\n\nI see mention of the Primus, and discussion of his fate. Or someone else's? It is hard to tell. It appears to point to a location, but I cannot understand the description of the location.\n\nThis may be more valuable than you know for the fate of the Shadowlands. Choose a reward, I will continue my work on this." }
WordHunterWoW_QuestEN[60252] = { title = "A Valuable Find: Spires of Ascension", description = "You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom.\n\nThis temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away.\n\nWe have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.", objectives = "Obtain the Fading Memory Glass from Devos, Paragon of Doubt in the Spires of Ascension.", progress = "You have the look of one who has something to say.", completion = "This memory glass is old, very old. It may be the memory of a soul that moved on many years ago, we can never be certain. What is known is that the knowledge contained within can never be replicated, and soon, will never be seen again.\n\nI will immediately get to work in preserving what of it I can. I must ask that you take your leave now, please choose a suitably rich reward for your efforts." }
WordHunterWoW_QuestEN[60253] = { title = "A Valuable Find: Necrotic Wake", description = "Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. \n\nIt may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us.\n\nThere are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.", objectives = "Obtain \"The Origin of Death\" from Nalthor the Rimebinder in the Necrotic Wake.", progress = "What have you found?", completion = "What sort of tome is this? May I leaf through it for a moment?\n\nWell then, this is quite a find. It represents many years cataloguing everything Nalthor knew about the origins of our world. The many curiosities of this place, from Zovaal's domain in the Maw, to the function of this strange city of Oribos.\n\nIt is surmised that they all tie together.\n\nI shall devour it with glee. Come, you may take one of our most prized possessions for it." }
WordHunterWoW_QuestEN[60254] = { title = "A Valuable Find: Tirna Scithe", description = "The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us.\n\nOne of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.", objectives = "Obtain the Unusual Automaton Parts from Tred'ova in the Mists of Tirna Scithe.", progress = "You look as if you have been sifting through gorm carcass, or perhaps that is simply what you always look like?", completion = "We have found only a few objects similar to this in all of our time here, that I am aware of. Whether it belonged to a race of creature or automatons that came before us, or they still exist somewhere, we do not know.\n\nThe metallic fragments of this piece appear similar in design to the walls that surround us here in Oribos, yet we have never seen something like this moving around in the city.\n\nI will add it to the cache of relics related to these mysteries. Take a suitable reward with you." }
WordHunterWoW_QuestEN[60255] = { title = "A Valuable Find: De Other Side", description = "Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. \n\nBut we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity.\n\n<The light around Ta'lan's head flares brightly for a moment. He seems... excited?>\n\nSlay the foolish creature, bring me his secrets, I will reward you handsomely!", objectives = "Obtain a Strange Ritual Mask from Mueh'zala in De Other Side.", progress = "Have you brought something of interest?", completion = "This mask is similar in features to some of the automaton parts we have found in our time here in the Shadowlands. Perhaps it belonged to an ancient civilization? The information we have is scattered and incomplete.\n\nAny further pieces you may find of this sort will help us unravel these great mysteries. There seems to be a greater design to this place than we can see, yet so much of it eludes us.\n\nI will take it off of your hands, in exchange you make take one of our most valuable pieces." }
WordHunterWoW_QuestEN[60256] = { title = "A Valuable Find: Halls of Atonement", description = "The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind.  Often they will travel with a piece or two affixed to their garb as a show of status.\n\nNow, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. \n\nOf course.\n\nYet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.", objectives = "Obtain the Golden Orb of Energy from Lord Chamberlain in the Halls of Atonement.", progress = "How does the battle fare?", completion = "Now this is quite a find. A functional piece of the mysterious machinery that can be found around the Shadowlands.\n\nLook at how intricate the weaving of the golden orb is, how the energy seems to be contained from somewhere within, yet in a construct that is almost beyond imagining. What could have made such an object? Where are they now?\n\nWe shall begin to investigate with fervor. Do drop in if you find anything similar, and take a reward before you go." }
WordHunterWoW_QuestEN[60257] = { title = "A Valuable Find: Sanguine Depths", description = "General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls --  it is a bag of eclectic contents.\n\nContained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr.\n\nSuch a strange mystery must be solved. I will, of course, provide great compensation.", objectives = "Obtain an Ancient Broker Headpiece from General Kaal in the Sanguine Depths.", progress = "What information do you bring?", completion = "This... is not what I expected.\n\nIt is similar in appearance to our people, yet so very different. Are there others of our kind out there? Who are they, and where do they reside? Why have they not made contact with us? Or are they hiding themselves purposefully?\n\nIs this a history we knew but have forgotten? I have so many questions.\n\nI thank you for this, it is quite meaningful to us. Please, take a relic of power from the treasury." }
WordHunterWoW_QuestEN[60264] = { title = "Soul Survivor", description = "I knew when you helped me in the Etheric Vault, that you were a just and worthy leader.\n\nI have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance.\n\nPlease, build a construct for me, and allow me to help you as you have helped me.", objectives = "Take specifications for Miru's construct.", progress = "Are you willing to do this?", completion = "Miru is a very old soul and a survivor. We would be well aided by building him a construct." }
WordHunterWoW_QuestEN[60265] = { title = "Disrupting the Chain", description = "From the desk of the Tithelord:\n\nAll supply carriages must re-route to Stonevigil for collection assistance. Once complete, you may resume your regularly scheduled routes.", objectives = "Destroy the Darkhaven and Manor carriages in Stonevigil Overlook.", completion = "Well done.\n\nWe will bleed this miscreant \"Harvester\" dry." }
WordHunterWoW_QuestEN[60267] = { title = "Prison of the Forgotten", description = "<As you stare at the object you've found, you sense it may lead you to another part of this wretched tower.\n\nPerhaps Ve'nari may know more of its purpose.>", objectives = "Take the object back to Ve'nari.", progress = "<The lock appears to be sturdy, yet old and untouched. Dust has collected considerably upon it.>", completion = "<As you place the key into the device, it shudders for a moment and begins to unlock.>" }
WordHunterWoW_QuestEN[60268] = { title = "Deep Within", description = "Who... who are you? Have you come to extract more of my memories?\n\nI'm afraid there aren't any useful ones left, save for the memories of my imprisonment.\n\nOr perhaps you're here for something else?", objectives = "Speak with the prisoner and learn of his situation.", progress = "What do you want of me?", completion = "You could be the key to my freedom. Will you help me, mortal?" }
WordHunterWoW_QuestEN[60269] = { title = "Reawakening", description = "If you can retrieve my memories, I can help you. At least I believe I can.\n\nThen, perhaps, we can help each other.", objectives = "Find a stolen memory of the Runecarver.", progress = "Have you found what was taken from me?", completion = "It's been an age since I knew anything other than the contours of this hellish prison.\n\nThank you, mortal. Now to aid you." }
WordHunterWoW_QuestEN[60270] = { title = "A Damned Pact", description = "Yes... I begin to remember. Power. Power with a purpose. That is what I can offer.\n\nRunes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands.\n\nWell, one hand would suffice. Both would be better.\n\nFind a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.", objectives = "Discover a way to break the Runecarver free from his chains.", completion = "Breaking a prisoner's chains? I'm not sure I know how that could be done, unless...\n\nIt's dangerous, but I believe there may be a way." }
WordHunterWoW_QuestEN[60271] = { title = "A Grave Chance", description = "First you'll need a vessel to house anima and a way to expel it. I happen to possess such a device, which I'll be pleased to give to you.\n\nFor a price, of course.\n\nYou recall Zovaal's Cauldron, I trust? The denizens there were forged in unholy fire. Assuming their anima is of a similar nature, it should be able to melt even the metals of the tower.\n\nWith my device and their anima, I believe you can achieve your goal, Maw Walker.", objectives = "Purchase an Anima Supricifer from Ve'nari and recover 5 Molten Anima.", progress = "Were you able to acquire the anima?", completion = "Your success continues to impress, Maw Walker.\n\nThough I admit, such feats are becoming less unexpected as I come to know you more." }
WordHunterWoW_QuestEN[60272] = { title = "The Weak Link", description = "This ought to be enough to break the bonds that hold your newfound ally.\n\n<Ve'nari pauses for a moment.>\n\nBefore you do so, I offer a word of warning.\n\nNo creature imprisoned in that place should be trusted. Tread carefully, mortal. \n\nAfter all, it would be a shame to lose so valuable a business partner.", objectives = "Break the Runecarver free.", progress = "It's good to remember something new again.", completion = "Freedom. Of a sort. Yes... this is good. You have my thanks.\n\nWhat was it you wanted? Ah, power. Yes. Very well, then." }
WordHunterWoW_QuestEN[60274] = { title = "Trading Favors", description = "Welcome, friend. \n\nI can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes.\n\nThere are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. \n\nLet your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.", objectives = "Report to Finder Ta'sul in Oribos.", completion = "Ah, you must have been sent by Ta'rela. We have need of your services.\n\nTrust me, we will make it more than worth your while." }
WordHunterWoW_QuestEN[60275] = { title = "WANTED: Enforcer Kristof", description = "WARNING!\n\nShrouded patrols have increased throughout the Ember Ward. By order of Enforcer Kristof, all who are found near the asylum will be forced to endure the Light. \n\nUse extreme caution when venturing beyond our sanctuary. Even the shadows are not safe so long as Kristof remains in power.  \n\nA reward awaits whoever is able to rid the ward of this tyrant. \n\n- Dispatcher Raluca", objectives = "Find and slay Enforcer Kristof.", completion = "No tears will be shed over the loss of such a miscreant. Coin is not abundant in this ward, but take this, the owner is long gone and it will fetch a fair price." }
WordHunterWoW_QuestEN[60276] = { title = "WANTED: Summoner Marcelis", description = "Be advised:\n\nSummoner Marcelis and his cohorts are dabbling in dangerous magics. They are calling forth ashen elementals to ravage these Light-scorched lands. \n\nWe cannot let such acts continue. \n\nAny who can are urged to put an end to this madness. \n\n- Dispatcher Raluca", objectives = "Find and slay Summoner Marcelis.", progress = "You'll get your reward when you slay Marcelis, and not a moment sooner.", completion = "Your reward, as promised." }
WordHunterWoW_QuestEN[60277] = { title = "WANTED: Aggregate of Doom", description = "Attention all workers: \n\nWe got ourselves a problem down in the thicket. \n\nA golem is trekking through the worksite, causing all sorts of trouble. \n\nGrab a rock and get to throwin'. The dredger that takes it out gets the rest of the day off. \n\n- Foreman Scug", objectives = "Find and slay the Aggregate of Doom.", completion = "You did it then? Fair enough. Now we can all get back to work." }
WordHunterWoW_QuestEN[60278] = { title = "WANTED: Duke Anton", description = "Loyal Citizens of Revendreth: \n\nDuke Anton and his decrepit house are relics of noble venthyr society. \n\nHis attempts to tarnish my name are laughable at best. \n\nIt is time someone rid us of Duke Anton's presence for good.\n\nI shall offer double whatever pathetic sum he can muster. \n\nSincerely, \n\nLord Darion of House Redelav", objectives = "Find and slay Duke Anton of House Briarbane.", completion = "House Redelav sure has deep pockets. But you've earned it, I suppose." }
WordHunterWoW_QuestEN[60279] = { title = "WANTED: The Pale Doom", description = "Notice to all: \n\nA lingering menace lurks in the Endmire, dangerously close to Darkhaven's border. \n\nIf alone in your travels, take care to avoid this monstrosity, lest it make you meet your true death.\n\nThose with a sense of adventure and a well-armed brigade might manage to slay this beast. If so, a reward will await you upon your return. \n\nSincerely, \n\nTaskmaster Gavril", objectives = "Find and slay The Pale Doom within the Endmire.", progress = "There's no shame in turning down the bounty. Not everyone has what it takes to slay a devourer.", completion = "You have done Darkhaven a great service by slaying that beast." }
WordHunterWoW_QuestEN[60280] = { title = "WANTED: Lord Darion", description = "To Whom it May Concern: \n\nLord Darion of House Redelav thinks that he can buy his place in society. \n\nHe flaunts his wealth, using it to win favor of other lords and ladies. Is there no price on decency? \n\nThis is not the way the noble houses of Revendreth should conduct themselves. \n\nI implore you to find Lord Darion and help him meet his true death. \n\nThe honor of House Briarbane rests in your capable hands.\n\nWarmest Regards, \n\nDuke Anton of House Briarbane", objectives = "Find and slay Lord Darion of House Redelav.", completion = "Hopefully this means House Briarbane will stop their whining." }
WordHunterWoW_QuestEN[60281] = { title = "Rule 4: Make A List", description = "I've discovered that one of the Jailer's inquisitors is attempting to devise a method to track my movements.\n\nClearly, that is a problem for me... and by extension, it is a problem for you.\n\nThe inquisitor has risen to the top of my list of potential threats. In the past, I would have had to deal with him myself. But now... I have a business partner.\n\nPut an end to him, yes? And if you can, determine exactly how he intended to track me.", objectives = "Kill Inquisitor Devaki and find out how he is trying to track Ve'nari.", progress = "Have you learned anything of Inquisitor Devaki's tracking methods?", completion = "Fine work. This should keep the both of us safe from the Mawsworn. \n\nI will hold onto the sphere that you found for the purpose of study.\n\nDon't you have other matters to attend to?" }
WordHunterWoW_QuestEN[60283] = { title = "Specter Of War: Visectus", description = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more Anima-bound Wraps to strengthen the summons.", objectives = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more Anima-bound Wraps to strengthen the summons.", progress = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more Anima-bound Wraps to strengthen the summons.", completion = "Thank you, <name>. Your contribution has been logged in our records for posterity to appreciate!" }
WordHunterWoW_QuestEN[60284] = { title = "Rule 5: Be Audacious", description = "You have proven yourself a useful associate, {class}. In thanks, I have crafted a cypher that will allow you to venture further into the Maw.\n\nBut... it is experimental in nature. You will have to test it in the field. And I have just the test in mind.\n\nCartel Ve has foolishly sent more agents into the Maw. They were captured and taken to Perdition Hold. I must know why.\n\nBreach the fortress and learn what has become of the captive brokers. Nothing is more valuable than knowledge of your enemy's plans.", objectives = "Investigate the increased activity within Perdition Hold.", progress = "What have you discovered, Maw Walker?", completion = "The Beastwarrens, you say... I wonder what they are plotting...\n\nSuch an embarrassment that they were discovered and captured in the first place. It seems Cartel Ve has become quite careless in my absence.\n\nYou have my gratitude for your assistance, as always. I will inform you when I have need of your services again." }
WordHunterWoW_QuestEN[60285] = { title = "Rule 6: Concealment is Everything", description = "I have made a startling discovery, {name}. \n\nDo you recall how the captured agents of my cartel were taken to the Beastwarrens? \n\nThe Mawsworn seem to think they possess a means of tracking me. And now, strange new runes empower the Jailer's hounds.\n\nClearly, we cannot have that.\n\nThis new cypher will grant you solace from the screeching in the Beastwarrens. Brave its caverns and secure those runes for inspection.\n\nIf we are to counter their effects, I must know how they work.", objectives = "Retrieve 15 Broker Hunting Runes from The Beastwarrens.", progress = "The runes... you have them?", completion = "Interesting... runes that can detect brokers by using our extracted essence.\n\nLet us hope you were able to stop any further production. I will keep these for study.\n\nAt some point, you will certainly need to walk the nightmarish plains of the Beastwarrens again. My cypher will continue to allow you to do so." }
WordHunterWoW_QuestEN[60286] = { title = "A Token of Our Admiration", description = "Ahh, the Maw Walker returns. No doubt prepared to rush into danger for the common good?\n\nI'll get to the point. You have made contact with a member of our cartel, Ve'nari. Her continued survival within the Maw is in spite of incalculable odds.\n\nWe wish to assure her that she has not escaped our regard. Would you be our messenger?", objectives = "" }
WordHunterWoW_QuestEN[60287] = { title = "Rule 1: Have an Escape Plan", description = "Many doomed souls suffer within the Maw. You must be careful if you do not wish to join them.\n\nYour Soulkeeper can hold a small number of souls until you return to your covenant. But that will be of little benefit if you do not survive this place yourself.\n\nThere is a substance, stygia, that is found on some creatures within the Maw. The stronger the soul, the more stygia they have.\n\nCollect some of it for me and I can fashion it into many things you will find quite useful.", objectives = "Rescue 5 souls and retrieve 60 Stygia. \n\nStronger enemies will have a higher chance to drop large amounts of Stygia. \n\nUse the Stygia to purchase a Cypher of Relocation from Ve'nari.", progress = "I will gladly assist you in the acquisition of survival tools... provided you bring me the stygia.", completion = "You seem to have a knack for drawing the Jailer's attention.\n\nThis changes the terms of our arrangement." }
WordHunterWoW_QuestEN[60288] = { title = "Supplies from the Necrolords", description = "<name>, thanks to your efforts, our forces have been able to secure additional resources in our battles.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Oyne Soulborn at the Bleak Redoubt in Maldraxxus for your reward.<name>, thanks to your efforts, our forces have been able to secure additional resources in our battles.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
WordHunterWoW_QuestEN[60289] = { title = "Rule 3: Trust is Earned", description = "Before you leave this cursed realm, there is one final task you must complete for me.\n\nThe Mawsworn regularly transfer souls to various blocks of Torghast from many different areas in the Maw.\n\nI happen to know of one such area. Place this beacon there so I may be informed when the next transfer happens.\n\nAnd if you are seen by the enemy... well, you are known for your prowess in combat, yes?", objectives = "Place a Signaling Beacon in Cocyrus.", progress = "I will have opportunities for trade in the future, Maw Walker. I am certain our paths will cross again.", completion = "One of your associates was taken into Torghast? \n\nIt sounds as if he put up quite the fight. Perhaps he could also prove useful... if he were to be rescued." }
WordHunterWoW_QuestEN[60291] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", progress = "Did you bring back the carcass?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>" }
WordHunterWoW_QuestEN[60292] = { title = "Dangerous Discourse", description = "I found this scroll while you were cleansing the temple.\n\nThese are dire words, and I suspect it only gets worse. Collect more of these scrolls so I can determine just what these so-called Forsworn want.", objectives = "Collect 6 Dark Sermons.", progress = "We must defend the temple, <name>.", completion = "These words...\n\nIt is as I suspected.\n\n<Eridia stares grimly ahead.>" }
WordHunterWoW_QuestEN[60296] = { title = "Pride or Unit", description = "You have made great strides with our pride. I hope you found value and fulfillment in working with the larion.\n\nThe time to meet with Pelodis has come. You must decide whose way of life is more rewarding, and which you would prefer to pursue.", objectives = "Meet with Pelodis and Nemea, then pick a side.", progress = "The pack has welcomed you, <name>. I hope that you feel it.", completion = "It is done." }
WordHunterWoW_QuestEN[60313] = { title = "Dredhollow", description = "That was a narrow escape.\n\nBut I believe this presents an opportunity to finally turn the tide of this strife and defeat the Fearstalker. Meet me at Dredhollow: the abandoned hunting lodge of the Fearstalker.  \n\nWe must take separate paths. The Fearstalker will soon be after us again.", objectives = "Meet the Accuser at Dredhollow.", completion = "I am glad you made it here alive.\n\nGeneral Draven has informed me of a plan that might just work." }
WordHunterWoW_QuestEN[60315] = { title = "WANTED: Gorgebeak", description = "Thief! Pilferer! Menace!\n\nThe insidious menace known as Gorgebeak threatens our harvest of ambrosi for tribute to our great Archon. She must be stopped!\n\nIf any are willing to take on this foul fowl, I have tracked her nest to the western edges of Firstborne's Bounty. Proof of her demise shall be amply rewarded.\n\n--Gerdus", objectives = "Collect Gorgebeak's Bill for Gerdus in Firstborne's Bounty.", progress = "What business have you with this simple tender?", completion = "Our harvest is saved! Oh thank you, brave adventurer, our tribute may be saved yet!" }
WordHunterWoW_QuestEN[60316] = { title = "WANTED: Altered Sentinel", description = "Praetor broken! At Aspirant's Crucible. Attacking everybody!\n\nSomething wrong. Maybe changed?\n\nSimo not know how to fix. Tried everything!\n\nMust destroy!", objectives = "Destroy the Altered Sentinel for Forgehand Simo in Aspirant's Rest.", completion = "Oh! Broke praetor is gone? Sad. So sad. But thank you-hoo!" }
WordHunterWoW_QuestEN[60337] = { title = "Pupa Trooper", description = "", objectives = "" }
WordHunterWoW_QuestEN[60338] = { title = "Journey to Ardenweald", description = "The warning you received from the Primus needs to reach the Winter Queen of Ardenweald, {name}. The Eternal Ones must stand together against the coming darkness.\n\nThe Winter Queen oversees the cycle between Death and Life. In her forest slumber ancient spirits of nature that must be reborn.\n\nI fear the anima drought will have taken an especially grim toll upon her realm. \n\nThe night fae can lead you to the Queen. Bring her this message, and she will know what needs to be done.", objectives = "Travel to Ardenweald and find someone to take you to the Winter Queen.", completion = "We haven't seen anyone come through the gateway in a very long time! Certainly not someone like you.\n\nWhat brings you to Ardenweald?" }
WordHunterWoW_QuestEN[60339] = { title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?" }
WordHunterWoW_QuestEN[60340] = { title = "Hands on Approach", description = "When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape.\n\nNow, with my blade hands... it's time for my revenge! \n\nI've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!", objectives = "Slay Wurtzog Soultap and recover 12 anima traces.", progress = "Did you kill them all?", completion = "Guillotine can be vicious, but sometimes that's exactly what the situation demands." }
WordHunterWoW_QuestEN[60341] = { title = "First on the Agenda", description = "Let's make a deal, {name}. I'll seek out the Winter Queen on your behalf if you complete a few of my duties in my stead. The Queen isn't the only one who's been kept busy by the drought!\n\nFirst, you're going to help my fellow fae here with their spriggan problem. Boot their leader off that poor moth! Featherlight will tell you where to go after that. \n\nWe'll reunite in Tirna Vaal if you survive.\n\nOh, and I would stay on the path if I were you. Ardenweald can be dangerous for the unwary!", objectives = "Slay Mothbane the Mighty.", progress = "Not bad! Not bad at all!", completion = "If you can handle the spriggans, then perhaps I can give you some of the more interesting items on Lady Moonberry's agenda. Excellent!" }
WordHunterWoW_QuestEN[60342] = { title = "Cut 'Em Down to Size", description = "Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything!\n\nI hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!", objectives = "Slay Charthox in the Dredgewood of Revendreth.", completion = "Good work, both of you! \n\nGuillotine's efforts have not gone unnoticed. I've seen the others redouble their efforts to follow her example.\n\nThank you both, again." }
WordHunterWoW_QuestEN[60343] = { title = "Welcome to Orgrimmar", description = "The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once.\n\nFor now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit.\n\nI'll send for you once I've given my report to the warchief.", objectives = "Meet with Cork Fizzlepop at the city gate.", completion = "Hey, <name>! Long time no see, am I right?\n\nWarlord Grimaxe asked me to show you the sights. Let's go!" }
WordHunterWoW_QuestEN[60344] = { title = "Finding Your Way", description = "Orgrimmar's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Rohaka at the stables... but I can't seem to remember the way there.\n\nDon't worry, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master. Then we can be on our way!", objectives = "Speak with Rohaka Tuskmaul at the stables.", progress = "Welcome to the stables, <class>. I've been expecting you.", completion = "Warlord Grimaxe instructed me to give you a mount, but there's something we need to do first." }
WordHunterWoW_QuestEN[60345] = { title = "License to Ride", description = "Warlord Grimaxe told me you'd be coming to the stables to pick up your mount.\n\nBut before you go charging into battle, you'll need to learn how to ride it first.\n\nSpeak with Kildar when you're ready to learn how to ride.", objectives = "Speak with Kildar to learn the Apprentice Riding skill.", completion = "Now that you've learned the basics, feel free to return any time you want to advance your riding skills or purchase additional mounts!" }
WordHunterWoW_QuestEN[60346] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Telotha Pinegrove to learn more about specializations!", objectives = "Speak with Telotha Pinegrove to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building." }
WordHunterWoW_QuestEN[60347] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Tamanji to learn more about specializations!", objectives = "Speak with Tamanji to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building." }
WordHunterWoW_QuestEN[60348] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Feenix Arcshine to learn more about specializations!", objectives = "Speak with Feenix Arcshine to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building." }
