WordHunterWoW_QuestEN[60357] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Gormok Ogrefist to learn more about specializations!", objectives = "Speak with Gormok Ogrefist to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building." }
WordHunterWoW_QuestEN[60358] = { title = "Gildenite Grab", description = "Took our gildenite! Stole it! Stole it and took it away!\n\n<Sika's feathers ruffle.>\n\nNeed it, need it to make armor! Weapons!\n\nCan't make armor without gildenite!\n\n<Sika moves her arms as if explaining how armor is made.>\n\nYou understand? Yes? Why you still here?", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion." }
WordHunterWoW_QuestEN[60359] = { title = "Home Is Where the Hearth Is", description = "I don't know about you, but I'm in the mood for some good ol' fashioned recreation!\n\nWhy don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola?\n\nWhile we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a wyvern, but you'll save yourself some dough in the process!", objectives = "Speak with Innkeeper Nufa to make The Wyvern's Tail your home.", progress = "How can I help you today, <class>? Are you looking for a place to stay?", completion = "As long as The Wyvern's Tail is your home, you can find a warm fire here when you return." }
WordHunterWoW_QuestEN[60360] = { title = "An Urgent Meeting", description = "I've been looking for you all over Orgrimmar, {name}.\n\nWarlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again.\n\nI was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, {name}.\n\nLok-tar ogar!", objectives = "Speak with Warlord Breka Grimaxe at Grommash Hold.", completion = "Good, you're here. The warchief wishes to speak with you." }
WordHunterWoW_QuestEN[60361] = { title = "Battle for Azeroth: Mission Statement", description = "The warchief has requested to meet with you in person.\n\nLady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. \n\nNow that you've arrived, I will make the introduction.", objectives = "Attend the war meeting in Grommash Hold.", completion = "The Dark Lady has placed her trust in us. We will not fail her, <name>." }
WordHunterWoW_QuestEN[60362] = { title = "Blank", description = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore.\n\nMany have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father.\n\nPerhaps she feels the time has come to atone for this.\n\nLoath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance.\n\nGood luck.", objectives = "Speak with Lady Jaina Proudmoore in Stormwind Harbor." }
WordHunterWoW_QuestEN[60363] = { title = "Gildenite Grab", description = "Hshh... the golden ore, we need it.\n\nGolden ore of Bastion. Make their armor with it. \n\nWe need, many uses. Armors, weapons, trinkets and rings. Many uses.\n\nTravel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands.\n\nThey do not use it. We will. Go now.", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion." }
WordHunterWoW_QuestEN[60364] = { title = "Gildenite Grab", description = "Our allies in Bastion are in possession of a special ore known as gildenite. A golden metal used for many things in their lands, it is also useful to us.\n\nOnce upon a time, we would have traded for it. Now, we have little to trade, and they have little to give.\n\nYet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it.\n\nShould you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion." }
WordHunterWoW_QuestEN[60365] = { title = "Gildenite Grab", description = "The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well.\n\nOur stores are nearly depleted, and we have little to trade, but our needs are great.\n\nLet us reflect. \n\nIn Bastion, there are those that have turned their backs on their own people.\n\nWe may relieve these deceivers of their gildenite without remorse.", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion." }
WordHunterWoW_QuestEN[60366] = { title = "WANTED: Darkwing", description = "The Cloudfeather matriarch, Darkwing, has fallen to a great and terrible sickness. She has grown aggressive, dominating her children and driving them to violence.\n\nDarkwing must be slain if her flock is to ever return to the Archon's grace.\n\nPlease use the attached whistle to call her to her nest. I shall consider one of her crown feathers sufficient proof of the deed.\n\n--Eumelia, Stable Master", objectives = "Collect an Umbral Plume from Darkwing in Greatwing Roost for Eumelia.", progress = "Until Darkwing rests at last I fear her brood will know no peace.", completion = "You have my gratitude for restoring balance to these fascinating creatures. We all have our part to play." }
WordHunterWoW_QuestEN[60367] = { title = "Anima Crossing", description = "", objectives = "" }
WordHunterWoW_QuestEN[60369] = { title = "A Wealth of Wealdwood", description = "The shapers of our lands cultivate a very special form of wood we call wealdwood.\n\nIt contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn.\n\nIt is the basis of our arms and armor, and in these dark days, it is a target of our enemies.\n\nThey steal and hoard it, out there in the wilds. \n\nFind them, and return our treasures to us.", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald." }
WordHunterWoW_QuestEN[60370] = { title = "A Wealth of Wealdwood", description = "In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood, an enchanted substance used for many sorcerous purposes, is a key component in our rituals.\n\nWithout it, our magics pale in comparison to those of our enemies.\n\nYet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places.\n\nTravel to those places, and return to us once you have brought atonement to these vile creatures.", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald." }
WordHunterWoW_QuestEN[60371] = { title = "A Wealth of Wealdwood", description = "The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes.\n\nThey do not use it, not as we would. We must use it. It is ours to take.\n\nKshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it.\n\nNeed it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald." }
WordHunterWoW_QuestEN[60372] = { title = "A Wealth of Wealdwood", description = "Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood.\n\nWealdwood magical, help us make many thing.\n\nYou find some? Bring to Sika? Yes? Hoo?\n\nYes. \n\n<Sika writes your name on a scroll and underlines it twice, then shows it to you.>\n\nSee?", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald." }
WordHunterWoW_QuestEN[60373] = { title = "A Source of Sorrowvine", description = "There is a dark, evil vine that grows in Revendreth, known as sorrowvine.\n\nThey say it feeds off of the anguish of the souls as they are broken.\n\nRegardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin.\n\nRevendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth." }
WordHunterWoW_QuestEN[60374] = { title = "Bonemetal Bonanza", description = "The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones.\n\nThey form their armors out of a cultivated form of bone we call bonemetal. Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength.\n\nWe have many uses for it, both as a means of attachment, and when ground up, as a reagent.\n\nWe cannot ask them for resources now, but if you find any, I would use it.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus." }
WordHunterWoW_QuestEN[60375] = { title = "Bonemetal Bonanza", description = "Maldraxxus no longer answers our calls, and the houses are in disarray.\n\nYet we have need of them. Once, they supplied us with bonemetal, a strong yet malleable material useful for many armors.\n\nThere are those in Maldraxxus that hoard the material, seeking to profit from the chaos.\n\nThey must atone for these sins.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus." }
WordHunterWoW_QuestEN[60376] = { title = "Bonemetal Bonanza", description = "Ksh-ksh-ksh... you are needed.\n\nSo many betrayers in our lands, many deaths, much armor destroyed. \n\nNeed to rebuild.\n\nThe eyes have shown me stores of bonemetal, hoarded by our foes.\n\nBring them to me.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus." }
WordHunterWoW_QuestEN[60377] = { title = "Bonemetal Bonanza", description = "<Sika is studying a scroll.>\n\nNo bonemetal! Again, out of bonemetal!\n\n<Sika throws a pile of scrolls into the air.>\n\nHoo! Where you come from?\n\nOh, OH. Bonemetal! You get? Get from Maldraxxus. Help us out!\n\n<Sika points in the direction of Maldraxxus.>\n\nThat way!", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus." }
WordHunterWoW_QuestEN[60378] = { title = "A Source of Sorrowvine", description = "Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins.\n\nWe use it for many things, from potions to venoms. It is a versatile reagent.\n\nOur stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us.\n\nAs you travel our lands, should you come upon any, we would make good use of it.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth." }
WordHunterWoW_QuestEN[60379] = { title = "A Source of Sorrowvine", description = "Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms.\n\nRevendreth does not answer our calls. The eyes show me conflict and strife in their lands.\n\nThis matters little to us.\n\nShh... travel there, find their vines, return to me.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth." }
WordHunterWoW_QuestEN[60380] = { title = "A Source of Sorrowvine", description = "Need sorrowvine! Please help!\n\nRevendreth not sending us supplies, not answering Sika! Can't make potions now. What we do?\n\n<Sika seems to have just remembered that you were there.>\n\nYou go! \n\n<Sika pushes you.> \n\nGo go!", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth." }
WordHunterWoW_QuestEN[60381] = { title = "Aiding Ardenweald", description = "Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides.\n\nTravel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall.\n\nRemind them that our great purpose will be fulfilled, and we will not let the groves wither.\n\nYou, Maw Walker, will unite us today.", objectives = "Complete 3 World Quests in Ardenweald.", progress = "Have you brought hope and faith to our people today?", completion = "Our bonds are stronger, our roots grow deeper, due to your actions this day. We will hold strong against the onset of foes that plague us, as groves weave together in defense, thanks to you." }
WordHunterWoW_QuestEN[60382] = { title = "Aiding Revendreth", description = "We do not turn out backs on our allies, even when we face darkness here in Ardenweald.\n\nIn Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader.\n\nWe cannot allow those that make Sinfall their home to lose hope.\n\nTravel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.", objectives = "Complete 3 World Quests in Revendreth.", progress = "How goes the battle in Revendreth?", completion = "As we aid our allies, we all remember the bonds that forge us together in our world. Together, we will overcome, and only together, will the Shadowlands function once more." }
WordHunterWoW_QuestEN[60383] = { title = "Aiding Maldraxxus", description = "Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did.\n\nNow they are plagued by infighting and an imbalance in power.\n\nWe have few allies there, but those that remain, we must maintain.\n\nGo there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more.\n\nWithout them, we are but one invasion from complete annihilation.", objectives = "Complete 3 World Quests in Maldraxxus.", progress = "Have you aided the forces of Maldraxxus?", completion = "We are now one step closer to reforging the army that will defend our worlds. This is a good thing you have done today." }
WordHunterWoW_QuestEN[60384] = { title = "Aiding Bastion", description = "The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die.\n\nWe cannot allow them to fall, for without Bastion, we are lost.\n\nTravel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.", objectives = "Complete 3 World Quests in Bastion.", progress = "Have you aided Bastion today?", completion = "Even in dark times, we cannot allow others to be alone with their troubles. It is only when we stand together that the Shadowlands can become whole again." }
WordHunterWoW_QuestEN[60385] = { title = "Training in Revendreth", description = "The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training.\n\nCome here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt.\n\nFor tomorrow, we hunt.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", completion = "I smell a group of successful hunters, good. Each successful hunt brings us one step closer to a trained hunting pack." }
WordHunterWoW_QuestEN[60386] = { title = "Training in Maldraxxus", description = "The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves.\n\nThere is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields.\n\nTake this one with you on your travels today, so that they may see what real combat looks like.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", progress = "Do you return with a trainee, or a coward?", completion = "There is little better than real combat experience to train our next generation of hunters. Thank you for keeping this one alive." }
WordHunterWoW_QuestEN[60387] = { title = "Training in Bastion", description = "Our hunters do not have the time for proper training, and so we must train them in the field.\n\nOur allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor.\n\nDo you hear that, trainee? Today, you accompany the Maw Walker!\n\nMaw Walker, do not go easy on this one.", objectives = "Complete 3 World Quests in Bastion with your trainee.", progress = "I hope that today's trainee survived the trip, but I am not overly confident.", completion = "Good, a tired trainee is a trainee that has seen combat and gained many experiences. You have done well with this one." }
WordHunterWoW_QuestEN[60388] = { title = "Training Our Forces", description = "Get up, trainee, you must get up!\n\nLook at this one! Needs much more training before we stand a fighting chance against our enemies. \n\nWe have precious little time to build combat prowess these days, with so many foes at our backs.\n\nTake this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", progress = "How goes the training?", completion = "You have done well, we will allow them to rest a moment. Today they have learned that even in the calmest meadow, there is always danger." }
WordHunterWoW_QuestEN[60389] = { title = "Aiding Ardenweald", description = "Ay there, ya got a moment?\n\nLotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one.\n\nWe're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? \n\nDo I gotta spell it out for you? Get on over there, ya big goof.", objectives = "Complete 3 World Quests in Ardenweald.", completion = "Ain't never been a friend to no Night Fae, but maybe it's about time we went lookin' for more allies. Gotta start somewhere, I suppose." }
WordHunterWoW_QuestEN[60390] = { title = "Aiding Ardenweald", description = "We are attacked by enemies on all sides, Maw Walker. \n\nAnd Ardenweald faces a similar threat.\n\nIt is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need.\n\nTogether, we are strong. This is the doctrine of the phalanx, and it will be ours as well.", objectives = "Complete 3 World Quests in Ardenweald.", progress = "Have you secured allies in Ardenweald?", completion = "Stability in Ardenweald will serve us as we move against the enemy. This was a solid strategic choice, Maw Walker." }
WordHunterWoW_QuestEN[60391] = { title = "Aiding Ardenweald", description = "Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall!\n\nMake haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone!\n\nBastion stands with them, and with us, they will never falter!", objectives = "Complete 3 World Quests in Ardenweald.", progress = "Have you served in Ardenweald today?", completion = "Today we are blessed that the Maw Walker has brought our divine purpose to Ardenweald! Our allies rejoice in your victories!" }
WordHunterWoW_QuestEN[60392] = { title = "Aiding Bastion", description = "In our own golden hills, evil abounds. We will not allow it to take root and fester!\n\nRaise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them!\n\nWith haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon!\n\nFor Bastion!", objectives = "Complete 3 World Quests in Bastion.", progress = "Do the hills echo with the cries of your victories, Maw Walker?", completion = "The hills speak of your faith and honor, our forces radiate with each victory! Glory to Bastion, glory to the Archon, glory to the Maw Walker!" }
WordHunterWoW_QuestEN[60393] = { title = "Aiding Bastion", description = "The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them.\n\nTravel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies.\n\nWar is not always fought on the battlefield, but often in the means of replenishment.", objectives = "Complete 3 World Quests in Bastion.", progress = "Have you secured the situation in Bastion?", completion = "We are one step closer to returning our supply of souls to a functioning form, Maw Walker. This is an important advancement in the war for Maldraxxus." }
WordHunterWoW_QuestEN[60394] = { title = "Aiding Bastion", description = "If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better.\n\nWe got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff.\n\n<Rendle wipes his nose loudly.>", objectives = "Complete 3 World Quests in Bastion.", completion = "Always wanted to eat a steward, never got the chance to. Really wonder what they taste like. \n\nWas a good thing you did for them, anyway. Just got some idle musings I do." }
WordHunterWoW_QuestEN[60395] = { title = "Aiding Maldraxxus", description = "In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all.\n\nWe must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord.\n\nA spear of gold and bone we will form! And thrust it into the heart of evil!\n\nGo now, Maw Walker, as the tip of the spear, to glorious battle!", objectives = "Complete 3 World Quests in Maldraxxus.", progress = "Have you pierced the heart of evil in Maldraxxus?", completion = "Glorious! The gilded halls of Bastion stand firm with our allies in Maldraxxus, may they never wane in their battle for righteousness!" }
WordHunterWoW_QuestEN[60396] = { title = "Aiding Maldraxxus", description = "The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand.\n\nWalk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you.\n\nFear is the seed that breeds doubt, and doubt is the root that crumbles empires.", objectives = "Complete 3 World Quests in Maldraxxus.", progress = "How goes the battle?", completion = "Our rival houses will think twice before stepping foot outside of their strongholds again. Blood and glory to you, Maw Walker." }
WordHunterWoW_QuestEN[60397] = { title = "Aiding Maldraxxus", description = "Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left.\n\nAll's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out.\n\nGet over there and help them good ones keep the peace, maybe they help us out some day, too.", objectives = "Complete 3 World Quests in Maldraxxus.", completion = "Maybe things get a bit more stable down there in Maldraxxus, now. Would do us all a lot o' good." }
WordHunterWoW_QuestEN[60398] = { title = "Aiding Revendreth", description = "Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. \n\nOnce, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses.\n\nToday, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part.\n\nIt is your Primus-given duty to aid Sinfall against those that seek to break the cycle.", objectives = "Complete 3 World Quests in Revendreth.", progress = "Have you broken the forces of Denathrius?", completion = "With your aid, we have once again been able to perform our sacred duties in defense of the Shadowlands. Little by little, we right the wrongs that have sent us awry, that the cycle can begin anew." }
WordHunterWoW_QuestEN[60399] = { title = "Aiding Revendreth", description = "Oi there, got somethin' for you to do today.\n\nLots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems.\n\nWe're not gonna make much headway against Denathrius with his lot at our heels all the time, ay?\n\nGet out there an' get some muck on your boots.", objectives = "Complete 3 World Quests in Revendreth.", progress = "What do ya want?", completion = "Ya did a good thing today, an' we're safer for it. Never been one to give a compliment, me, but today I gotta say ya did a good one." }
WordHunterWoW_QuestEN[60400] = { title = "Aiding Revendreth", description = "Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius.\n\nWe cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all.\n\nWe of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!", objectives = "Complete 3 World Quests in Revendreth.", completion = "Even those that are far from our lands are necessary allies in these dark times. With faith and honor we will serve them, and the Shadowlands, until evil clips our wings!" }
WordHunterWoW_QuestEN[60401] = { title = "Training in Ardenweald", description = "I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. \n\n<Sakaa waves her hand vaguely in the direction of Ardenweald.>\n\nPlenty of things to maim over there, maybe they learn a thing or two about wood.\n\n<Sakaa smirks.>", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", completion = "Oh, well, good job carting this one around, then. Hope they didn't give you any trouble.\n\nMaybe a little trouble would be acceptable." }
WordHunterWoW_QuestEN[60402] = { title = "Training in Ardenweald", description = "Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads.\n\nTake this trainee out and get them some real combat experience.\n\nArdenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", progress = "You back already?", completion = "Good, good, I can already see this one's learned a thing or two today. I'll take it from here." }
WordHunterWoW_QuestEN[60403] = { title = "Training in Ardenweald", description = "It is our great duty to take our aspiring warriors and train them in combat. \n\nToday, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands.\n\nTeach them the ways of battle and honor.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", progress = "How fares the training?", completion = "You have returned with your charge intact, most benevolent. Carry the lessons of the teacher with you." }
WordHunterWoW_QuestEN[60404] = { title = "Training Our Forces", description = "What better place to stretch our wings than right here on our own fields?\n\nTake one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here.\n\nPart of their training will be courage when facing off against those they thought their brethren.\n\nIt has been known to break hearts and ranks before.", objectives = "Complete 3 World Quests in Bastion with your trainee.", progress = "How fares your heart today?", completion = "Let this one rest, now. Facing threats from within, let alone against ones you once considered kin and ally, can take a mighty toll." }
WordHunterWoW_QuestEN[60405] = { title = "Training in Bastion", description = "Useless minions, the lot of them. All of this fodder needs to get trained.\n\nHere, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me.\n\nPlenty of things to test them against, there. \n\nIf you get them killed, I don't want to hear it.", objectives = "Complete 3 World Quests in Bastion with your trainee.", progress = "Any luck with this sad lot?", completion = "Well well well, kind of surprised you managed to make it back with your trainee intact. Guess you're a better instructor than I gave you credit for. Going to keep that in mind." }
WordHunterWoW_QuestEN[60406] = { title = "Training in Bastion", description = "I have yet another minion, er, recruit that needs training.\n\nTake them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. \n\nMaybe you pick up some new tricks while you're out there, too.", objectives = "Complete 3 World Quests in Bastion with your trainee.", completion = "Thank you for showing them around today. There's plenty to learn still, though." }
WordHunterWoW_QuestEN[60407] = { title = "Training in Maldraxxus", description = "Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath.\n\nTake this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators.\n\nThere, they will face true challenges, and return with great knowledge.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", progress = "Has your trainee survived the fields of battle?", completion = "Ah, good, you returned with your trainee intact. Truthfully, each time we send them on such an errand, it is a game of chance. It is good you were with them." }
WordHunterWoW_QuestEN[60408] = { title = "Training Our Forces", description = "Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat.\n\nTake a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", progress = "Any luck out there?", completion = "By my bones, you came back and your trainee isn't a pile of mush. Can't believe my eye sockets." }
WordHunterWoW_QuestEN[60409] = { title = "Training in Maldraxxus", description = "Another trainee needs some looking after, if you don't mind.\n\nMaldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that.\n\nJust throw them in the arena or something. 'Sink or swim' is an effective training strategy.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", progress = "Could really go for a nap I could.", completion = "Your trainee's looking a little roughed up, but none the worse for wear. Probably learned a thing or two." }
WordHunterWoW_QuestEN[60410] = { title = "Training Our Forces", description = "I have yet more troops for you to train, and there are plenty of things to do right here in our domain. \n\nTake them out and give them a good, solid, and probably bloody taste of what we're up against.\n\nNow, if you get them killed? That's none of my business.\n\n<Sakaa sips a thick and sweet-smelling beverage.>", objectives = "Complete 3 World Quests in Revendreth with your trainee.", progress = "Did you manage to bring them back alive?", completion = "Well, it looks like you drilled some good experience into this one today. Only a few broken bones!" }
WordHunterWoW_QuestEN[60411] = { title = "Training in Revendreth", description = "Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking.\n\nDo me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic.\n\nWon't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", progress = "Well? You bring back a pile of bones or a trainee?", completion = "Looks like this one's got a bit more in the head now, maybe they'll survive beyond a battle now." }
WordHunterWoW_QuestEN[60412] = { title = "Training in Revendreth", description = "A trainee is in need of your guiding hand.\n\nTake them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes.\n\nReturn victorious, as their shield and mentor, so that our armies will be bolstered this day.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", completion = "Another glorious day of training in the name of the Archon! We will let this one rest now, to train another day." }
WordHunterWoW_QuestEN[60414] = { title = "Rare Resources", description = "The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. \n\nWe have relied upon them to bring us useful materials for many years, but these days, we have little to trade.\n\nThey value a currency of their own making, coins of brokerage, as a general means of trade.\n\nIf you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", progress = "Have you found any coins?", completion = "Oh, this is quite a find. These will allow me to procure some rather rare ingredients and materials, and with them, we may turn the tide against our foes. Well done." }
WordHunterWoW_QuestEN[60415] = { title = "Rare Resources", description = "Hello! Yes! Hello.\n\nBrokers, you know them? \n\n<Sika does her best attempt at looking like a broker. It is not convincing.>\n\nTrade many things with us. Things we no get. Things we want.\n\nNeed coins. Clink clink!\n\n<Sika makes a circle with her finger feathers.>\n\nFind them everywhere, bring them to Sika!", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", progress = "Bring coins to Sika? Need trade with brokers. You know this?", completion = "Coins! Coins for Sika! Happy Sika, happy friends. Can buy many things, strange things, you no understand, is ok.\n\n<Sika takes the coins and waves at you.>" }
WordHunterWoW_QuestEN[60416] = { title = "Rare Resources", description = "Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them.\n\nFind many secrets, they do. Bring us supplies, strange and rare.\n\nNeed things to trade. Need broker coins.\n\nThey trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. \n\nYou may eat their corpses, I will not judge. Just need coins.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", progress = "Bring me coins? Coins for brokers. Many uses. You see?", completion = "The clink of the coins is the sound of secrets being revealed. Many uses, many things I will purchase. More powerful will we become, due to this. A good find." }
WordHunterWoW_QuestEN[60417] = { title = "Rare Resources", description = "The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure.\n\nThey are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere.\n\nThey hold in high regard a currency of their own creation, you may find such coins in your travels. \n\nI will gladly take them off of your hands to bolster our supplies.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", progress = "Have you found any of the broker's coins?", completion = "This small handful of coins will purchase many things of use to us. I will contact them directly.\n\nThank you, Maw Walker." }
WordHunterWoW_QuestEN[60418] = { title = "A Call to Bastion", description = "Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. \n\nIf they fall to darkness, it's only a matter of time before we, too, dwindle and fade.\n\nThey are beset by all manner of problems. We have to get over there and help them!", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", progress = "How are the Kyrians?", completion = "I've gotten word from our Kyrian allies that you did them a great service! Thank you!" }
WordHunterWoW_QuestEN[60419] = { title = "Troubles at Home", description = "They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! \n\nAll throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect.\n\nIf the cycle stops here, so many great souls will be lost... forever.\n\nThere's no time to waste, we need your help! Defend Ardenweald!", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", progress = "Are things improving in the glades?", completion = "I've heard many tales of your greatness, the Winter Queen is quite pleased! \n\nPlease take this, and keep up the fight!" }
WordHunterWoW_QuestEN[60420] = { title = "A Call to Maldraxxus", description = "I'm glad you're here! We've got some problems in Maldraxxus.\n\nThe forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. \n\nBut now, some of the houses have overthrown the balance, and seek to conquer the rest of us!\n\nOur allies there need our help! Aid them however you can.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", progress = "Are things improving in Maldraxxus?", completion = "The houses of Maldraxxus are once again in balance, and not a threat to us... for now at least. \n\nYou did great!" }
WordHunterWoW_QuestEN[60421] = { title = "A Call to Revendreth", description = "Oh, I'm glad you're here, we've got a problem!\n\nOur friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! \n\nIf Denathrius's control of Revendreth isn't broken, he'll come for us next...\n\nLet's do whatever we can to help them out!", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", progress = "How are things in Revendreth?", completion = "Ha, take that Denathrius. He won't be allowed to rule the Shadowlands if you have anything to say about it!" }
WordHunterWoW_QuestEN[60422] = { title = "A Call to Ardenweald", description = "We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger.\n\nThe great soul-trees of Ardenweald are under assault from many foes that seek to harness their power.\n\nWe must aid our allies in the Night Fae, and punish their enemies for these transgressions.\n\nWe are stronger together.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", progress = "Have you completed your task?", completion = "You have secured our alliance with the Night Fae, and in doing so, we hold a stronger position across the Shadowlands." }
WordHunterWoW_QuestEN[60423] = { title = "A Call to Ardenweald", description = "Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. \n\nMaldraxxus alone is responsible for challenging those that would disrupt the cycle.\n\nTake our banners, steady your weapons, and bring war to Ardenweald.\n\nFor the Shadowlands.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", progress = "How do the boughs break?", completion = "The cycle will continue, as we have willed it to be so. \n\nWith every foe you slay, the name of Maldraxxus is spoken with glory and purpose." }
WordHunterWoW_QuestEN[60424] = { title = "A Call to Ardenweald", description = "Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls.\n\nShould the weald fall, the devastation that would be unleashed could destroy us all.\n\nWe must aid the Winter Queen. It is the will of the Archon.\n\nGo now, and provide support to the Night Fae.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", progress = "Have things improved in Ardenweald?", completion = "Our allies in Ardenweald have sent word of your many deeds. You have shown once more that the Kyrian will fight for the Shadowlands and our allies, no matter the cost. \n\nCourage and wisdom to you." }
WordHunterWoW_QuestEN[60425] = { title = "Troubles at Home", description = "Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes.\n\nToday, we root them out.\n\nHead into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you.\n\nIn the name of the Archon.", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", progress = "Are the fields cleansed?", completion = "The bells chime in the distance, heralding your return. A glorious sound.\n\nYou have performed a great service today, and truly secured your place among us.\n\nHail, victor!" }
WordHunterWoW_QuestEN[60426] = { title = "A Call to Bastion", description = "We, the defenders of the Shadowlands, will never let a great foe go unchallenged.\n\nThe Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services.\n\nNow, they too are under attack from within. We must defend them in their time of need.\n\nGo now, and bring glory in the name of the Primus.", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", progress = "Are the golden fields bathed in blood?", completion = "We will always rise to the defense of the Shadowlands, even if we are weakened from within. \n\nYou have shown that no foe is too far to escape the reach of Maldraxxus." }
WordHunterWoW_QuestEN[60427] = { title = "A Call to Bastion", description = "The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger.\n\nThey have their own troubles in these times, as well. Today, we must look without, and aid our allies.\n\nTravel to the golden fields, and rid them of their foes. \n\nOnly with allies do we stand a chance against Denathrius.", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", progress = "Have you completed your task?", completion = "The Archon has sent word of your deeds, and agreed to support us in the battles to come. We will fix this broken cycle, with steps such as this leading the way." }
WordHunterWoW_QuestEN[60428] = { title = "The Blade of the Primus", description = "That's everything I need. Time to get to work.\n\nI'd stay close, if I were you. Forging a weapon is never a simple task when the Primus's handiwork is involved.\n\nIf he taught me anything, it was to expect the unexpected.", objectives = "Help Bonesmith Heirmir forge your runeblade.", progress = "Stay close, now.", completion = "The Primus was always fond of his trials. It seems you've passed this one. Well done." }
WordHunterWoW_QuestEN[60429] = { title = "Troubles at Home", description = "Look! Look around you! All around us, foes await the crushing hand of victory.\n\nThere is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened.\n\nThe only cure is more combat!\n\nChallenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", progress = "Have you littered the ground with the bones of your enemies?", completion = "The stories of your power reverberate across the landscape. The bones of the fallen tremble at your name. Let us revel in your victory today!" }
WordHunterWoW_QuestEN[60430] = { title = "A Call to Maldraxxus", description = "The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands.\n\nNow, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others.\n\nTheir problems are many, our solutions are just. \n\nTravel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", completion = "With the houses of betrayal brought to their knees, you have brought us one step closer to peace. The Archon thanks you for your service to the Shadowlands." }
WordHunterWoW_QuestEN[60431] = { title = "A Call to Maldraxxus", description = "The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now.\n\nThe houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten.\n\nGo now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", completion = "The warriors of Maldraxxus speak your name, a great victory to have achieved this day. The balance of power will be restored one day, and our alliances will pay dividends." }
WordHunterWoW_QuestEN[60432] = { title = "Troubles at Home", description = "There are many tasks that need your attention outside of the walls of Sinfall.\n\nOur closest allies are under assault from all sides, and the forces of Denathrius are unrelenting.\n\nTake your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies.\n\nWe will take back what is ours.", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", progress = "Have you reclaimed our homeland?", completion = "We are more secure in our position due to your actions today. Revendreth will not fall to the sway of Denathrius, not as long as we hold firm." }
WordHunterWoW_QuestEN[60433] = { title = "A Call to Revendreth", description = "We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls.\n\nThere is one such betrayer - Sire Denathrius.\n\nBring the vengeance of Maldraxxus down upon his foul crown. \n\nSlay his allies, serve his foes, end his reign in carnage.", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", completion = "Denathrius did not expect us to rally so quickly, to serve our great purpose in the cycle. \n\nHe underestimated our house for the last time, and has paid the price in blood." }
WordHunterWoW_QuestEN[60434] = { title = "A Call to Revendreth", description = "We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just.\n\nYet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands.\n\nWe have friends there, amongst the Venthyr. Aid them, and put their enemies to rest.\n\nThe Word of the Archon is with you.", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", progress = "Have you returned victorious?", completion = "The crimes of Sire Denathrius could not go unpunished, and you have meted out a proper response today. \n\n<Polemarch Adrestes bows his head in your direction.>" }
WordHunterWoW_QuestEN[60435] = { title = "Challenges in Revendreth", description = "We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors.\n\nOver many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will.\n\nWhat better way to secure our allies and test our strength, than to eliminate his most fervent champions.\n\nGo now, and hunt.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", progress = "Have you thinned Denathrius's forces?", completion = "The generals that serve our enemies in Revendreth will think twice before attempting to control the Shadowlands. \n\nWe have aided unlikely allies, and forged true bonds with Revendreth today, and it is thanks to you." }
WordHunterWoW_QuestEN[60436] = { title = "Challenges in Maldraxxus", description = "Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands.\n\nThere, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds.\n\nCrash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", progress = "Have you returned victorious?", completion = "In a land of champions and war, you have proven your worth. Few can claim to have taken on the greatest defenders of the Shadowlands and survived, yet here you stand, a monument to the strength of the Night Fae. \n\nMay it never wane." }
WordHunterWoW_QuestEN[60437] = { title = "Challenges in Bastion", description = "Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls.\n\nThey are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos.\n\nDoubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", progress = "Have you aided the denizens of Bastion?", completion = "You have shown courage in the face of great doubt. There are many kinds of strength, and you have shown that you possess one that goes beyond the blade and bow." }
WordHunterWoW_QuestEN[60438] = { title = "Challenges in Ardenweald", description = "The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life.\n\nIn our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue.\n\nTake on this trial, and put an end to the invaders of Tirna Scithe.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", progress = "How goes the hunt?", completion = "A quiet has overtaken the glade, the leaves no longer rustle in anguish. This is your doing, and we will not forget this kindness." }
WordHunterWoW_QuestEN[60439] = { title = "Challenges in Ardenweald", description = "Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades.\n\nReady your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness.\n\nIt is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils.\n\nLight shines only in darkness.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", progress = "Have you cleansed the weald?", completion = "I have received word of your great deeds in Ardenweald. They are thankful for your service, and you have proven your courage tenfold today." }
WordHunterWoW_QuestEN[60440] = { title = "Challenges in Ardenweald", description = "Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no?\n\nSo ready your weapon and get out there! What better place to prove your might?\n\nSmash them to pieces, in the name of Maldraxxus!", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", progress = "Rip and tear!", completion = "It is a shame your job was completed so quickly. So many foes, so little time!\n\nYou are a good addition to our forces, I really enjoy all of this slaying." }
WordHunterWoW_QuestEN[60441] = { title = "Challenges in Ardenweald", description = "Ardenweald was once a place of peace and regrowth, but no longer.\n\nFoes assault the weald from all sides, dark creatures that serve no masters.\n\nThey will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them.\n\nThey will see what we do to those that must be broken.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", progress = "Has justice been served?", completion = "Those that have no masters have learned a lesson today.\n\nWe are their masters, in the end." }
WordHunterWoW_QuestEN[60442] = { title = "Challenges in Bastion", description = "Sometimes we need look no further than our own golden hills to find a suitable challenge.\n\nDoubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight.\n\nWe must stand against them, now. \n\nIt will not be easy, but things that are worth fighting for rarely are.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", progress = "Have you seen the face of doubt and shown it certainty?", completion = "You have uprooted the seeds of doubt and crushed them with certainty. May their doubts now be about only their own dark paths." }
WordHunterWoW_QuestEN[60443] = { title = "Challenges in Bastion", description = "We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle!\n\n<Grandmaster Volo laughs and smashes his weapon around.>\n\nWe must aid them against their foes, or else the arena will sit barren, and we can't have that!\n\nFind their greatest enemies and turn their bones into golden dust.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", progress = "Have you clipped their wings?", completion = "You return victorious, atop a mountain of bloody feathers! Ha ha! Glorious!" }
WordHunterWoW_QuestEN[60444] = { title = "Challenges in Bastion", description = "Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services.\n\nYet, within their ranks, doubt has grown and festered. If this continues, we will all pay.\n\nTheir loss of focus shall not be allowed to continue. We will punish their wandering hearts.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", progress = "Has justice been served?", completion = "The sins of the doubtful have been purged." }
WordHunterWoW_QuestEN[60445] = { title = "Challenges in Maldraxxus", description = "The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds.\n\nHere, you will find some of your greatest challenges.\n\nSeek out the champions of the strongest houses, stand against them, and let them see your might.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", progress = "Do you stand victorious?", completion = "You stand alone atop a pile of bones, as a true master of combat. You have shown yourself a real Necrolord today!" }
WordHunterWoW_QuestEN[60446] = { title = "Challenges in Maldraxxus", description = "Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds.\n\nFor many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless.\n\nThey must pay for these transgressions.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", progress = "Has justice been served?", completion = "Let this be a lesson to them, Revendreth will not stand by and let the balance be disturbed." }
WordHunterWoW_QuestEN[60447] = { title = "Challenges in Maldraxxus", description = "In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors.\n\nWhat better place to test yourself?\n\nHead into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", progress = "Have you found the truth in courage?", completion = "The mightiest gladiators have fallen to your hand, and in doing so, you have shown that we, too, will defend the Shadowlands if necessary. Let this be a lesson to them." }
WordHunterWoW_QuestEN[60448] = { title = "Challenges in Revendreth", description = "Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all.\n\nSome are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. \n\nThey are the mightiest of Denathrius's allies, and they must be brought to justice.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", progress = "Has justice been served?", completion = "Justice has been served." }
WordHunterWoW_QuestEN[60449] = { title = "Challenges in Revendreth", description = "I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out.\n\nTheir leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right.\n\nI want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", progress = "You didn't let them bite you, right?", completion = "I have heard of your bloody exploits in Revendreth, and I am pleased. \n\nDid you bring me back any of their teeth? No? Well, maybe next time." }
WordHunterWoW_QuestEN[60450] = { title = "Challenges in Revendreth", description = "Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? \n\nIn this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield.\n\nNone more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands.\n\nAnd here is where you must challenge yourself today.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", progress = "Have you proven your worth in Revendreth?", completion = "Even so far from our fields, you stood strong against the evils you found, unflinching. This is true courage." }
WordHunterWoW_QuestEN[60451] = { title = "Never Enough", description = "Well done, recruit. These were merely the first of many assignments in your future.\n\nMatters here demand my attention. Report to Baroness Draka and see what need she has of you.\n\nI will watch closely as this war unfolds.", objectives = "Return to Baroness Draka.", completion = "Good work. I see that our defenses have been shored up." }
WordHunterWoW_QuestEN[60452] = { title = "Storm the Maw", description = "Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it!\n\nYou need to go back there! You're the Maw Walker!\n\nSee what you can learn of his power, and slow him down however you can. I believe in you!\n\nBe careful, ok?", objectives = "Kill 3 rare or special encounter bosses in The Maw.", completion = "You did great! We learned a lot from your reports, and it sounds like you did some good down there. Good job!" }
WordHunterWoW_QuestEN[60453] = { title = "The Path to Glory", description = "It's been some time since I had a chance to craft a weapon that powerful! Good to know that the skills I learned from the Primus haven't dulled.\n\nYou'd best get back to the baroness with that runeblade. I'm sure the margrave will want to know you wield it, as well.\n\nThe Primus was notorious for thinking ten paces ahead of everyone else. I suspect he knew that someone like you would take up that blade.", objectives = "Return to Baroness Draka with your runeblade.", completion = "You wield a fine weapon. Now you must put it to use." }
WordHunterWoW_QuestEN[60454] = { title = "Storm the Maw", description = "We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this.\n\nWe know little about the Jailer's lands, save that he is powerful beyond imagining.\n\nI ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces.\n\nWe must buy more time.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", completion = "You have shown us many things we could not see ourselves, and now perhaps we can begin to formulate a plan. \n\nYou have done us a great service today." }
WordHunterWoW_QuestEN[60455] = { title = "Storm the Maw", description = "We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall.\n\nReturn to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day.\n\nHis forces must be slowed, make what progress you can.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", progress = "You seem different, somehow.", completion = "He has seen you, and you are now marked. Wear this as a badge of honor. None other could have done what you did.\n\nHe is not afraid, yet, but he will be." }
WordHunterWoW_QuestEN[60456] = { title = "Storm the Maw", description = "We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return.\n\nWhat I am about to ask of you I would not dare ask of another.\n\nWe cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands.\n\nMake what progress you can, we must slow down his forces however possible.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", completion = "We have learned much from your travels into the Maw, and we shall plan for the future.\n\nThere was no other way to slow the Jailer's consolidation of power, you have done us a great service, Maw Walker." }
WordHunterWoW_QuestEN[60457] = { title = "Anima Salvage", description = "So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it.\n\nMaw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower.\n\nBring us that which we lack.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", progress = "Have you recovered the Anima Embers?", completion = "You have done us a great service today, Maw Walker. We shall use these to nourish what we can." }
WordHunterWoW_QuestEN[60458] = { title = "Anima Salvage", description = "When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands.\n\nSouls that have been devoured, consumed, their anima lost to us. Return to us what you can.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", progress = "Have you secured the lost Anima Embers?", completion = "While it is not the same as returning the souls, their power shall not go to waste. You have my thanks." }
WordHunterWoW_QuestEN[60459] = { title = "Anima Salvage", description = "The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus.\n\nThe Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops.\n\nTravel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", progress = "Have you brought Anima Embers for our stockpiles?", completion = "The armies of the undying will not fall today, Maw Walker. You emerge victorious once more in the face of great power, impressive." }
WordHunterWoW_QuestEN[60460] = { title = "Anima Salvage", description = "Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society.\n\nThis is a necessary part of the cycle.\n\nYet now, the cycle is broken, and are unable to serve our great purpose.\n\nIn order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", progress = "Have you brought the Anima Embers to us?", completion = "These Anima Embers will serve us well, Maw Walker." }
WordHunterWoW_QuestEN[60461] = { title = "Meet the Margrave", description = "Word of the runeblade has reached Margrave Krexus. He wishes to see it for himself.\n\nWith such a weapon by your side, you pose a threat that the other houses cannot ignore. Perhaps we can use that to our advantage.\n\nBut enough talk. Follow me.", objectives = "Present your runeblade to Margrave Krexus.", completion = "Show me this runeblade of yours, mortal." }
WordHunterWoW_QuestEN[60462] = { title = "Anima Appeal", description = "Maw Walker!\n\nThe Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die.\n\nSearch the realms for additional nourishment and deliver it to the sanctum.\n\nArdenweald cannot continue without your aid!", objectives = "Deposit 600 anima in the Anima Reservoir at the Heart of the Forest in Ardenweald." }
WordHunterWoW_QuestEN[60463] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur anima stores have run low, and soon we will have nothing to sate our thirst...\n\nSeek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum.\n\nThese are dire circumstances. Our fate is in your hands.", objectives = "Deposit 600 anima in the Anima Reservoir at Sinfall in Revendreth." }
WordHunterWoW_QuestEN[60464] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost!\n\nScour the realms for all the anima you can gather and deliver it here to the sanctum.\n\nVictory depends on your success!", objectives = "Deposit 600 anima in the Anima Reservoir at Seat of the Primus in Maldraxxus." }
WordHunterWoW_QuestEN[60465] = { title = "Anima Appeal", description = "Maw Walker!\n\nOur supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late!\n\nSearch the realms for all the anima you can gather and deliver it to the sanctum.\n\nTime is short. Move swiftly, {class}.", objectives = "Deposit 600 anima in the Anima Reservoir at Elysian Hold in Bastion." }
WordHunterWoW_QuestEN[60466] = { title = "The Old Ways", description = "You there! Might I ask your help?\n\nI must confess, with the lack of new souls arriving, our supplies have dwindled. We lack the means to clothe arrivals in proper kyrian attire.\n\nBefore the forging of the centurions, aspirants trained against the native wildlife. Perhaps there is another way these beasts can prove useful.\n\nIf you collect materials from the cloudstriders and larions nearby, we can use them to ensure our new arrivals look the part.\n\nOh, and some thread from Mirene, if you would!", objectives = "Collect an Elysian Thread, 4 Cloudstrider Pelts, and 12 Larion Plumes.", progress = "How goes the hunt?", completion = "These are perfect! Go in service, always." }
WordHunterWoW_QuestEN[60467] = { title = "A Rousing Aroma", description = "<Sabina is unresponsive. Her exposed flesh cracked and blistered. Perhaps something with a pungent aroma will rouse her.>", objectives = "Collect 4 Pungent Swarmer Toxin from Ravenous Swarms.", progress = "Sabina remains unresponsive.", completion = "<Sabina begins to stir. >\n\nAre... are they back? Help... help me." }
WordHunterWoW_QuestEN[60468] = { title = "Rubble Rummaging", description = "I do not know how long it's been since my captors left me here, but the Light has... taken its toll. \n\nYou must help me escape. The key to my shackles should be hidden nearby. Perhaps among the rubble? That's likely where I'd hide something small.", objectives = "Find a Shackle Key among the rubble within Ashen Traverse.", progress = "Have you found the key?", completion = "This looks like it could fit." }
WordHunterWoW_QuestEN[60469] = { title = "Safe in the Shadows", description = "I cannot recollect what happened. Perhaps the Light has burdened my memory? Who knows how long I've been out here...\n\nThe last thing I remember before things went dark... my companions and I had finally found refuge in the shadows. I worry for their well-being. \n\nSo long as my assailants remain at large, my companions could be in danger. Will you find them and ensure they're still safe in the shadows?", objectives = "Find out what happened to Sabina's companions.", completion = "They've perished? Are you sure? Who could have done something so cruel..." }
WordHunterWoW_QuestEN[60470] = { title = "Setting Sabina Free", description = "Release me. Please, you must do so. I cannot linger in the Light any longer. \n\nThis unease, it's so... familiar, but it will pass. I will feel myself once again, once I have returned to the shade.\n\nI'll stay as still as silence while you work the lock.", objectives = "Release Sabina from her shackles." }
WordHunterWoW_QuestEN[60474] = { title = "Spawn Tracking Unit-Specified World Effect in a WMO Bug", description = "There seems to be a bug when you setup a world effect containing a gold dot on the minimap through Spawn Tracking that is set to Unit, rather than Objective. It seems to only happen with spawns inside WMOs. Might also be happening with setting it to Object as well.\n\nIf the Spawn Tracking on the World Effect is set to Objective, everything's fine. However, if it is set to Unit, the golden dot will not show up on the minimap.", objectives = "Attempt to figure out why the WMO spawned objective's minimap golden dot will not appear when its spawn tracking is set to Unit instead of Objective." }
WordHunterWoW_QuestEN[60475] = { title = "We'll Workshop It", description = "", objectives = "" }
WordHunterWoW_QuestEN[60476] = { title = "Spriggan Size Me!", description = "", objectives = "" }
WordHunterWoW_QuestEN[60480] = { title = "The Endmire", description = "Oi! You.\n\nNot sure what landed you in the Endmire but I need your help.\n\nSee these torches? It's my gig to keep 'em lit. But it ain't like they runnin' on flint n' tinder.\n\nMy stash of infused rubies got hauled off by some devourers when my back was turned. Can ya find 'em before we both get ate by one of these horrors?", objectives = "Find 5 Infused Rubies.", progress = "Just going to be clear on this: I... HATE... THIS... GIG.", completion = "Much obliged. These torches keep the effects of the Endmire at bay. Even scares away the devourers for the moment. Only lasts so long though. \n\nI miss the good ol' days of only having to worry about manifestations down here." }
WordHunterWoW_QuestEN[60482] = { title = "See With My Eyes", description = "After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. \n\nThere are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now.\n\nJourney to the hold, use my sightless vision to see the weapons and recover what you can.", objectives = "Collect 10 hidden weapons", progress = "Have you recovered the weapons.", completion = "You can kill more of them if you want." }
WordHunterWoW_QuestEN[60487] = { title = "It Used to Be Quiet Here", description = "Well... You don't look like the rest of 'em, do you?\n\n<Chiselgrump shrugs.>\n\nDoesn't bother me. Keep my head down and do my job, making sure these sinstones stay in good shape.\n\nKeep breaking my tools, though.\n\nBring me some more chisels and I'll teach you an old dredger construction trick.", objectives = "Collect 8 Dredger Chisels.", progress = "Got those chisels yet?", completion = "Yeah, these'll last me awhile.\n\nAlright, I'll show you the trick to making a barricade quickly..." }
WordHunterWoW_QuestEN[60489] = { title = "The Path of Ascension", description = "With the anima you collected, we can once again start up the Path of Ascension.\n\nThe eternal training ground of the kyrian, the Path is an ancient tradition and favored amongst many of the kyrian, aspirant and ascended alike.\n\nThe Hands of Courage, Apolon and Artemede, have stepped up to lead this tradition. Once you herald the Path's rebirth, speak to them to learn more.", objectives = "Activate the Path of Ascension.", completion = "By your hand, the coliseum is powered by anima once more. Glory awaits you and your allies in the Path of Ascension!" }
WordHunterWoW_QuestEN[60491] = { title = "Among the Kyrian", description = "You will be well at home among the kyrian, brother. We welcome your aid.\n\nThe Archon was so confident in this outcome that she has arranged a grand reception for you in honor of your efforts against the Maldraxxus incursion into our realm.\n\nFor now, all you must do is journey to the Seat of Eternal Hymns. I shall meet you there.", objectives = "Meet Polemarch Adrestes at the Seat of Eternal Hymns in Bastion.", completion = "Much has culminated in this moment." }
WordHunterWoW_QuestEN[60492] = { title = "A Proper Reception", description = "Though the path you follow is not that of a traditional ascended, it is a kyrian path all the same.\n\nTo follow it is to bask in the footsteps of the innumerable lives before us, forever in service to a good far greater than we can achieve alone.\n\nTo join us amidst such strife is an accomplishment worthy of recognition. Our Archon has called all among us to join her in welcoming you to our ranks.", objectives = "Join the Kyrian Covenant.", progress = "This is the final step of joining our ranks. Should you have second thoughts, have them now.", completion = "May this be but the beginning." }
WordHunterWoW_QuestEN[60493] = { title = "Humble Gatherer", description = "Before your soulbinds step foot in the coliseum, you must challenge your first opponent.\n\nThere is a tradition to this, as with all things. You will need to gather specific items, then bring them back here to fashion armaments to help execute your challenge.\n\nIn the case of your first challenge, you will find the materials throughout Bastion. Return to me once you have collected everything, then we will continue.", objectives = "Collect 2 Depleted Goliath Cores from Forsworn goliaths, 6 Tampered Anima Chargers from Forsworn centurions, and 5 Soul Mirror Shards from Forsworn kyrian.", progress = "Though the Path of Ascension leads to glory, participants must remember to stay humble and grounded in the tradition.", completion = "You have taken the first steps. A commendable feat!" }
WordHunterWoW_QuestEN[60494] = { title = "Your Friend, Dactylis", description = "With the materials you gathered, you are now ready to craft your lure.\n\nReport to Dactylis. She will be able to help you craft not only this, but many more items of all kinds later.\n\nOnce you craft your lure, return to me and I will give you your next instruction.", objectives = "Speak to Dactylis to craft 2 Overcharged Goliath Cores and 1 Soul Mirror.", progress = "Inspired by the Collectors, we must take the time to craft by hand. Through crafting we practice patience, diligence, and humility.", completion = "Every time you craft, a piece of yourself is imbued in whatever you create." }
WordHunterWoW_QuestEN[60495] = { title = "A Suitable Opponent", description = "The opponents you train against in the coliseum are not physical beings, but rather manifestations of such.\n\nYour first opponent is one you and your soulbinds have met numerous times before -- the Ascended Kalisthene.\n\nAsking another kyrian to be your opponent in the Path is a great honor, as it tells them that you have much to learn from them.\n\nGo to Aspirant's Awakening and use the cores to summon Kalisthene by calling back to your first introduction. It is as ceremony states.", objectives = "Use the Overcharged Goliath Cores on the Depleted Goliaths in Aspirant's Awakening, then use the Soul Mirror to capture a memory of Kalisthene.", completion = "Kalisthene will train your friends well." }
WordHunterWoW_QuestEN[60496] = { title = "Into the Coliseum", description = "The time of your challenge has come!\n\nAs you are not a being of Bastion, you shall act as a tactician for your soulbinds. You have developed mighty bonds between each other... let us see how they handle the coliseum.\n\nLet me know when you are ready to begin. Show us the merit of your bonds!", objectives = "Speak to Artemede to challenge the Path of Ascension.", progress = "This is just the first of many challenges ahead of you, <name>. Remember to stay humble.", completion = "A lesson in humility. But not one without purpose.\n\nThis blueprint will serve you well." }
WordHunterWoW_QuestEN[60497] = { title = "Herald's Footpads", description = "Sometimes, sheer force of will is not enough. A piece of equipment can save your life.\n\nThis blueprint you found can teach you to craft your first piece of equipment.\n\nBring it over to Dactylis. She will be able to aid you in this as well.", objectives = "Bring the Blueprint: Herald's Footpads to Dactylis.", progress = "Welcome back. How may I aid you?", completion = "Ah, a new blueprint! Let us get started, yes?" }
WordHunterWoW_QuestEN[60498] = { title = "Overcoming the Trial", description = "These new footpads can give Pelagos the edge he may need to defeat Kalisthene.\n\nReturn to the Path, {name}. Equip Pelagos with these footpads and overcome your opponent.\n\nIt may take a few tries, but all trials do.\n\nGo in service, and in glory!", objectives = "Defeat Kalisthene in the Path of Ascension.", completion = "More trials lie ahead, <name>. Your future experience with the Path of Ascension is yours to guide!" }
WordHunterWoW_QuestEN[60500] = { title = "Halls of Atonement: Medallion of Pride", description = "Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. \n\nI do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. \n\nLord Chamberlain falls into this latter category. His medallion must be taken by force.", objectives = "Recover the Medallion of Pride from Lord Chamberlain within the Halls of Atonement.", progress = "Have you recovered the medallion?", completion = "With this, we are one step closer to realizing the revitalization of Revendreth." }
WordHunterWoW_QuestEN[60501] = { title = "Redemption for the Redeemer", description = "<Energies of death and innervation struggle to free themselves from the blade and consume you to your very core.>\n\n<The bonds of warding placed on this blade by Prince Renathal will not hold for long. It should be taken to Sinfall where more permanent arrangements have been made for this prisoner.>", objectives = "Deliver Remornia to General Draven on the edge of Sinfall.\n\nProvided item:", completion = "Denathrius once served a noble cause. His charismatic leadership and understanding of the dark desires were instrumental in the redemption of more souls than your world has known.\n\nPerhaps in time, he could be this again. If the right lessons were to remind him of his true purpose." }
WordHunterWoW_QuestEN[60502] = { title = "Sanguine Depths: An Ally Within", description = "There are whispers of a prisoner within these depths that may be of use to our cause. \n\nWhether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. \nWe cannot afford to ignore an opportunity such as this. \n\nVenture into the Sanguine Depths and recover this valuable prisoner.", objectives = "Recover the valuable prisoner from within the Sanguine Depths.", completion = "This naaru shall prove an invaluable ally." }
WordHunterWoW_QuestEN[60504] = { title = "Strengthen the Bond", description = "To bond souls is but the first step. You must now explore its potential.\n\nJust as Pelagos will gain strength from you, so too shall you grow from him. As your bond grows over time you will touch deeper into one another's souls, and so your strength shall increase. \n\nAll you must do is place your hand upon the Forge of Bonds to augment your bond. There is no price to pay--the only limitation is your connection to our sacred covenant.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", progress = "This device is merely a pathway to the strength that lies within you both.", completion = "May you prove worthy allies to one another in the trials to come." }
WordHunterWoW_QuestEN[60505] = { title = "Spider's Lair", description = "When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. \n\nHe has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse.\n\nI need you eliminate Manipulator Zalisar and his spider forces.", objectives = "Slay 8 Razorweb Weavers and Manipulator Zalisar.", completion = "Your help is always welcome, Maw Walker." }
WordHunterWoW_QuestEN[60506] = { title = "The Accuser", description = "It is time to hunt our final prey, the Accuser.\n\nAnima drought or not, her sycophantic adherence to sacred \"rituals\" flies in the face of the Master's will. I can't wait to see the fear in her eyes.", objectives = "Hunt the Accuser.", completion = "We meet again. Under dire circumstances I fear." }
WordHunterWoW_QuestEN[60508] = { title = "On the Trail", description = "In my visions, I witnessed Tyrande cutting through an endless storm of malevolent, nightmarish beings.\n\nUp ahead... is that...? Yes. I believe it is the very place I saw.\n\nCome. It may hold a clue as to where my mother has gone.", objectives = "Look for signs of Tyrande Whisperwind.", completion = "Some vile force in this place intends to stop us from finding Tyrande.\n\nIf experience serves, that means we must be on the right track." }
WordHunterWoW_QuestEN[60509] = { title = "Not My Job", description = "Right. So, 'em devourers are going to start creepin' out of the Endmire soon. \n\nAnd with the anima drought puttin' the squeeze to the fangs... well... we ain't gettin' help from them until it's too late.\n\nUs dredgers could use someone in your line of work. Professional destroyer as it were. \n\nIf you can spare the time, meet me out at the Dredgewood. We'll scoop up a couple of lads and see if we can't make a stand.", objectives = "Meet Rendle in the Dredgewood.", completion = "I see you decided to get your hands dirty and join us gents in the labor pool." }
WordHunterWoW_QuestEN[60510] = { title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple in Bastion.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", objectives = "Slay Woeblade the Atrocity.", completion = "May our victory bring them peace." }
WordHunterWoW_QuestEN[60514] = { title = "Hunting Trophies", description = "To be a hopebreaker is to conquer all prey, not just souls.\n\nThe Banewood is home to many dangerous creatures: deathwalkers, fearspinners, and the horrifying doomfangs. If you wish to really master the art of the hunt, you should be able to defeat these foes.\n\nBring me trophies as proof of your conquests. Then, you may just earn my respect.", objectives = "Collect 3 Doomfang Skulls, 3 Pristine Deathwalker Paws, and 3 Prized Fearspinner Fangs.", progress = "Have you conquered the creatures of the Banewood?", completion = "<Constantin examines what you have brought him>\n\nWell done. You may make a fine hopebreaker yet." }
WordHunterWoW_QuestEN[60517] = { title = "The Toll of the Road", description = "This vessel appears to be brimming with anima. It is certainly tolls collected from denizens traveling by this crossroads. I am sure with all that is going on, Mistress Mihaela in Darkhaven would appreciate these tolls brought to her to cover the Village Ward's obligations.", objectives = "Return the tolls to Darkhaven.\n\nProvided item:", completion = "What is this? The road tolls! Varaboss, that conniving fiend, never did master his greed. Your kind prefers this precious metal as recompense I believe." }
WordHunterWoW_QuestEN[60519] = { title = "Audience with the Winter Queen", description = "Zephyrs herald the Queen's arrival. Hushed silence descends upon the grove.\n\nWait, watch, and speak when the time has come.", objectives = "Speak to Moonberry and await the Winter Queen's arrival.", progress = "The Queen shoulders so much because of this drought. But she is powerful, and I know we will make it through.", completion = "Gone so soon... the forest must be in even more dire straits than I realized.\n\n<Moonberry looks crestfallen for a moment before resolutely setting her hands on her hips.>\n\nWell, then we'll just have to help ease the Queen's burden. Then she'll have the time to grant you an audience!" }
WordHunterWoW_QuestEN[60520] = { title = "Nightmares Manifest", description = "Oh, this isn't good. As soon as you left, the spirit's nightmares spilled out all over Tirna Vaal. \n\nI've done everything to try to soothe her. I've tried singing to her, I've tried telling her stories, but nothing I do seems to calm her.\n\nPlease, would you confront and dispel her nightmares? That might be the only thing that will work.", objectives = "Confront the wildseed's nightmares in Tirna Vaal.", progress = "Her dreams are usually beautiful.", completion = "There, that seems to have calmed her. I can feel her dreams begin to ease.\n\nYou really do have a knack for this!\n\nBut I'm worried that we're only buying time, and we need to do something more drastic." }
WordHunterWoW_QuestEN[60521] = { title = "Call of the Hunt", description = "You've done so much, but the Queen's focus is still divided across the forest.\n\nIf you want to deliver your message, then we need to help lessen her burden.\n\nLet's start with the Wild Hunt. They are the protectors of Ardenweald, and dealing with the threat of the masked fae has stretched them thin.\n\nSeek out Hunt-Captain Korayn at Glitterfall Basin. Last I heard, her hunting party could use reinforcements.\n\nAnd don't let her ferocity put you off. She's quite nice as long as you're not her prey!", objectives = "Seek out Hunt-Captain Korayn in Glitterfall Basin.", completion = "Lady Moonberry said she would be sending a strong hand to help secure this grove.\n\nNow, how are you in a fight?" }
WordHunterWoW_QuestEN[60522] = { title = "Return to Tirna Vaal", description = "We of the Wild Hunt are always prepared to return to the cycle in defense of Ardenweald.\n\nI must move on, and so should you. I advise you to return to Droman Tashmur in Tirna Vaal. Others will need your help.\n\nHere, take this. It is a gift and a thank you.\n\nHelping each other is the only way to survive this drought.", objectives = "Return to Tirna Vaal.", completion = "Oh, you have a spirit cradle! That will be quite useful, indeed.\n\nAssuming we can calm this chaos, of course. The wildseed you bonded with is having intense nightmares... and they're manifesting all over the grove!" }
WordHunterWoW_QuestEN[60530] = { title = "The Sea of Souls", description = "Some force here seeks to keep us from finding Tyrande.\n\nThe trail of bodies seems to go into this... stream of souls. \n\nI suggest we split up. I will follow along the bank of the river. You enter its current and follow the trail.\n\nShould you need me, I will be close at hand.\n\nWe will find Tyrande, no matter where this course leads.", objectives = "Follow the trail of corpses to Tyrande Whisperwind.", completion = "Tyrande must see reason. She cannot save the kaldorei if she remains lost within this darkness." }
WordHunterWoW_QuestEN[60531] = { title = "Chosen Champions", description = "", objectives = "" }
WordHunterWoW_QuestEN[60532] = { title = "Destroy the Dominant", description = "", objectives = "" }
WordHunterWoW_QuestEN[60533] = { title = "Terrors in Tirna Scithe", description = "", objectives = "" }
WordHunterWoW_QuestEN[60534] = { title = "Disloyal Denizens", description = "", objectives = "" }
WordHunterWoW_QuestEN[60542] = { title = "Nathanos Blightcaller", description = "", objectives = "" }
WordHunterWoW_QuestEN[60545] = { title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Stormwind, and I will take you to him.\n\nI would not keep him waiting.", objectives = "Meet Darion Mograine outside Stormwind Keep.", completion = "It is good that you have arrived.\n\nWe need heroes like you in this dire hour." }
WordHunterWoW_QuestEN[60557] = { title = "First Time? You Have to Fight!", description = "When it comes to warfare, strength of will is as critical as strength of arms. A demoralized soldier is a defeated soldier!\n\nWe have the numbers to overwhelm the constructs with a full scale assault, but only if our forces are fully committed to the charge. Some may fall, but their sacrifice will secure our victory!\n\nTake this battle horn and rally our troops. Remind them of their duty to the Chosen!", objectives = "Rally 8 demoralized soldiers.", progress = "Have you rallied the troops?", completion = "Our forces stand ready to fight once more!" }
WordHunterWoW_QuestEN[60559] = { title = "Unused", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[60563] = { title = "Tending to Wildseeds", description = "We infuse wildseeds with anima from the animacones we collect in the surrounding area.\n\nBut the caretakers are missing, and we have wildseeds in need of an anima infusion.\n\nThis is an absolute mess that must be corrected before the Winter Queen arrives!\n\nI've already gathered a basket of animacones. Can you use them to infuse a few of the wildseeds?\n\nI'll show you how it's done, but then I have to look for the missing caretakers.", objectives = "Collect basket of animacones, then use them on 4 wildseeds.", completion = "Fine work. We mustn't stop tending to the wildseeds that the Winter Queen has chosen to be saved.\n\nNow, perhaps you can lend me a hand with another matter." }
WordHunterWoW_QuestEN[60564] = { title = "Three Gorm Enter, No One Leaves", description = "", objectives = "" }
WordHunterWoW_QuestEN[60565] = { title = "A Steward for Every Occasion", description = "", objectives = "" }
WordHunterWoW_QuestEN[60566] = { title = "Into the Light", description = "I am afraid that you must endure the next stretch of the stroll without me, {name}.\n\nWhile my compatriots and I have secured access to the elevator that shall carry us up to Sinfall, we are unable to utilize it.\n\nThe Master has redirected a massive beam of Light directly onto the elevator's landing.\n\nVenthyr that get close are obliterated.\n\nDredgers sent up never return.\n\nWe need someone who can walk in the Light to discover what is happening up there.\n\nLady Sybille will show you the way.", objectives = "Take the elevator up to Sinfall and investigate the area.", completion = "<Breakfist is badly injured.>\n\nToo many... couldn't make it..." }
WordHunterWoW_QuestEN[60567] = { title = "Shooing Wildlife", description = "Things are chaotic here in the Tranquil Pools. I'd be devastated if the Winter Queen saw this.\n\nThis is meant to be a peaceful place where we give anima to wildseeds.\n\nBut with the current drought, starving beasts have encroached on the pools and are trying to feed on the anima themselves.\n\nSadly, we need to put them down... or else they may endanger the spirits within the wildseeds.", objectives = "Slay 8 Anima-Starved wildlife.", progress = "I hate having to do this, but if it's a choice between sparing the beasts and saving the wildseeds, I have to choose the wildseeds.", completion = "Normally, I wouldn't require help from whatever race you are.\n\nAh... my apologies. That was rude.\n\nPlease understand that Ardenweald is home to souls from across all of the mortal realm. It's hard for me to keep track of every race that arrives here." }
WordHunterWoW_QuestEN[60568] = { title = "TEMP MAW RUN", description = "<Placeholder Quest. Thank you for your patience as our dev team works to make the Maw experience the coolest thing we can. In the meantime, please enjoy a sample of a snarky sword and her fourth wall breaking objectives.>\n\nLook, normally I would give you a quest to storm the very Maw itself looking for Prince Renathal before he gets transferred in to the dreaded Torghast, Tower of the Damned.\n\nHowever, since that is NOT something we can do. Let's just assume we did and go talk to that projection of him", objectives = "Speak with Projection of Prince Renathal.<Placeholder Quest. Thank you for your patience as our dev team works to make the Maw experience the coolest thing we can. In the meantime, please enjoy a sample of a snarky sword and her fourth wall breaking objectives.>\n\nLook, normally I would give you a quest to storm the very Maw itself looking for Prince Renathal before he gets transferred in to the dreaded Torghast, Tower of the Damned.\n\nHowever, since that is NOT something we can do. Let's just assume we did and go talk to that projection of him" }
WordHunterWoW_QuestEN[60572] = { title = "For the Sake of Spirit", description = "With all of the anima you recovered from Tirna Noch, it is only a matter of time before my grove becomes the target of every anima-seeking enemy of Ardenweald.\n\nI hope Dreamweaver knows what he is doing with this ritual.\n\nProceed quickly. Speak with Dreamweaver, and see what needs to be done to aid the spirit within the wildseed.", objectives = "Speak with Dreamweaver to prepare the ritual.", completion = "You're ready to begin preparing for the ritual? Wonderful.\n\nI am also ready!" }
WordHunterWoW_QuestEN[60573] = { title = "Meatball's Revenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[60574] = { title = "Shaking 'Shrooms", description = "", objectives = "" }
WordHunterWoW_QuestEN[60575] = { title = "Belly Full of Fae", description = "The local flora have gone somewhat wild during this anima drought.\n\nIt seems they swallowed most of the young fae who were tending to the wildseeds here.\n\nAt least now we know where they've been.\n\nOh, don't worry. This isn't the first time this has happened. We can last quite a while inside those plants.\n\nTake my dagger. Use it to cut through the shrubbery and free the other wildseed tenders.", objectives = "Free 16 Wildseed Tenders from inside Devouring Hydra.", progress = "How goes the gardening?", completion = "Great work. This should help get the Tranquil Pools back to normal.\n\nI admit, I had thought the worst when I couldn't find any of the tenders. I'm glad they were only eaten by the local vegetation." }
WordHunterWoW_QuestEN[60577] = { title = "Hungry for Animacones", description = "I have to apologize for the state of the Tranquil Pools. Normally, it's quite peaceful here.\n\nThe wildseed tenders tell me that the plants you see walking around have eaten all the animacones intended for use in Tirna Vaal.\n\nCould you rip the animacones out of those plants?\n\nWe have wildseeds that are in need of that anima.", objectives = "Recover 25 Animacones from Gobbling Blossoms.", progress = "Have you found the animacones? They're still useful, even if they're a little slimy. \n\nTrust me, the spirits don't mind as long as they get their anima.", completion = "The animacones! In this time of drought, we have to scrounge for every bit of anima we can get. Thank you." }
WordHunterWoW_QuestEN[60578] = { title = "Visions of the Dreamer: The Betrayal", description = "I sense that in the spirit's vision, she struggles with the memory of a betrayal that is truly profound. \n\nSomeone as close to her as a brother, turned to an enemy.\n\nGo to the second Dreamshrine in the Basin, and help vanquish the pain of this nightmare.", objectives = "Grapple with the Dreamer's vision of a great betrayal.\n\nIf you leave the Vision, interact with a Dreamer's vision portal in Dreamshrine Basin to enter again.", progress = "Have you seen what dreams have come?", completion = "To have an old friend turn against you, in the most terrible way. How very painful. \n\nBut we are so close now, to soothing the spirit within the wildseed." }
WordHunterWoW_QuestEN[60585] = { title = "Spriggan Riot", description = "", objectives = "" }
WordHunterWoW_QuestEN[60594] = { title = "One Special Spirit", description = "You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds.\n\nI'd love for you to come with me. It's only fair, since you're the one who recovered the animacones.\n\nI'm quite excited for you! Let's go.", objectives = "Go with Dreamweaver to feed anima to the wildseed in Tirna Vaal.", progress = "The howling wind becomes a gentle breeze. All is well once again.", completion = "Starlight shines within Dreamweaver, radiant and serene.\n\nAnd... two rivers meet in a lush delta. A wildseed and a mortal, both new to the forest. Bonded by spirit and by fate.\n\nLong has it been since the boughs beheld such an event. The weald will be watching." }
WordHunterWoW_QuestEN[60597] = { title = "Trouble at the Gormling Corral", description = "", objectives = "" }
WordHunterWoW_QuestEN[60599] = { title = "Soul Shape", description = "", objectives = "" }
WordHunterWoW_QuestEN[60600] = { title = "Preparing for the Winter Queen", description = "Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you.\n\nYou have more than upheld your end of our bargain... and yet I was not able to do the same.\n\nThat is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement?\n\nPlease, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!", objectives = "Receive Ardenweald's essence from Lady Moonberry.", progress = "Joy follows Lady Moonberry, a scent that lingers as a flower blooms.", completion = "Shadows loom over Heartwood Grove. Things unseen crawl within the darkness." }
WordHunterWoW_QuestEN[60601] = { title = "Darkwing Drills", description = "", objectives = "" }
WordHunterWoW_QuestEN[60602] = { title = "Secret Service", description = "", objectives = "" }
WordHunterWoW_QuestEN[60605] = { title = "Glimmerfin Scale", description = "<A brightly-colored scale fell to the ground as the murloc ran off. It was unlike any other murloc you've seen in Northrend.\n\nPerhaps King Mrgl-Mrgl would know more about this new species?>", objectives = "Show the scale to King Mrgl-Mrgl in Borean Tundra.", completion = "What do you have there? Oh! Isn't this colorful.\n\nYou say there's a new band of murlocs down south? That doesn't surprise me, strange things have been happening in the waters far from here, from what I've heard.\n\nWell, if they're friendly, it's up to us to welcome them! Here's a few potions, you're probably going to need them." }
WordHunterWoW_QuestEN[60606] = { title = "Glimmerfin Welcome", description = "First thing's first, they're probably hungry. Life up here in the cold isn't quite as easy as it is elsewhere, and even the most acclimated murlocs sometimes have trouble finding food.\n\nWe're going to need to feed them, but also help them find food for themselves.\n\nThey're already watching you, so search the area around where you found the murlocs for food sources and show them what to hunt. Then bring the meat to their leader--just look for the biggest one.", objectives = "Collect 10 Meaty Crab Chunks and deliver them to Glimmergut in Venture Bay.", progress = "Mrgg?", completion = "Mrg?\n\n<Glimmergut looks at you, then cautiously takes the crab chunks and hands them to a nearby forager. The forager and Glimmergut appear to have a short conversation about your crab hunt.\n\nGlimmergut turns back to you and points down at the sand.>" }
WordHunterWoW_QuestEN[60609] = { title = "Who Devours the Devourers?", description = "", objectives = "" }
WordHunterWoW_QuestEN[60614] = { title = "A Big Horkin' Task", description = "<Glimmergut begins to draw in the sand.\n\nThe murloc traces the outline of what appears to be a large seal. He points at the picture, then upwards, indicating that the creature must be somewhere on the surface of the water.\n\nThe murloc then digs a small, shallow hole in the sand, and points at it several times.>\n\nMrg! Mrg! Grml.\n\n<He cocks his head expectantly.>", objectives = "Collect one Pile of Blubberfat and deliver it to Glimmergut in Venture Bay.", progress = "Grmgr?", completion = "Grml! Mrgl-rgml. M'gurgle.\n\n<Glimmergut looks at the foragers next to him. They nod, and he nods back.>" }
WordHunterWoW_QuestEN[60615] = { title = "Seer of the Waves", description = "<Glimmergut points across the ship. He wants you to take the blubber to someone.>\n\nMrg m'grrl.", objectives = "Deliver the Blubberfat to the Glimmerfin Oracle.", completion = "<The oracle takes the blubberfat from you, as if expecting your arrival, and arranges it in a small pile.>" }
WordHunterWoW_QuestEN[60616] = { title = "Pearl in the Deeps", description = "<The oracle draws a circle in the sand, then points down into the deeps. There is something round down there that she is after, perhaps a pearl or stone?\n\nThe oracle motions for you to wait a moment before you leave. She waves her hands around frantically, then places them under her mouth, mimicking two large fangs.\n\nYou take this as a warning that there may be something waiting for you in the icy darkness.>", objectives = "Collect the Giant Pearl and deliver it to the Glimmerfin Oracle.", progress = "<The oracle looks at you.>", completion = "<The oracle takes the pearl from you and rubs it gently before peering deeply into its shimmering depths.>" }
WordHunterWoW_QuestEN[60617] = { title = "Trainer's Test", description = "<The oracle finishes peering into the pearl and turns to face you. She appears to be deep in thought, staring directly at you and blinking a few times.\n\nFinally, she nods. \n\nThe oracle points at you, then points upwards. She places a hand a small distance above the ground, indicating something pet-sized.\n\nYour surmise that there may be test of your connection with your battle pets ahead.>", objectives = "Defeat Trainer Grrglin in a pet battle.", progress = "<The oracle looks very excited.>", completion = "<The oracle looks excited at your return. She points rapidly down at the blubber pile next to her, where an egg has been softly nestled.>" }
WordHunterWoW_QuestEN[60619] = { title = "Wrap it Up", description = "<The seems quite excited about the presence of the new egg. You get the sense that this is an important occasion for these murlocs--there may be few eggs left.\n\nThe oracle waves a small piece of seaweed in front of you, showing you the young buds of the immature plant.\n\nShe warps the seaweed around a small part of the egg, then points at you, then back at the wrapped seaweed.\n\nIt appears that the egg needs to be wrapped in more immature seaweed stalks.>", objectives = "Collect a Warm Seaweed Stalk, a Young Seaweed Stalk, and a Bulbous Seaweed Stalk and deliver them to the Glimmerfin Oracle.", progress = "<The oracle blinks at you.>", completion = "<The oracle wraps the egg gently in the seaweed.>" }
WordHunterWoW_QuestEN[60620] = { title = "Guardian of the Smallest", description = "<The oracle pats you on the shoulder, and seems quite pleased with all that you've done.\n\nShe holds up one finger, then spreads her hands wide and emits a terrible roar-like murgle.\n\nShe points outside, then at you, then your weapon, then nods seriously.\n\nThere must be one more trial to await you. It would appear to be a test of strength.>", objectives = "Slay Great Mua'kin and return to the Glimmerfin Oracle.", progress = "<The oracle claps excitedly.>", completion = "<The oracle pats you excitedly on the shoulder, and raises her arm in triumph.\n\nShe starts, then points quickly at the egg and rushes over.\n\nThe egg begins to hatch...>" }
WordHunterWoW_QuestEN[60621] = { title = "Enemies at the Gates", description = "Lorkron is here. \n\nI tracked him all the way from the Glittering Falls. Then I saw the Drust try to flank our forces.\n\nI'd say they were rather surprised that we turned the tables against them.\n\n<Korayn's smile is fierce. She lifts her weapon and her voice to address all present.>\n\nHuntsmen and huntresses, with me! We ride to defend the grove! Take no prisoners and leave none standing!", objectives = "Reach Droman Aliothe in Hibernal Hollow.", completion = "This attack... It is like they are being driven!" }
WordHunterWoW_QuestEN[60622] = { title = "Eye of the Scryer", description = "Evading the Mawsworn's scryers requires powerful magical countermeasures.\n\nThe prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance.\n\nThe scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye.\n\nRestraint is advised in its procurement.", objectives = "Obtain the Eye of the Scryer from Leerok the Scryer in The Maw.", progress = "Well? Do you have it, undamaged?", completion = "Do you think he saw that one coming?\n\nThat was an attempt at mortal humor. You may laugh at your leisure." }
WordHunterWoW_QuestEN[60623] = { title = "AHHH! Real Monsters!", description = "", objectives = "" }
WordHunterWoW_QuestEN[60624] = { title = "Ride to Heartwood Grove", description = "A storm of strife and fear rains down upon Heartwood Grove. Sylvar flee from the flood.\n\nBrave the torrent astride a stag. Becalm the deluge and be the salvation of those who would drown.\n\nMake haste. Time wanes.", objectives = "Ride a stag to Heartwood Grove.", completion = "We can't leave Heartwood Grove like this." }
WordHunterWoW_QuestEN[60628] = { title = "The Missing Hunters", description = "Strange creatures have been seen lurking just outside the grove. Terrible, ugly things.\n\nWhatever they might be, they are not native to Ardenweald. \n\nIt does not matter how they breached our borders, though. Every one of them must be eliminated.\n\nI sent my best huntsmen and huntresses to slay them, but not one has returned. See if you can determine what has delayed them.", objectives = "Find Jynkla, Serinkai, Rondar, and Ara'lon.", completion = "Only Ara'lon and Lumera survived? The rest have fallen?\n\n<Korayn trembles with unbridled fury.> \n\nI will see to it that their bodies are retrieved. And this cannot go unpunished. We will avenge them all!" }
WordHunterWoW_QuestEN[60629] = { title = "Extreme Recycling", description = "The Wild Hunt serves the Winter Queen under the leadership of Lord Herne. We are elite fighters, hunters, and trackers.\n\nBut we cannot fight without weapons and supplies. The droman here informs me that there are severe obstacles to their delivery.\n\nI do not have time to wait. We need equipment, and we need it now.\n\nSee what you can scavenge from the field. A broken weapon can always be mended and put to use again.", objectives = "Slay the Blighted and take their weapons.", progress = "Did you find anything of use out there?", completion = "You found far more weapons than I expected.\n\nVery strange. How could they acquire so many of OUR blades?\n\n<Korayn appears troubled.>\n\nThey will be used against our enemies again, I swear it." }
WordHunterWoW_QuestEN[60630] = { title = "Totem Eclipse", description = "I can smell our foes' dark magic, twisting the air and muddling my mind. They are up to something. Bringing awful powers into Ardenweald.\n\nIf you see any of their totems, destroy them immediately. \n\nI always feel better after smashing something to pieces, don't you?", objectives = "Destroy Foul Totems.", progress = "What terrible magic has been brought into Ardenweald?", completion = "If it was not clear before, it is now. This is a personal hunt.\n\nWe will rid Ardenweald of this monster." }
WordHunterWoW_QuestEN[60631] = { title = "Big Problem, Little Vorkai", description = "Ara'lon's report matches what I have seen. Too many enemies, and too few of the Wild Hunt to dispose of them on our own.\n\nFortunately, I feel strongly inclined to take matters into my own hands. And avenge my fallen hunters. \n\nLet us depart. We will show those monsters the fury of nature.", objectives = "Slay Blighted with Korayn.", progress = "Ardenweald will endure.", completion = "We have slain so many, and yet more remain. We must get to the heart of this evil and tear it out.\n\nIf we don't, then soon it could spread all across Ardenweald." }
WordHunterWoW_QuestEN[60632] = { title = "I Know Your Face", description = "This voice... I have heard it before. Though it is distorted and vengeful now.\n\nHe hunts us.\n\nBut I am not prey. And I will not let him gloat over his slain quarry. That is not the way of the Wild Hunt.\n\nThough he may draw us to ground of his choosing, we will fight him.\n\nAnd we will win. Are you with me?", objectives = "Defeat Lorkron the Hunter.", completion = "It cannot be easy for Korayn to hunt one of our own... but she is right. The forest is not safe so long as Lorkron lurks within it.\n\nWhat a terrible fate... both for those who become possessed, and those who must hunt them down." }
WordHunterWoW_QuestEN[60637] = { title = "The End of Former Friends", description = "Heartwood Grove was to give up its anima so that other groves could survive.\n\nBut then... I started seeing these masks on many of the other fae. Soon, everyone was wearing them.\n\nI don't know what has come over them, but it's clear they mean us harm. Please... you have to...\n\nThey aren't the friends I once knew. Not anymore.", objectives = "Slay 8 possessed creatures in Heartwood Grove.", completion = "Thank you. I tried so hard to save them... but once that mask is on, there is no return." }
WordHunterWoW_QuestEN[60638] = { title = "Recovering Wildseeds", description = "One of my tasks in Heartwood Grove was to tend to the wildseeds.\n\nSome were chosen to be brought back to Tirna Vaal. But now the masked fae are draining the anima from them!\n\nWe need to save the ones that remain. I beg of you, recover any surviving wildseeds you can find.\n\nThe spirits within them were chosen to be reborn. I won't let them wither away!", objectives = "Recover 6 Drained wildseeds in the Heartwood Grove.", progress = "We need to split up and rescue as many wildseeds as we can.", completion = "You found more wildseeds! They're so weak... I can't stand to see them like this.\n\nWe need to finish this and bring them to Tirna Vaal as soon as possible." }
WordHunterWoW_QuestEN[60639] = { title = "Heart of the Grove", description = "We were supposed to take the heart of the grove to Tirna Vaal when we left this place to wither.\n\nThe masked fae struck before that could happen. They must be after the heart of the grove!\n\nThe heart contains all of the anima that was meant to save the other groves. We can't afford to lose it.\n\nCan you secure it? I need to find Korenth, one of our healers. His skills will help any survivors we find.", objectives = "Bring the Heart of the Grove to Tirna Vaal.", progress = "Do you have the heart of the grove?", completion = "Korenth is... gone? And the heart of the grove has been taken?\n\nThen... then we have much to do." }
WordHunterWoW_QuestEN[60640] = { title = "Regrowth of the Grove", description = "The grove thrives, my mortal friend, but there is yet room for it to grow.\n\nWith enough anima, it can nourish even more wildseeds at once. Each one is a spirit that might otherwise be lost forever.\n\nSpeak with Zayhad once again, and see to the regrowth of the conservatory.", objectives = "Upgrade the Queen's Conservatory to Tier Three.", completion = "Your efforts revitalize the grove, and with it, countless spirits in need of aid." }
WordHunterWoW_QuestEN[60641] = { title = "Blossoming of the Grove", description = "The conservatory grows hearty and hale. Now, it must blossom anew.\n\nThough it requires much in the way of anima, every additional spirit that the conservatory rebirths returns your generosity tenfold.\n\nConfer with Zayhad, so that this conservatory may grow ever larger.", objectives = "Upgrade the Queen's Conservatory to Tier Four", completion = "You have this grove's gratitude. Yet more spirits may now rejoin the cycle." }
WordHunterWoW_QuestEN[60642] = { title = "The Grove Resplendent", description = "You have done much to return the conservatory to its former splendor.\n\nIn ages past, this grove was a place of convalescence for spirits who were wounded upon their demise, and needed special care before being reborn.\n\nIt was a place rarely used... but now, it is critical to the continuation of the cycle.\n\nTell Zayhad that the time has come. The Queen's Conservatory must thrive for the good of Ardenweald.", objectives = "Upgrade the Queen's Conservatory to Tier Five", completion = "The conservatory, and the spirits who are tended here, are forever in your debt.\n\nThank you, Maw Walker." }
WordHunterWoW_QuestEN[60643] = { title = "[OLD NOT USED]", description = ".", objectives = "" }
WordHunterWoW_QuestEN[60644] = { title = "Draw Out the Darkness", description = "Now that we have the dagger, it will take the combined will of all of us to sever the weapon's link to the High Chieftain. \n\nJaina, Anduin, and I must do our part to keep Baine's spirit grounded, so it will be up to you to deal with whatever force is unleashed when the blade is broken.\n\nAre you up to the task?", objectives = "Draw out and defeat the Withering Presence in Detrithos.", completion = "Were it not for your efforts, I am certain my body and soul would be trapped in this forsaken place for eternity.\n\nI owe you my life, <name>, and I will fight to my last breath to repay this debt." }
WordHunterWoW_QuestEN[60645] = { title = "Gargantuan Seeker", description = "", objectives = "" }
WordHunterWoW_QuestEN[60646] = { title = "Misery Business", description = "The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls.\n\nWhy? I do not know yet. But it behooves us to stop them.\n\nDestroy the conduits that they deposit the misery into and bring me some samples of their work. \n\nPerhaps with some research, I can discern their intentions.", objectives = "Collect 10 Essences of Misery and destroy the Misery Conduits.", progress = "Have you halted their misery?", completion = "Your burden is great, but today you have saved souls from damnation." }
WordHunterWoW_QuestEN[60647] = { title = "Recovering the Animacones", description = "The grove's droman is wearing one of the masks. I fear he's going to drain all of the anima from the grove's heart!\n\nThat anima is meant for the forest's other groves. If we lose it... then Heartwood Grove would have been lost for nothing...\n\nWe'll carve a path to the Shrouded Mire to find the droman before it's too late.\n\nMany of these masked fae have stolen Heartwood Grove's animacones. We must recover them along the way. \n\nIn this drought, every bit of anima is precious.", objectives = "Recover 25 animacones from the Possessed.", progress = "We can't let the possessed take anything else from us.", completion = "So many animacones lost... at least we were able to recover these." }
WordHunterWoW_QuestEN[60648] = { title = "Survivors of Heartwood Grove", description = "Korenth... I can't believe he's...\n\nWe have to save whomever we can. Droman Krelnor is too strong for us to face alone.\n\nI saw a few other survivors scattered around the grove. Hurry, we have no time to waste!", objectives = "Rescue Casad, Wagonmaster Derawyn, and Te'zan from the possessed.", progress = "We must rescue my friends!", completion = "Derawyn... I can't lose her too! We can use the animacones to save her!" }
WordHunterWoW_QuestEN[60649] = { title = "A Thorn In Their Side", description = "", objectives = "" }
WordHunterWoW_QuestEN[60651] = { title = "Champion: Meatball", description = "", objectives = "FEED ME!" }
WordHunterWoW_QuestEN[60653] = { title = "Mirror Restoration", description = "", objectives = "" }
WordHunterWoW_QuestEN[60654] = { title = "Swarming Souls", description = "", objectives = "" }
WordHunterWoW_QuestEN[60655] = { title = "A Stolen Stone Fiend", description = "", objectives = "" }
WordHunterWoW_QuestEN[60656] = { title = "Summon Your Sins", description = "", objectives = "" }
WordHunterWoW_QuestEN[60657] = { title = "Aid From Above", description = "", objectives = "" }
WordHunterWoW_QuestEN[60658] = { title = "An Endless Appetite", description = "", objectives = "" }
WordHunterWoW_QuestEN[60659] = { title = "Light Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[60660] = { title = "Flight Test", description = "I fix these to my arms... then they become wings, yes?\n\nThen I jump off cliff. And fly!\n\nYou watch?", objectives = "Observe Kowalskos' test flight.", progress = "Did you watch me?", completion = "Hmm... did not work. What else, what else..." }
WordHunterWoW_QuestEN[60661] = { title = "Dying Dreams", description = "We have lost so much... and this one is special.\n\n<Moonberry looks at you, resolute. Her voice is strangely formal, her manner commanding.>\n\nCome, {name}. We will carry her on the Path of Rebirth and entreat the Queen to save her.\n\nHurry and make preparations. We have little time.", objectives = "Take Ysera's wildseed to the Heart of the Forest.", completion = "Well met, stranger. You arrive in... interesting times.\n\n<Herne snorts a laugh.>\n\nAnd with equally interesting company." }
WordHunterWoW_QuestEN[60669] = { title = "Cause for Distraction", description = "The Horde has come under siege, {name}.\n\nThe undead Scourge rises like a grim tide, in numbers not seen since Arthas Menethil sat upon the frozen throne. \n\nAnd as if that were not concerning enough... something terrible has occurred.\n\nWhat I am about to tell you, I share in the strictest confidence. This information will be known by all soon enough, but I needed to speak with you directly first.\n\nAllow me to explain.", objectives = "Speak with Lor'themar Theron atop Grommash Hold in Orgrimmar.", progress = "There is much to discuss.", completion = "Though we must search for Thrall and Baine, we cannot neglect the protection of our citizens and allies in the process.\n\nAs such, I have enlisted the aid of those who are experienced in dealing with the Scourge." }
WordHunterWoW_QuestEN[60670] = { title = "Return of the Crusade", description = "I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. \n\nThe fate that befell Silvermoon must never be repeated. \n\nDeath knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements.\n\nThe Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, {name}.\n\nTheir commander awaits your arrival.", objectives = "Speak with Commander Throgg in the Valley of Strength in Orgrimmar.", completion = "<Commander Throgg grunts.>\n\nYou must be the one." }
WordHunterWoW_QuestEN[60671] = { title = "The Sacrifices We Must Make", description = "Hurry! We can use the animacones we gathered to save Derawyn.\n\nI know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", objectives = "Use the recovered animacones to save Wagonmaster Derawyn.", completion = "The heart of the grove...\n\nWe have to get it back... for all those who have fallen." }
WordHunterWoW_QuestEN[60673] = { title = "The Traitor", description = "Right, looks like I should let you in now.\n\nCan't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that.\n\nWonder what happened to her. Denathrius seemed awfully upset when they last spoke.\n\nAnyways, let me just get that door open for ya.", objectives = "Kill Sinkeeper Mateo and collect his mirror shard.", progress = "Do you have Mateo's mirror shard?", completion = "He showed so much promise in his duties.\n\nI suppose the promise of power was too much for him to resist. But now is not the time to dwell on such things, <name>. Let us proceed." }
WordHunterWoW_QuestEN[60709] = { title = "Recovering the Heart", description = "Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove.\n\nAnima drains from the heart, nectar taken from ripened fruit. It must be stopped.\n\nFoul magic bars the way. Anima in peril, anima the salvation.\n\nBeseech Te'zan. An old soul, brimming with anima, the spark to ignite our hope.", objectives = "Speak with Te'zan to break down the droman's barrier, then confront Droman Krelnor.", completion = "We've lost so much. Why would anyone do this?" }
WordHunterWoW_QuestEN[60721] = { title = "The Anima Must Flow", description = "This device you see here can be used to send anima to the thirsting wards, aiding our people.\n\nAs each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.", objectives = "Use the Anima Conductor to channel anima to a location in Revendreth.", completion = "Anima is flowing to a ward once more. You will want to return to the device periodically and channel more.\n\nAs you gather anima and channel it into Revendreth, the flows will grow stronger. Though they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nWith anima flowing into our lands once again, it is only a matter of time until we unite all of Revendreth under our banner." }
WordHunterWoW_QuestEN[60722] = { title = "Tower Power", description = "This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them.\n\nThough you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes.\n\nUse the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.", objectives = "Use the Anima Conductor to channel anima to a location in Maldraxxus.", progress = "The anima must flow!", completion = "Yes, yes! I feel the flow of anima. You will want to return to the device periodically and channel more.\n\nAs you gather and channel more anima to a tower, its connection to our sanctum will grow stronger. Eventually you will be able to reinforce the channel, making it permanent.\n\nWith enough anima flowing throughout Maldraxxus, our armies will be unstoppable!" }
WordHunterWoW_QuestEN[60723] = { title = "The Roots Thirst", description = "This device can soak the roots of our great canopy in anima. The branches thirst for it.\n\nAs each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade.\n\nNow, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.", objectives = "Use the Anima Conductor to channel anima to a location in Ardenweald.", progress = "The leaves shake in anticipation.", completion = "The roots are soaked in anima once more. Return to the device periodically and channel more anima, so that all may drink deeply.\n\nAs you gather anima and channel it, the flows will grow stronger. While they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nSoon, all will open their blossoms and bloom in full once more." }
WordHunterWoW_QuestEN[60724] = { title = "Heartless", description = "So many of my friends have returned to the cycle... all because of those strange masks.\n\nWhy did they take my friends? What was the point of destroying the heart of my grove?\n\nYou have to return to Tirna Vaal and tell Droman Tashmur what happened here. \n\nI'll make my way there eventually. I just... need some time to say goodbye.", objectives = "Return to Droman Tashmur in Tirna Vaal.", completion = "Shadows loom over the weald, harbingers of tragedy to come.\n\nThe river of fate flows swiftly, its currents inexorable. Where they lead... cannot yet be seen." }
WordHunterWoW_QuestEN[60725] = { title = "Field Reports", description = "We cannot anticipate where and when the Scourge will strike.\n\nIn order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them.\n\nSeek out my field officers along the southern road. I expect a full report when you return.", objectives = "Gather reports from officers in Durotar and the Barrens.", progress = "Reinforcements? Thank the Light!", completion = "The situation appears far more dire than we thought...\n\nCommander Throgg must hear of this." }
WordHunterWoW_QuestEN[60726] = { title = "[OLD NOT USED]", description = "[OLD NOT USED]", objectives = "" }
WordHunterWoW_QuestEN[60727] = { title = "A Message from Icecrown", description = "Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance.\n\nWe must respond to this summons at once, no matter what terrors await us in Icecrown.\n\nA {class} like you would do much to bolster our chances on the battlefield.\n\nYou have my word that Orgrimmar will be protected in your absence.\n\nBattle calls, {name}. I trust you are ready.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", completion = "You arrive just in time. Commander Throgg spoke highly of you." }
WordHunterWoW_QuestEN[60732] = { title = "Disrupting the Flow", description = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served.\n\nThe complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done.\n\nSend the inhabitants of Zovaal's Cauldron a message.>", objectives = "Disrupt the Mawsworn's efforts in Zovaal's Cauldron.", completion = "Rejoice in your accomplishment, but do not forget the weight of your actions.\n\nHe is always watching." }
WordHunterWoW_QuestEN[60733] = { title = "Front and Center", description = "The runes on that blade... they are the same as the ones etched on the door to the Seat of the Primus. \n\nAnd one of them just began to glow...\n\nIs this what I think it is, {name}? Do you have the means to unseal the Seat? \n\nIf so, then perhaps Vyraz's gambit was not for nothing. This could turn the tide of the entire war!", objectives = "Empower the Rune of Might at the Seat of the Primus.", progress = "Come! Victory awaits!", completion = "By blood and thunder, we will crush our foes." }
WordHunterWoW_QuestEN[60735] = { title = "Trouble in Paradise", description = "I have given your presence here some thought, {name}.\n\nIt is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented.\n\nYou must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence.\n\nSo... I ask you... why are you here, truly?", objectives = "Answer Kleia's question.", progress = "<Kalisthene peers down at you.>\n\nWhat is it, mortal?", completion = "<Kalisthene peers down at you.>\n\nWe have heard you, mortal." }
WordHunterWoW_QuestEN[60736] = { title = "Quest 02", description = "", objectives = "Open the door to the Seat of the Primus.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[60737] = { title = "The Door to the Unknown", description = "You empowered the final rune? Then we might yet turn the tide of battle!\n\nOpen the door, {name}! We'll hold the enemy back as long as we can!", objectives = "Open the door to the Seat of the Primus.", completion = "<The runeblade glows brighter as you approach an old stone altar.>" }
WordHunterWoW_QuestEN[60738] = { title = "The Way to Hibernal Hollow", description = "I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this.\n\nThen again, we've also never had a living mortal in our midst.\n\nWe need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs.\n\nI'll place it into the spirit cradle. Can you ask Niya if she would accompany you?\n\nThe poor sylvar has been directionless since the fall of her grove. This would be good for her.", objectives = "Recruit Niya to help you bring the wildseed to Hibernal Hollow.", completion = "I'm surprised that any wildseed could spawn such nightmares." }
WordHunterWoW_QuestEN[60739] = { title = "Tough Crowd", description = "", objectives = "" }
WordHunterWoW_QuestEN[60757] = { title = "Skeleton Key", description = "I see Thrall. But... the path to him is sealed.\n\nYou must find the key.\n\nThe task ahead is fraught with peril. You must journey to the Maw, and deliberately invoke the Eye of the Jailer to fall upon you. Tempt fate until his strongest assassins strike.\n\nOne of them will possess the key we need.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go to the Maw, and attract the Eye of the Jailer until you find an Upper Reaches Key on one of the Jailer's assassins." }
WordHunterWoW_QuestEN[60759] = { title = "Damned Intruders", description = "It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads.\n\nBefore you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.", objectives = "Kill 6 Cultists and 4 Bloodthirsty Ghouls at the Crossroads.", progress = "In troubled times, the Light guides our path.", completion = "You have my thanks, <class>. It will take all of our might to vanquish the Scourge." }
WordHunterWoW_QuestEN[60761] = { title = "Return of the Scourge", description = "Deliver these reports to Commander Throgg. He must be told of the full extent of the threat we face.\n\nIf we fail to hold the line against the Scourge... then Light help us all.", objectives = "Bring Lieutenant Althera's report to Commander Throgg in the Valley of Strength in Orgrimmar.\n\nProvided item:", completion = "I will pass this report onto the Regent Lord. I fear this is only the beginning. \n\nWord has come from Icecrown. The darkness stirs, and your strength is needed." }
WordHunterWoW_QuestEN[60762] = { title = "Death Motes", description = "I have a task for you, Maw Walker.\n\nSouls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will.\n\nIt is a tragic end.\n\nI wish to better understand this process--what is it about a soul that causes this transformation?\n\nFragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", objectives = "Collect 10 Death Motes from Ruin's Cradle in The Maw.", completion = "It is perhaps... ethically questionable to benefit from these motes, given their source. \n\nBut such knowledge may prove vital in defeating our enemies." }
WordHunterWoW_QuestEN[60763] = { title = "I Moustache You to Lend a Hand", description = "A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time.\n\nThis isn't a prank, is it? The Queen doesn't have time for pranks. But I do!\n\n<Moonberry leans in close and whispers to you.>\n\nAnd for this one, I think we need one more lily.\n\n<Moonberry winks.>\n\nLet me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.", objectives = "Assist Moonberry and Featherlight.", completion = "I hope that your arrival in Ardenweald is a sign that better times are on the horizon." }
WordHunterWoW_QuestEN[60764] = { title = "Soothing Song", description = "I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive.\n\nThis wildseed seems to take comfort in your presence, so you'll need to stick close to it.\n\nNiya will also need to sing to the wildseed to keep it calm... or else the nightmares may return.\n\nSpriggans love to interrupt our songs, so be on the lookout for them.\n\nLet me know when you're ready to head off.", objectives = "Travel with Niya to take the wildseed to Hibernal Hollow.", progress = "How strange that such a small wildseed could cause so much trouble...", completion = "It's good to see you again. The Wild Hunt could use your help." }
WordHunterWoW_QuestEN[60765] = { title = "Cure For All Ills", description = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness.\n\nMaw Walker, I'd do anything to help them. Even saving a few is better than saving none.\n\nPlease, help me cure them!", objectives = "Use Roseboil's Regenerative Molt to cure 15 Plague-ridden Survivors.", completion = "You and Roseboil have done well to help the survivors from the House of Plagues." }
WordHunterWoW_QuestEN[60766] = { title = "Damned Intruders", description = "Before you depart... we are in desperate need of reinforcements.\n\nThese reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.", objectives = "Kill 12 Scourge in the area.", progress = "In troubled times, the Light guides our path.", completion = "Thank you, <class>. We will need all the strength we can muster in the coming days." }
WordHunterWoW_QuestEN[60767] = { title = "Return of the Scourge", description = "Deliver my report to Commander Gregor. He must be informed of what we are up against. \n\nThe Scourge's numbers are on the rise, and if they do not abate... then the Light help us all.", objectives = "Bring Lieutenant Vernon's report to Commander Gregor in the Trade District of Stormwind City.\n\nProvided item:", completion = "I will see to it that King Greymane and the Lord Commander receive these reports, though I fear this is only the beginning.\n\nThis courier has just brought us dire news from Icecrown.\n\nIt appears we are not the only ones under assault." }
WordHunterWoW_QuestEN[60770] = { title = "Squish and Burn", description = "", objectives = "" }
WordHunterWoW_QuestEN[60775] = { title = "A Suitable Demise", description = "Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy.\n\nThe soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain.\n\nThis of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.", objectives = "Throw 5 Soulforged Cores into Soulforges in Zovaal's Cauldron in the Maw.", completion = "Next time, ask me how to run a stampede of mawrats off the edge of a cliff. That never fails to entertain." }
WordHunterWoW_QuestEN[60778] = { title = "Wildseed Rescue", description = "<Featherlight checks his notes.>\n\nLet's see... There was a request for help regarding an imperiled wildseed and... something about an egg? The original note wasn't entirely clear, but the fae who sent it was... Ah! It was Korenth. Again.\n\nWell, I suppose we'll find out what his trouble is soon enough!\n\nI'll fly ahead and look for him. Stick to the path.", objectives = "Help Korenth recover the wildseed.", progress = "You survived!", completion = "That was fun to watch! You had that bird ready to build a nest and raise hatchlings!\n\nOh, how I needed that laugh..." }
WordHunterWoW_QuestEN[60785] = { title = "Party Crashers!", description = "", objectives = "" }
WordHunterWoW_QuestEN[60786] = { title = "Swarm Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[60825] = { title = "Amateur Spies", description = "", objectives = "Your court is infested with spies, Maw Walker.\n\nNecromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down.\n\nI will dispatch any that I come across, but I would prefer to focus my attentions on the court.\n\nBring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.", progress = "Your court is infested with spies, Maw Walker.\n\nNecromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down.\n\nI will dispatch any that I come across, but I would prefer to focus my attentions on the court.\n\nBring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.", completion = "They thought to spy on the Matron of Spies herself?\n\nFools get what they deserve." }
WordHunterWoW_QuestEN[60827] = { title = "Advancing the Effort", description = "While the other crusaders regain control of the tournament grounds, you and I must press on.\n\nOur forces previously attempted to set up a forward camp farther into Icecrown, but they were overrun.\n\nWith you by our side, I am confident we can reclaim the area.", objectives = "Secure a foothold atop the Ironwall Rampart in Icecrown.", progress = "There is no stopping what has begun. We must continue our efforts.", completion = "Excellent work, <name>. \n\nPreparations are underway. Soon the foothold will be stocked and ready for use as a staging ground.\n\nFor the time being, there are other matters that require your attention." }
WordHunterWoW_QuestEN[60828] = { title = "A New Foothold", description = "Our preparations are complete. It is time we take the fight to the Scourge.\n\nJusticar Trueheart has tasked me with leading our efforts at the forward camp.\n\nMeet me there and we shall continue our work together.", objectives = "Meet Crusader Renn at the Argent Camp atop the Ironwall Rampart in Icecrown.", completion = "Our scouts report increased activity among the Cult of the Damned.\n\nI believe it is time we learn exactly what our fanatical friends are planning." }
WordHunterWoW_QuestEN[60831] = { title = "Fit For a Margrave", description = "We're finally ready, my apprentice. We shall craft our greatest potion!\n\nThough what the potion is meant for escapes me, I'm simply so proud of your progress. Margrave Stradama will be thrilled by your achievements!\n\nCome, now. Let's present what we've made to her!", objectives = "Present your potion to Margrave Stradama.", progress = "Go on, apprentice!", completion = "Ah... apprentice? Are you there? I feel... strange." }
WordHunterWoW_QuestEN[60837] = { title = "Wrath of Aliothe", description = "", objectives = "" }
WordHunterWoW_QuestEN[60839] = { title = "Remnants of the Wild Hunt", description = "The Wild Hunt is holding the line against these monsters, lest they overrun the road to Hibernal Hollow.\n\nToo many of my fellow hunters have been possessed by the dark magic of those twisted masks.\n\nBut with you here, we might be able to turn the tide. \n\nAid any hunters you can find before our foes turn them against us.\n\nI will meet you farther within the meadow. If we rally our numbers, we can bring an end to this battle.", objectives = "Rescue 5 Wounded Defenders from Soryn's Meadow.", completion = "Thank you for rescuing my fellow hunters. We'll have time to respect those who have returned to the cycle when this is all over." }
WordHunterWoW_QuestEN[60840] = { title = "Wild Hunt Offensive", description = "", objectives = "" }
WordHunterWoW_QuestEN[60841] = { title = "Evacuation Effort", description = "Our forces are in danger, and the fault is my own. Believing that the surrounding area was safe, I sent a small team to secure the abandoned camp in the valley to the southwest.\n\nBut our field reports were outdated or mistaken. The camp is a lost cause. We must now focus on rescuing those whom I assigned to it.\n\nHead for the camp. Do what you can to save our allies.", objectives = "Rescue 6 allies in the Valley of Lost Hope. Kill 6 Scourge in the area.", completion = "Thank you, <name>. Your efforts have saved many lives.\n\nFrom here on out, I will ensure that our scouting reports are accurate and up to date. It seems the threats we face escalate with each passing day." }
WordHunterWoW_QuestEN[60842] = { title = "To Serve Spriggan", description = "", objectives = "" }
WordHunterWoW_QuestEN[60843] = { title = "Cult Couture", description = "Though our scouts have been able to infiltrate the cultist forces at Aldur'thar, sneaking into Mord'rethar has proven all but impossible.\n\nPerhaps it is time to explore other methods of ingress.\n\nStart by investigating the cult's nearby ritual chambers. You may find something of use.", objectives = "Collect a Collaborator's Hood and a Collaborator's Robe from the cultists at Aldur'thar.", progress = "Find something?", completion = "These should suffice." }
WordHunterWoW_QuestEN[60844] = { title = "Flight School: Falling With Style", description = "", objectives = "" }
WordHunterWoW_QuestEN[60855] = { title = "Gormageddon", description = "", objectives = "" }
WordHunterWoW_QuestEN[60856] = { title = "Toppling the Brute", description = "A nearby monstrosity has been thwarting our efforts to clear the meadow.\n\nTogether, we can bring it down.\n\nYou and I will face off against the beast. When the time is right, I will call for the hunt to charge.\n\nThe Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!", objectives = "Defeat the Blighted Beast.", completion = "Fine work, <name>. This won't win our war... but it will at least help us in the fight for Soryn's Meadow." }
WordHunterWoW_QuestEN[60857] = { title = "We Can't Save Them All", description = "I am surprised--but pleased--that you weren't torn to pieces! Well done.\n\nBut now... I fear we have a far more serious task to complete.\n\nThe Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved.\n\nWe are to bring the final list to Droman Krelnor.", objectives = "Bring the list of saved wildseeds to Droman Krelnor at the Heartwood Grove.", progress = "Move along, stranger.", completion = "<Droman Krelnor sighs wearily as he reads the short list of wildseeds.>\n\nAt least a few will be relocated to Tirna Vaal." }
WordHunterWoW_QuestEN[60858] = { title = "Flight School: Up and Away!", description = "", objectives = "" }
WordHunterWoW_QuestEN[60859] = { title = "Souls of the Forest", description = "If you're standing in for Lady Moonberry, then maybe you can help!\n\nWagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey!\n\nCome on! They're just down the road!", objectives = "Rescue souls in peril.", progress = "Well, that was exciting.", completion = "It's been a while since a new soul arrived in Ardenweald, so each one already here is precious to us.\n\nI'll be sure to let Lady Moonberry know of your heroic rescue efforts on her behalf. She might even decide she owes you a favor!" }
WordHunterWoW_QuestEN[60861] = { title = "Secrets in Shadows", description = "Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers.\n\nTake these robes. Make your way into the inner sanctum and see what you can discover.\n\nThis may be our only chance to learn their intentions, {name}.", objectives = "Use the Collaborator's Robes in Mord'rethar to discover what secrets lie within.", progress = "Find something?", completion = "<This news is rather unsettling.>" }
WordHunterWoW_QuestEN[60867] = { title = "A Message from Above", description = "This is troubling news, {name}. Whoever this \"Banished One\" may be, it is clear he is behind the Scourge's return.\n\nThat the undead are amassing in great numbers outside Icecrown Citadel cannot be a coincidence. Lead our hippogryph riders in surveying the area from above.\n\nDetermine if the dark herald you saw is among them, and then clear a path for reinforcements.\n\nLet us hope she possesses the answers we seek.", objectives = "Discover the location of Herald Dalora. Destroy the Scourge forces surrounding Icecrown Citadel.", progress = "The skies over the citadel may be dangerous, but we need to know what we're up against.", completion = "With their numbers momentarily reduced, now is our chance to strike." }
WordHunterWoW_QuestEN[60869] = { title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", objectives = "Establish a portal to Orgrimmar at the Argent Tournament Grounds. Deliver the news to Lor'themar Theron atop Grommash Hold in Orgrimmar.", completion = "This is troubling news, <name>. To think that Sylvanas would willingly ally with such a dark power..." }
WordHunterWoW_QuestEN[60871] = { title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", objectives = "Establish a portal to Stormwind at the Argent Tournament Grounds. Deliver the news to Genn Greymane at Lion's Rest in Stormwind City.", completion = "These are grim tidings, <name>. It seems the Banshee has aligned herself with a darker power than we know." }
WordHunterWoW_QuestEN[60872] = { title = "A Dangerous Harvest", description = "", objectives = "" }
WordHunterWoW_QuestEN[60881] = { title = "Ride of the Wild Hunt", description = "Thanks to your efforts, we have turned the tide of battle. We won't soon forget your aid. \n\nWe should be able to hold Soryn's Meadow, now that this brute is dead. \n\nRide with us, {name}. Let us return to the road and your wildseed.", objectives = "Ride with the Wild Hunt to Niya and the wildseed.", completion = "It is good to see part of the Wild Hunt's strength restored... and also that you found the spirit cradle of use.\n\nNow let us bring the wildseed within it to Hibernal Hollow." }
WordHunterWoW_QuestEN[60886] = { title = "The Seat of the Primus", description = "This cannot be a coincidence. It is clear that your runeblade is somehow connected to the Seat of the Primus.\n\nI will not pretend to know the Primus's agenda. But I would not be surprised if he left behind a way for the worthy to open the door to his sanctum.\n\nDraka will bring you to the Seat of the Primus. If you hold the key, mortal, then our victory is all but assured.", objectives = "Go with Draka to the Seat of the Primus.", progress = "What is it?", completion = "We cannot lose sight of the battles ahead of us. The door will have to wait." }
WordHunterWoW_QuestEN[60887] = { title = "Cataclysm: Onward to Adventure in Kalimdor", description = "There are people across Azeroth that could use your help, <name>. They come from different walks of life, but are all working towards finding their place on this beautiful world.\n\nExamine the Warchief's Command Board and see where your adventure awaits!", objectives = "Find the Warchief's Command Board in Orgrimmar.", progress = "I cannot wait to hear your stories someday.", completion = "So many choices, so little time!\n\nGood luck out there, <name>... but I don't think you'll need it." }
WordHunterWoW_QuestEN[60889] = { title = "Favor: She Had a Stone Heart", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the She Had a Stone Hearth poem to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "Is that a piece of paper?\n\n<You present Ta'xera with the poem.>\n\nA Stoneborn poem! Very few stoneborn express feelings or desires beyond that of the service and loyalty chiseled into them. \n\nI shall enjoy, I mean, this will make excellent documentation of potential depth to the Stoneborn, you must let me buy it!" }
WordHunterWoW_QuestEN[60891] = { title = "Cataclysm: Onward to Adventure in the Eastern Kingdoms", description = "There are people across Azeroth that could use your help, <name>. They come from different walks of life, but are all working towards finding their place on this beautiful world.\n\nExamine the Hero's Call Board and see where your adventure awaits!", objectives = "Find the Hero's Call Board in Stormwind.", progress = "I cannot wait to hear your stories someday.", completion = "So many choices, so little time!\n\nGood luck out there, <name>... but I don't think you'll need it." }
WordHunterWoW_QuestEN[60898] = { title = "The Fate of Ara'lon", description = "{name}, I have an urgent request to make of you.\n\nRecently, the Wild Hunt has been encountering the masked fae in greater numbers... particularly in the area surrounding Blackthorn Grove. I sent a hunting party to investigate, but they have yet to return.\n\nAra'lon was leading the hunt. You have offered him aid before, yes? I ask that you do so again.\n\nSearch the area for signs of the missing hunters and report back to me.", objectives = "Search near Blackthorn Grove for Ara'lon and the lost hunting party.", completion = "Keep your voice down. There are masked fae are nearby..." }
WordHunterWoW_QuestEN[60899] = { title = "A Night in the Woods", description = "", objectives = "" }
WordHunterWoW_QuestEN[60900] = { title = "Archival Protection", description = "The rarest volumes are kept at the top of this tower, protected by an entity called the Archivist.\n\nThis stoic guardian is incorruptible. Intractable. Completely uninterested in striking a fair bargain!\n\nIts utter lack of business acumen is really quite upsetting.\n\nAh, well. I fear we have no choice but to dispatch this impediment. Shall we?", objectives = "Defeat the Archivist.", completion = "The volumes are not here!\n\nThe Archivist's final words must have meant something. A clue, perhaps?" }
WordHunterWoW_QuestEN[60901] = { title = "Passage to Hibernal Hollow", description = "You have done the Wild Hunt a great service. I must repay you in some way.\n\nThe battle for Soryn's Meadow has turned. With the brute defeated, the Blighted forces lose their strength.\n\nAllow us to escort you to Hibernal Hollow.\n\nSpeak to me whenever you wish to depart.", objectives = "Speak with Ara'lon to receive an escort to Hibernal Hollow.", completion = "Dreamweaver has told me much about your strange wildseed. \n\nI will do what I can to help." }
WordHunterWoW_QuestEN[60903] = { title = "Krala", description = "", objectives = "" }
WordHunterWoW_QuestEN[60904] = { title = "Medallion of Desire", description = "The Medallion of Desire rests upon the neck of the Countess. \n\nIt is a source of power for her, but not her only source of power. Claiming it by force would merit us only a short victory. For this we must be much more subtle.\n\nLucky for us, Theotar has come to me with a plan but he will need your help. Speak with him and see what the two of you can do. \n\nHe was closer to the Countess than any of us for a long time and I would consider him our resident expert on her.", objectives = "Speak with Theotar.", completion = "Down for a little espionage and intrigue?" }
WordHunterWoW_QuestEN[60905] = { title = "Infusing the Wildseed", description = "Dreamweaver tells me of a ritual to quell the wildseed's nightmares... but it will require anima.\n\nA soul named Proglo lives beneath this tree, gathering anima for the grove's caretakers to use.\n\nHis mortal life came to a violent end, and his soul has been skittish ever since. He will not respond well to your current form.\n\nI will grant you the ability to assume the soulshape of a fox. Approach Proglo in your new form to gain his trust and ask for his anima.", objectives = "Use Soulshape to collect anima from Proglo, then infuse the wildseed with the collected anima.", progress = "I hope we can aid this wildseed.", completion = "It's going to be difficult, but I know of a place where there may be enough anima to help this wildseed." }
WordHunterWoW_QuestEN[60906] = { title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Hero's Rest where you can do the honors.", objectives = "Enshrine the Spear of Kalliope in its rightful place at Hero's Rest.", progress = "<The resting place of the spear lies before you.>", completion = "<Place the Spear of Kalliope in its rightful place knowing that only a true hero can do so.>" }
WordHunterWoW_QuestEN[60907] = { title = "Ascension Calling: Kleia", description = "<This scroll details an invitation for Kleia to join you and Pelagos on the Path of Ascension.\n\nIt would be wise to deliver this to her at once.>", objectives = "Inform Kleia she is now able to participate in the Path of Ascension.", completion = "Time to stretch my wings!" }
WordHunterWoW_QuestEN[60910] = { title = "Masks of Deception", description = "My hunting party was ambushed not far from here. I narrowly escaped capture, but the others were taken deeper into Blackthorn Grove.\n\nWe must find and rescue them, but we are vastly outnumbered. We'll need to disguise ourselves while we search the grove.\n\nSee if you can find something we can use to do so. I need just a little longer to recover from my wounds.", objectives = "Find two Masks of Possession.", progress = "What have you found?", completion = "Yes! We can use these masks to disguise ourselves." }
WordHunterWoW_QuestEN[60911] = { title = "Flight School: Flapping Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[60916] = { title = "RSVP: Stonehead", description = "Hi, best bud!\n\nMe no go party. \n\n<Stonehead shakes his head vigorously.>\n\nGot to stay for job!", objectives = "Forge a document to give Stonehead permission to leave his post for the Ember Court.", progress = "Hi, best bud!", completion = "<Stonehead scratches his head and peers at the document.>\n\nMe see lots of wax blobs.\n\n<Stonehead thinks very hard, moving his lips as he tries to sound out words.>\n\nUmm... maybe... it... say... Me go party with best bud?\n\nYay! Me go party with best bud!" }
WordHunterWoW_QuestEN[60920] = { title = "Akros", description = "", objectives = "" }
WordHunterWoW_QuestEN[60928] = { title = "Blackthorn Captives", description = "These disguises will allow us to explore the grove undetected, but beware of the overseers. Their Drust magic will more than likely be able to pierce through our deception.\n\nWe need to save the rest of my hunting party while we still can.", objectives = "Locate the missing hunters in Blackthorn Grove.", progress = "The Drust have taken so much from us...", completion = "Gweyir is the only survivor... but she's already been afflicted by the Drust's cursed magic. \n\nWe can't just leave her here. Not like this!" }
WordHunterWoW_QuestEN[60929] = { title = "Air Supremacy", description = "", objectives = "" }
WordHunterWoW_QuestEN[60930] = { title = "Lower Your Standards", description = "", objectives = "<Picky Stefan leans in close and whispers.>\n\nMaw Walker, we are running low on refreshments!\n\nThankfully, you chose to serve such a humble... \"delicacy\"  that we can find more just about anywhere.\n\nAs you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.", progress = "<Picky Stefan leans in close and whispers.>\n\nMaw Walker, we are running low on refreshments!\n\nThankfully, you chose to serve such a humble... \"delicacy\"  that we can find more just about anywhere.\n\nAs you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.", completion = "Normally, I would be far more discerning in what we serve our guests, but this crowd seems to lack my sophisticated palette." }
WordHunterWoW_QuestEN[60932] = { title = "Only Shadows Remain", description = "We may not know who this dark herald serves, but it is clear that the message she brings has emboldened the Scourge and the Cult of the Damned alike.\n\nThis cannot be allowed to continue. We must vanquish her and strike a definitive blow against her master's new minions.\n\nLead the charge, {name}. The Argent Crusade stands with you.\n\nLight willing, we will put an end to this madness here and now.", objectives = "Defeat Herald Dalora in the Cathedral of Darkness.", progress = "May we continue our fight together.", completion = "It seems that eliminating the herald has slowed the Scourge's advance.\n\nWe will have to remain vigilant. Thank you for all you have done, <name>." }
WordHunterWoW_QuestEN[60934] = { title = "Report to Lord Herne", description = "I will do whatever it takes to save Gweyir from the Drust's curse.\n\nLord Herne must be informed of what befell my hunting party. Deliver my report to him while I escort Gweyir back to the Heart of the Forest.\n\nGweyir was under my leadership during the ambush... she is my responsibility. I will make sure she gets home safely.", objectives = "Deliver Ara'lon's report to Lord Herne.", progress = "Did you find the lost hunting party?", completion = "So Gweyir and Ara'lon are the only survivors... this is grave news." }
WordHunterWoW_QuestEN[60935] = { title = "Medallion of Avarice", description = "The Medallion of Avarice was the tool of the Curator.\n\nWith its power it granted her authority over the Catacombs Ward. Combined with her knowledge of the vast library of sinstones Revendreth has accumulated over the ages, the Curator was a master of her craft.\n\nWhen Denathrius defeated my first rebellion, he tossed both myself and the Curator into the Maw. \n\nThe Curator was clever, though, and she hid the medallion before Denathrius could act. Come, let us speak of plans.", objectives = "Speak with Prince Renathal.", completion = "The Curator is one of the few remaining true venthyr forged during the founding of Revendreth.\n\nHer memory is vast, but her time in the Maw has fragmented the order of those memories.\n\nShe will need your help." }
WordHunterWoW_QuestEN[60937] = { title = "[DNT] Blueprint: Herald's Footpads", description = "PH - Take this to Dactylis.", objectives = "" }
WordHunterWoW_QuestEN[60945] = { title = "Deep Echo Trident", description = "<The trident glistens in the sunlight.\n\nThis should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>", objectives = "Bring the Deep Echo Trident to Paolone.", completion = "Trident? Very very nice! I hold on for safe keeping." }
WordHunterWoW_QuestEN[60946] = { title = "Blueprint: Deep Echo Trident", description = "<You have discovered plans for a trident that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "Bring the Blueprint: Deep Echo Trident to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[60947] = { title = "Blueprint: Charm of Fortitude", description = "<You have discovered plans for a charm that seems to fortify your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "Bring the Blueprint: Charm of Fortitude to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[60948] = { title = "RSVP: The Countess", description = "The Prince wishes to host court? Well, that should be interesting...\n\nI am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. \n\nSo you shall do something for me.\n\nHouse Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses.\n\nSteal it for me, but incriminate one of the other houses in the act.", objectives = "Disguise yourself as a member of House Iremoore and steal the House Briarbane mascot.", progress = "It would be a shame to waste such a fine mascot on such an unworthy house.", completion = "Lovely. That should keep the houses distracted while I attend the Prince's soiree." }
WordHunterWoW_QuestEN[60950] = { title = "A Matter of Stealth", description = "", objectives = "" }
WordHunterWoW_QuestEN[60955] = { title = "Noko's Flute", description = "", objectives = "<Noko breathes in slowly.>\n\nThe stage manager says he cannot find my flute anywhere.\n\nThe last time this happened, one of the rowdy roadies had run off with it.\n\nYou can find those troublesome dredgers causing trouble around the party.\n\nRetrieve my flute from them and I will play for your guests.", progress = "<Noko breathes in slowly.>\n\nThe stage manager says he cannot find my flute anywhere.\n\nThe last time this happened, one of the rowdy roadies had run off with it.\n\nYou can find those troublesome dredgers causing trouble around the party.\n\nRetrieve my flute from them and I will play for your guests.", completion = "<Noko holds his flute tenderly.>\n\nI only truly feel like myself while holding the flute of my caravan.\n\nThank you for providing the opportunity to play." }
WordHunterWoW_QuestEN[60957] = { title = "Ansel's Lucky Violin", description = "", objectives = "<Lucky Ansel reluctantly breaks gaze with his sinstone.>\n\nMy burdens are still far too heavy.\n\nI will never be free of the Maw's dangers while even a single sin remains on this stone.\n\nLuckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor.\n\nRetrieve my violin from the band supplies over near the dancers and I will begin my public penance.", progress = "<Lucky Ansel reluctantly breaks gaze with his sinstone.>\n\nMy burdens are still far too heavy.\n\nI will never be free of the Maw's dangers while even a single sin remains on this stone.\n\nLuckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor.\n\nRetrieve my violin from the band supplies over near the dancers and I will begin my public penance.", completion = "<Ansel turns his violin as it sparkles in the light.>\n\nLet the show begin." }
WordHunterWoW_QuestEN[60958] = { title = "We Send Only You", description = "", objectives = "" }
WordHunterWoW_QuestEN[60959] = { title = "Burning Crusade: Onward to Adventure in Outland", description = "The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the shattered world of Outland." }
WordHunterWoW_QuestEN[60960] = { title = "Chiu's Lute", description = "", objectives = "I am nervous, <name>. Music lays bare my soul for all to see.\n\nAnd while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within.\n\nLord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived.\n\nI must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.", progress = "I am nervous, <name>. Music lays bare my soul for all to see.\n\nAnd while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within.\n\nLord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived.\n\nI must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.", completion = "<Chiu speaks to the lute while she quickly tunes its strings.>\n\nWhat did those dredgers do to you, old friend?" }
WordHunterWoW_QuestEN[60961] = { title = "Burning Crusade: Onward to Adventure in Outland", description = "The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the shattered world of Outland." }
WordHunterWoW_QuestEN[60962] = { title = "Wrath of the Lich King: Onward to Adventure in Northrend", description = "The Lich King will stop at nothing to subjugate every living being on Azeroth.\n\nFind your way back to Northrend and continue your adventure!", objectives = "Travel to the icy continent of Northrend." }
WordHunterWoW_QuestEN[60963] = { title = "Wrath of the Lich King: Onward to Adventure in Northrend", description = "The Lich King will stop at nothing to subjugate every living being on Azeroth.\n\nFind your way back to Northrend and continue your adventure!", objectives = "Travel to the icy continent of Northrend." }
WordHunterWoW_QuestEN[60964] = { title = "Mists of Pandaria: Onward to Adventure in Pandaria", description = "There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, <name>.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the mysterious land of Pandaria." }
WordHunterWoW_QuestEN[60965] = { title = "Mists of Pandaria: Onward to Adventure in Pandaria", description = "There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, <name>.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the mysterious land of Pandaria." }
WordHunterWoW_QuestEN[60968] = { title = "Warlords of Draenor: Onward to Adventure in Draenor", description = "You mustn't delay, <name>. The people of Draenor still need your help!\n\nFind your way back there and continue your adventure!", objectives = "Travel to the orcish homeworld of Draenor." }
WordHunterWoW_QuestEN[60969] = { title = "Warlords of Draenor: Onward to Adventure in Draenor", description = "You mustn't delay, <name>. The people of Draenor still need your help!\n\nFind your way back there and continue your adventure!", objectives = "Travel to the orcish homeworld of Draenor." }
WordHunterWoW_QuestEN[60970] = { title = "Legion: Onward to Adventure in the Broken Isles", description = "The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it!\n\nFind your way back to the Broken Isles and continue your adventure!", objectives = "Travel to the Broken Isles." }
WordHunterWoW_QuestEN[60971] = { title = "Legion: Onward to Adventure in the Broken Isles", description = "The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it!\n\nFind your way back to the Broken Isles and continue your adventure!", objectives = "Travel to the Broken Isles." }
WordHunterWoW_QuestEN[60972] = { title = "The Hunt for the Baron", description = "<The amulet Bolvar gave you flickers with a faint red light, then grows dim.\n\nTo be useful in finding Darion Mograine, you must find a way to restore its potency.\n\nYou recall an area called Zovaal's Cauldron that was teeming with dark magic.\n\nPerhaps the amulet's power could be restored there.>", objectives = "Charge the Amulet of the Horsemen." }
WordHunterWoW_QuestEN[60973] = { title = "Blueprint: Phial of Serenity", description = "<You have discovered plans for a phial that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "Bring the Blueprint: Phial of Serenity to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[60974] = { title = "Phial of Serenity", description = "<Your steward friend gave you an extra bottle to store this potion in.\n\nThis should keep your soulbinds fighting in the Path of Ascension, as your phial does.>", objectives = "Bring the Phial of Serenity to Paolone.", completion = "Phial? Very nice! Just like friend! I hold on for safe keeping." }
WordHunterWoW_QuestEN[60975] = { title = "Blueprint: Spiritforged Aegis", description = "<You have discovered plans for a shield that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "Bring the Blueprint: Spiritforged Aegis to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[60990] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[60991] = { title = "Orrholyn, Lord of Bloodletting", description = "", objectives = "" }
WordHunterWoW_QuestEN[60992] = { title = "Razkazzar, Lord of Axes", description = "", objectives = "" }
WordHunterWoW_QuestEN[60993] = { title = "Citadel of Loyalty", description = "The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. \n\nForge cannot solve this. Citadel of Loyalty can.\n\nTaken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.", objectives = "Meet Mikanikos at the Citadel of Loyalty.", completion = "Here we are. I'm glad we have your friends here too.\n\nWe are going to need it if we hope to reach the temple." }
WordHunterWoW_QuestEN[60994] = { title = "Lowering Their Defenses", description = "We can alter the crown to expunge Denathrius's corruption in the medallions.\n\nProblem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken.\n\nDrain the anima from the barrier's sources that power it. Barrier will disappear.", objectives = "Drain the anima from the Forsworn Barrier Sources.", completion = "Excellent work. \n\nBarrier around the temple is gone. To fix the crown, we must go there." }
WordHunterWoW_QuestEN[60995] = { title = "Disloyalty", description = "There are many enemies of Bastion here. \n\nIf we thin their numbers, it will further mend the tension between our realms. \n\nShow no remorse. \n\nI will take to the skies to support from above. I will be able to provide ground support when needed.", objectives = "Kill 15 Forsworn in the Citadel of Loyalty.", completion = "Forsworn defeated? Good. The fewer of them there are, the happier I am." }
WordHunterWoW_QuestEN[60996] = { title = "Face Your Fears", description = "The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown.\n\nPrepare yourself. Denathrius's magic has always been potent and destructive. \n\nThis won't be easy.", objectives = "Speak to General Draven to go to the Temple of Loyalty. Then, aid Mikanikos in purifying the Crown of the Harvesters.", completion = "With the echo of Denathrius defeated, Mikanikos assures me the crown is pure.\n\nThis is a key victory for Revendreth and all the Shadowlands." }
WordHunterWoW_QuestEN[61050] = { title = "How to Wear Seven Medallions", description = "One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them.\n\nWhat I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder.\n\nUnfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius.\n\nNo, for this, we must employ the aid of a realm that specializes in service.\n\nDraven has the details.", objectives = "Speak with General Draven.", completion = "After much strategizing, the Prince and I have developed a plan that requires the aid and resources of someone I once led actions against on behalf of the Master.\n\nPrepare to shield your eyes. We need to go to Bastion." }
WordHunterWoW_QuestEN[61051] = { title = "The Absent-Minded Artisan", description = "Of all the foolhardy, misguided, exasperating...\n\n<Guardian Kota snorts and stomps a hoof.>\n\nBut standing here does Sha'lor no good. We must find him and bring him back safely.\n\nCome, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.", objectives = "Search for Master Sha'lor on the Autumnal Rise.", completion = "No!\n\nWhatever that beast was, it's taken Sha'lor!" }
WordHunterWoW_QuestEN[61056] = { title = "Niya of Ardenweald", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "" }
WordHunterWoW_QuestEN[61057] = { title = "By Trials Forged", description = "You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. \n\nIt has been a privilege to fight by your side, {name}. It would be my honor to continue, as your Soulbind.", objectives = "Complete the soulbinding ritual with Korayn.", progress = "Together we are stronger!", completion = "Together, we will guard Ardenweald." }
WordHunterWoW_QuestEN[61058] = { title = "Bound in Dreams", description = "I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well!\n\nSince then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger.\n\nI would be honored to help you continue the good work you have been doing, and to become your soulbind.", objectives = "Complete the soulbinding ritual with Dreamweaver.", progress = "I am humbled by the care you have shown for others.", completion = "I just know that together we can save Ardenweald and all the spirits who slumber here." }
WordHunterWoW_QuestEN[61059] = { title = "RSVP: Rendle and Cudgelface", description = "I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e  haven't got proper ah-tire.\n\nSays 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths.\n\nHe says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.", objectives = "\"Sootible\" hats may be crafted by players who have the recipe and appropriate tradeskill.", completion = "Wot a hat! Rendle will be the talk of the court, 'e will." }
WordHunterWoW_QuestEN[61060] = { title = "Spore Losers", description = "", objectives = "" }
WordHunterWoW_QuestEN[61061] = { title = "Ulfar's Guidance", description = "There is one who may know how to dispel the curse from Gweyir.\n\nIn the mountains of Drustvar lives Ulfar, an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust.\n\nJourney to his den and ask for his wisdom. He may hold the answers you seek.\n\nLord Herne and I will tend to Gweyir once she arrives with Ara'lon.", objectives = "Speak with Ulfar at Ulfar's Den in Drustvar.", completion = "You have come from beyond the veil to seek my wisdom? A long journey indeed..." }
WordHunterWoW_QuestEN[61062] = { title = "Adjutant Dekaris", description = "", objectives = "" }
WordHunterWoW_QuestEN[61075] = { title = "A Spark of Light", description = "Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned.\n\nThe Jailer's unblinking eyes patrol the river and watch for souls who attempt escape.\n\nBlind the eyes that find them. Close them for good. \n\nTake this and do what must be done.", objectives = "Defeat 4 Eyes of Damnation.", progress = "Have you closed the Jailer's eyes?", completion = "Well done, Maw Walker. The Jailer's eyes are dangerous, indeed." }
WordHunterWoW_QuestEN[61076] = { title = "Into the Flame", description = "I know the curse of which you speak. Dark magic that possesses the mind of the afflicted.\n\nLong ago, the Drust were ruled by a sorcerer king named Gorak Tul. It was he who twisted our rituals and set us on the path of death and domination.\n\nYou will need to claim a portion of his power to break the curse. \n\nTake this fetish to Gol Inath and temper it in the Flame of Oblivion. But beware... it is a vile place, and danger lurks among its shadows.", objectives = "Imbue the Drust Fetish with the power of Gorak Tul.", progress = "Gorak Tul's magic empowers the curse, and only his magic can break it.", completion = "I can sense Gorak Tul's dark power seething within this fetish. Handle it with caution, <class>." }
WordHunterWoW_QuestEN[61077] = { title = "Confronting Sin", description = "Thanks to the raid launched against Castle Nathria, we have obtained an opportunity.\n\nA soul, powerful and fused with dark purpose at the hands of the Master's experiments. \n\nGiven this soul is from Azeroth, the Accuser has asked for your assistance in untwining the corruption done to his sinstone.\n\nThe Accuser awaits you in the lower levels of Sinfall.", objectives = "Speak with the Accuser in Sinfall.", completion = "I make no presumption that all mortals from Azeroth know each other. \n\nWhen confronting a challenging soul like this, however, it helps to offer even the faintest of familiarity." }
WordHunterWoW_QuestEN[61079] = { title = "The Jailer's Share", description = "The Mawsworn's torturers have a talent for misery.\n\nThe suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss.\n\nI have fashioned a conduit specifically for capturing the leftover stygia. You can borrow it if you wish.\n\nThere are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.", objectives = "Place 4 Stygia Conduits at marked locations within Calcis in The Maw.", progress = "Were the conduits effective? How much stygia did they collect?", completion = "It is satisfying to know that the Jailer's share now belongs to us. Well done, Maw Walker." }
WordHunterWoW_QuestEN[61087] = { title = "Delayed Delivery: Old Gate Parcel", description = "", objectives = "" }
WordHunterWoW_QuestEN[61088] = { title = "Dust to Dust", description = "The Mawsworn never cease to invent new forms of suffering.\n\nEven the ground on which we tread is formed from souls pounded into dust. With the flood of souls passing through Gorgoa, the Mawsworn are keen to expand their domain.\n\nAt present, the Mawsworn are burying souls and crafting new terrain from their torment. It is not too late for some of them.\n\nFree the buried souls and stop the endless expansion of suffering.", objectives = "Rescue 8 Half-Buried Souls in Calcis in The Maw.", progress = "They are safe?", completion = "The curious forms of torment the Mawsworn invent will never cease to amaze me." }
WordHunterWoW_QuestEN[61092] = { title = "RSVP: Grandmaster Vole", description = "I'm busy, so I'll get right to the point. \n\nThe only way I'm going is if you pay me enough coin to make it worth my while or you amuse me. \n\nAs interesting and enjoyable as the Ember Court may be, I lose money every time I am away from here. That said, I do love a good slaughter.\n\nSo, coin or deaths. Take your pick.", objectives = "Convince Grandmaster Vole by bribing him or slaying players of the opposite faction.", progress = "You need to cough up the coin or get killing.", completion = "That works. I'll be there. It will be a nice vacation." }
WordHunterWoW_QuestEN[61095] = { title = "Supplies from The Undying Army", description = "Your efforts meet with the approval of The Undying Army.\n\nThese rewards are in recognition of those efforts. May they help you in the battles to come.", objectives = "Speak with Nalcorn Talsen at the Theater of Pain.", completion = "The Undying Army would like to thank you for your efforts in aiding Maldraxxus.\n\nPlease accept a gift in recognition of your service to our cause and our forces." }
WordHunterWoW_QuestEN[61096] = { title = "The Arbiter's Will", description = "We will all suffer if Bastion and Maldraxxus fall into war.\n\nFor some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion.\n\nThough our anima reserves remain low, they will be enough to open the way for you.", objectives = "Meet Kah-Sher in the Ring of Transference in Oribos.", completion = "This slot shall suffice." }
WordHunterWoW_QuestEN[61097] = { title = "Supplies from The Ascended", description = "The Ascended would like to thank you for your efforts in aiding Bastion.\n\nPlease accept a gift in recognition of your service to our cause and our people.", objectives = "Speak with Adjutant Nikos in Hero's Rest in Bastion.", completion = "The Ascended would like to thank you for your efforts in aiding Bastion.\n\nPlease accept a gift in recognition of your service to our cause and our people." }
WordHunterWoW_QuestEN[61098] = { title = "Supplies from The Wild Hunt", description = "The Wild Hunt thanks you for your efforts in aiding Ardenweald.\n\nTake these gifts as recognition for your aid. May they help you in whatever trials may come.", objectives = "Speak with Aithlyn at the Heart of the Forest in Ardenweald.", completion = "The Wild Hunt thanks you for your efforts in aiding Ardenweald.\n\nTake these gifts as recognition for your aid. May they help you in whatever trials may come." }
WordHunterWoW_QuestEN[61099] = { title = "The Search for Baine", description = "I dare not step inside that accursed tower myself, of course.\n\nWhile I cannot tell you exactly where your comrade is being held, I offer a gift to assist you.\n\nUse it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes?\n\nEither that, or you'll end up trapped within the tower's ever-shifting halls for all eternity.\n\nBut those are the risks one must take, I suppose. Best of luck!", objectives = "Enter Torghast and search for Baine.", progress = "You've found him!", completion = "Finding Baine was no easy feat. But you braved the horrors of that tower and succeeded.\n\nWell done.\n\nBut I fear your work is only just beginning." }
WordHunterWoW_QuestEN[61100] = { title = "Supplies from the Court of Harvesters", description = "Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. \n\nAs a result, we have collection of resources you may find useful, plundered from Sire Denathrius' most devoted followers. They are waiting for you with me in Darkhaven.", objectives = "Speak with Mistress Mihaela for your reward.", completion = "Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. \n\nPlease accept these token of gratitude." }
WordHunterWoW_QuestEN[61102] = { title = "Kivarr the Thornspeaker", description = "In my youth, I was mentored by a wise and powerful Thornspeaker named Kivarr. She passed from this world long ago, but her soul may yet rest within the Shadowlands.\n\nKivarr's knowledge is ancient and vast, far eclipsing my own. She may be able to offer you the guidance that I cannot.\n\nSeek her out. Deliver the fetish to her. She will know what to do.\n\nMay the wind be your guide.", objectives = "Speak with Lord Herne at Heart of the Forest in Ardenweald.", completion = "Kivarr... yes, I have heard of someone by that name. Ara'lon may know where to find her." }
WordHunterWoW_QuestEN[61103] = { title = "Disrupting the Cycle", description = "The shacklers in the Tremaculum are an awful sort.\n\nSouls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. \n\nIf you wish to slow the rate at which the Jailer raises his armies, start at the source. \n\nDisrupt the cycle at the Tremaculum.", objectives = "Defeat 4 Mawsworn Shacklers and 6 Deadeyes at the Tremaculum in The Maw.", completion = "Well done, Maw Walker. The Jailer's forces are vast, but they are not infinite." }
WordHunterWoW_QuestEN[61104] = { title = "Grathalax, the Extractor", description = "There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer.\n\nFar beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax. Power is fed to him via conduits throughout the area.\n\nHis role is to make the process of anima extraction more efficient. His methods are... unkind.\n\nI believe we would both benefit from the end of his existence.", objectives = "Defeat Grathalax underneath the Tremaculum in The Maw.", completion = "The end of Grathalax will deal a great blow to the Jailer's infrastructure. Well done." }
WordHunterWoW_QuestEN[61105] = { title = "RSVP: Plague Deviser Marileth", description = "Oh! This sounds like a wonderful opportunity to do field research in Revendreth, apprentice.\n\nI look forward to collaborating with new colleagues. We must bring a gift to thank them for their invitation. What could be more appropriate than some lovely slimes?\n\nPlease pick some of the best slimes for me to present to our host. Just bring them to Kevin so they can make friends and travel together.", objectives = "Herd Bubbling Oozes to Kevin so Plague Deviser Marileth has a present to bring to the Ember Court.", progress = "Have you finished choosing our gift slimes yet, apprentice?", completion = "You've done very well apprentice!" }
WordHunterWoW_QuestEN[61107] = { title = "A Land of Strife", description = "It is imperative that you identify the cause of the attack on Bastion.\n\nWe will require your aid to open the gateway. Once the focus is sufficiently powered, we will call upon the gate to Maldraxxus and direct it into position.\n\nFrom there, the fate of this war must rest upon your shoulders.", objectives = "Activate the gateway to Maldraxxus.", progress = "Time is precious, now more than ever.", completion = "The way is open. The eternal battlefields of Maldraxxus await you." }
WordHunterWoW_QuestEN[61109] = { title = "RSVP: Hunt-Captain Korayn", description = "I am a Captain of the Wild Hunt, a defender of the sacred groves. As much as I would enjoy the diversion, my place is here fighting back the forces of the enemy, not venturing outside of Ardenweald.\n\nEggs are hatching again at Gormhive and we shall soon be overrun by gormling larva. Until that threat is neutralized I cannot leave my post.", objectives = "Remove the threat of Gormhive by smashing eggs, eliminating egg tenders, and slaying gorm so Hunt-Captain Korayn can attend the Ember Court.", completion = "Well done. Thank you for the help." }
WordHunterWoW_QuestEN[61112] = { title = "A Hunger for Flesh", description = "<The bile-soaked cloth bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Gregor will want to know of this at once.>", objectives = "Bring the Partially Digested Cloth to Commander Gregor in the Trade District of Stormwind City.\n\nProvided item:", completion = "This... This is from one of our own... from within the city walls.\n\nI will send word to our patrols. Remain alert, <name>.\n\nShould the Scourge rise up from within our own ranks, find me at once!" }
WordHunterWoW_QuestEN[61113] = { title = "Kivarr's Den", description = "Kivarr... I have not heard that name in many an age.\n\nShe used to make her home near Eventide Grove to the south. Ara'lon knows the area well. I suggest you take him with you.\n\nI fear that the situation with Gweyir weighs heavily upon him. Perhaps joining you on the hunt will do him some good.", objectives = "Travel to Kivarr's Den at Eventide Grove in Ardenweald.", progress = "Kivarr has made her home in Ardenweald for many an age, but she has always kept to herself.", completion = "This is the place, but Kivarr is nowhere to be found..." }
WordHunterWoW_QuestEN[61114] = { title = "A Hunger for Flesh", description = "<The bile-soaked leather bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Throgg will want to know of this at once.>", objectives = "Bring the Partially Digested Leather to Commander Throgg in the Valley of Strength in Orgrimmar.\n\nProvided item:", completion = "This... This is from one of our own... from within the city walls.\n\nI will send word to our patrols. Remain alert, <name>.\n\nShould the Scourge rise from within our own ranks, find me at once!" }
WordHunterWoW_QuestEN[61123] = { title = "RSVP: Polemarch Adrestes", description = "I must politely decline your Prince's offer.\n\nMy skills are needed here, and I am not particularly well-suited to the social demands of attending court.\n\nPerhaps the Paragon of Humility would be a better representative for Bastion.\n\nYou may find him at the Temple of Humility, east of here.\n\nPlease express my sincere regrets that I am unable to attend.", objectives = "Seek the assistance of the Paragon of Humility.", progress = "My answer has not changed.", completion = "Thank you for the reminder that sometimes duty calls me to do things that I find uncomfortable.\n\n<Polemarch Adrestes salutes you.>" }
WordHunterWoW_QuestEN[61124] = { title = "Warren Mongrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[61125] = { title = "Malevolent Stygia", description = "", objectives = "" }
WordHunterWoW_QuestEN[61129] = { title = "RSVP: Droman Aliothe", description = "I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. \n\nOnce, I might have enjoyed your Prince's party, but I am no longer suited to revelry.\n\nMy world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home.\n\nI have heard those strange traders, the brokers, have unusual objects from other worlds. \n\nPerhaps they have something from mine?", objectives = "Investigate the offers of the Brokers to see whether a remnant of Aliothe's world may be found.", progress = "Have you found a reminder of my home for me?", completion = "That scent! I would know it anywhere. My den was surrounded by this plant! Thank you. I will keep this token close to me to remember the joyous times." }
WordHunterWoW_QuestEN[61130] = { title = "RSVP: Sika", description = "Hello, <name>! Sika like to help. So much to do.\n\nWould go to Ember Court, but too many things only Sika can do. Very sorry.", objectives = "Find others in Olympic Village to take on Sika's tasks so she can attend the Ember Court.", progress = "Busy, busy. Too busy. No one else can do all the things.", completion = "What's in notes? Others need more help from Sika?\n\n<Sika takes in a deep breath.>\n\nSika can do. Sika always helps." }
WordHunterWoW_QuestEN[61135] = { title = "Heart of the Crest", description = "With this greatest of gifts from Ardenweald, we have the final piece to rebuild the Crest of Ascension.\n\nLet us make certain Willowblossom's sacrifice is not in vain.", objectives = "Place the Vessel of Ardenweald at the Crest of Ascension.", progress = "<The vessel seems drawn to the spot.>", completion = "<Willowblossom's essence will suffuse the crest, completing it so Bastion can once more invest new Ascended.>" }
WordHunterWoW_QuestEN[61136] = { title = "Agonix", description = "", objectives = "" }
WordHunterWoW_QuestEN[61139] = { title = "RSVP: Choofa", description = "Oooh a party! I love parties.\n\nMy friends have to come too or it's just not as much fun. Ask them please! You need to find Awool, Rury, and Slanknen so we can go together.", objectives = "Make sure all of Choofa's friends are able to attend the party.", progress = "Friends all ready?", completion = "Hooray! We are going to a party." }
WordHunterWoW_QuestEN[61140] = { title = "Dath Rezara", description = "", objectives = "" }
WordHunterWoW_QuestEN[61141] = { title = "Deathfang's Favorite Toy", description = "", objectives = "" }
WordHunterWoW_QuestEN[61143] = { title = "Return to the Den", description = "There may be a way to break the curse and free your friend's mind, but it will require some work.\n\nUlfar was wise to send you to me. He knew that a portion of Gorak Tul's power would be necessary, but the other reagents we need do not exist on Azeroth.\n\nMy den is not far from here. Meet me there and I will help you prepare a ritual to break the curse.", objectives = "Meet with Kivarr at her den in Ardenweald.", completion = "It feels good to be out of that cage and back home in my den." }
WordHunterWoW_QuestEN[61145] = { title = "Take The Fight To Them", description = "Our scouts report that Margrave Gharmal gathers their forces at the House of Constructs.\n\nOur necropolis and our new kyrian allies have already begun an aerial assault. I need you to lead our forces on the ground.\n\nMeet me within Zerekriss. We will begin our attack immediately.", objectives = "Take the portal to meet Draka aboard the Zerekriss.", completion = "Victory will be ours." }
WordHunterWoW_QuestEN[61146] = { title = "Manifesting Power", description = "As you know, shedding our memories of life can result in dangerous creatures known as manifestations. They have increased in number and strength as of late, but I believe we can find use for them yet.\n\nManifestations carry great power within them--power we may purify and use in our own creations at the forge here. In making something positive out of such negativity, we do a noble act of service.\n\nSimply eliminate any you come across, and collect their essence. That is all.", objectives = "Collect 15 Condensed Essence from manifestations.", progress = "Be cautious in your travels. Manifestations are no simple foe.", completion = "These will do quite nicely! Go in service, Maw Walker." }
WordHunterWoW_QuestEN[61148] = { title = "AHHH! Real Monsters!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61149] = { title = "[DNT] Kivarr's Remedy", description = "When Gorak Tul developed the power of possession, he used it to construct an army of unliving soldiers made of earth and stone. The wicker creatures you encountered in Drustvar were created in much the same way.\n\nBut these masks are different. I have never seen this power used to control the living...\n\nI can help you brew a potion to break the bonds of possession, but I do not know what will happen when the bonds are severed from a living creature...\n\nThere is only one way to find out.", objectives = "" }
WordHunterWoW_QuestEN[61156] = { title = "Where There's a Quill...", description = "In times long past, Aspirants trained against the fauna of Bastion. The creation of the Centurions rendered such unstructured progression obsolete.\n\nThe many flying denizens of this realm are known for their quills. They are light and sturdy, perfect for our purposes.\n\nGather all that you can, please. Any flying creature shall suffice.", objectives = "Collect 30 Shimmerflight Quills from flying beasts.", progress = "Have you the quills?", completion = "Acceptable portion received. You have my thanks." }
WordHunterWoW_QuestEN[61157] = { title = "Straight to the Point", description = "The horned beasts of Bastion were once commonly used in aspirant training, but centurion sparring units have mostly taken their place. Over the past few eons, their numbers have grown and now must be culled.\n\nTheir horns are critical components to our work. Many specimens are broken from use in battle--they will not suffice. You must be careful in collecting them.\n\nFace them, defeat them, and bring back their horns.", objectives = "Collect 12 Elysian Horns from horned beasts.", progress = "We require as many horns as you are able to procure.", completion = "Acceptable quality and quantity level. Thank you." }
WordHunterWoW_QuestEN[61159] = { title = "Signs of Demise", description = "All members of the Forsworn carry an insignia on their person at all times. We suspect they are imbued with the power of the Temple of Loyalty, bolstering their strength against us.\n\nCollect these insignias from their deceased forms. Strip them of this power, and we shall put it to better use in our own machinations.\n\nSuch is the Archon's will, as it is ours.", objectives = "Collect 20 Forsworn Insignias from Forsworn kyrian.", progress = "Each insignia is a shift of power in our favor.", completion = "These will prove most useful. Well done." }
WordHunterWoW_QuestEN[61161] = { title = "Party Crashers!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61162] = { title = "Party Crashers!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61163] = { title = "Party Crashers!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61164] = { title = "Party Crashers!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61166] = { title = "Reduce, Reuse, Recycle", description = "Centurions need lots of parts. But so do we!\n\nKofi needs their metal. Can be from Centurions or the ground. Your choice!\n\nNot too damaged, ok? Hard to clean!", objectives = "Collect 20 Resonant Alloy from Forsworn centurions or Centurion parts.", progress = "You have metal?", completion = "This is HEAVY metal! Just like Kofi's favorite music!" }
WordHunterWoW_QuestEN[61167] = { title = "[DNT] Delivering Hope", description = "Even Gorak Tul, for all his evil, never used the power of possession to dominate the minds and souls of living creatures.\n\nTo see such a terrible power used on the living is truly frightening. The curse must be stopped before it spreads across both the Shadowlands and Azeroth.\n\nTake this potion and deliver it to your friends in the Heart of the Forest. If there is a way to save those who have been cursed, this potion represents our only hope.", objectives = "" }
WordHunterWoW_QuestEN[61171] = { title = "Unbroken Bonds", description = "The Drust will pay for this foul curse that they've unleashed upon us.\n\nWe have lost too many allies... too many friends to give up now. Even though we cannot save those who have fallen into possession, we can end their torment. I will instruct the hunt to put down all possessed they encounter.\n\nPlease deliver this report to the Winter Queen. She must be told what we have learned.\n\nThank you for your service, {name}. You are a true friend and guardian of Ardenweald.", objectives = "Deliver Lord Herne's report to the Winter Queen.", progress = "What news do you bring?", completion = "If the Thornspeakers have no way to break the curse, then perhaps there truly is no hope for the possessed. These are tidings most dire." }
WordHunterWoW_QuestEN[61173] = { title = "RSVP: Mikanikos", description = "Ember Court sounds interesting ... but very busy right now! Forsworn got into my supplies. Now everything jumbled and disorganized. Can't work in these conditions. My workshop isn't right!\n\nHelp me! Get parts. Most will be damaged and you don't know how to tell about flaws. Bring me many to examine. I will find perfect part.", objectives = "Assist Mikanikos by gathering potentially perfect parts so he can finish his construction and attend the Ember Court.", progress = "Have my parts?", completion = "Perfect one here! See? Rest are bad for my construction. You keep." }
WordHunterWoW_QuestEN[61174] = { title = "RSVP: Baroness Vashj", description = "I am no stranger to courts, Maw Walker. Having attended on Queen Azshara herself, and then later serving my Lord Illidan.\n\nThat does not mean, however, that I accept every invitation I receive.\n\n<Baroness Vashj smirks.>\n\nImpress me with your strength, $p, and I will believe Prince Renathal has power that is worth my time.", objectives = "Gather the heads of fearsome foes to present to Baroness Vashj.", progress = "Where are the heads of your enemies?", completion = "<Baroness Vashj nods approvingly at the display of heads you placed before her.>\n\nWith your power behind the Prince's efforts, I suppose that I had better pay attention.\n\nVery well. I will pay a visit to Prince Renathal and attend his Ember Court." }
WordHunterWoW_QuestEN[61179] = { title = "Forge Ahead", description = "The Eternal Forge has anima again?\n\nAh! Yes! So exciting!\n\nYou must go. Find Forgelite Selene. She will help! So much to make!", objectives = "Speak to Forgelite Selene at the Eternal Forge.", completion = "Beautiful, is it not? I was not sure if I would ever see the forge empowered so ever again." }
WordHunterWoW_QuestEN[61180] = { title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", objectives = "Collect 6 Stitchflesh Designs.", progress = "This foul work must be destroyed.", completion = "Well done. I will see that these are destroyed personally." }
WordHunterWoW_QuestEN[61182] = { title = "Pollen Your Weight", description = "You know Twirlpetal flowers?! They spin around in the light!\n\nWe need pollen. Only pollen if in bloom!\n\nGet a bunch! Flowers in golden fields. And they spin! Round and round!", objectives = "Collect 30 Twirlpetal Pollen in Bastion's plains.", progress = "Pollen very fragile. Won't last long!", completion = "So much! Yes, yes, great! Perfect!" }
WordHunterWoW_QuestEN[61189] = { title = "Further Gelatinous Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[61190] = { title = "Wake of Ashes", description = "It feels as if the Maw itself is sentient... and taking notice of our presence.\n\nWe must leave at once. Bolvar must be informed of what is happening here.\n\nI will bring my father with us. Lead the way out of here, {name}. With haste.", objectives = "Escape from the Maw and report to Bolvar in Oribos.", completion = "Now to get you and your... associates out of here." }
WordHunterWoW_QuestEN[61193] = { title = "A Light Touch", description = "Need Firstborne's Light! You know?\n\nNamed after Archon! Always in water. Kofi's favorite!\n\nShine big light when grown. And go to shore! Easy to see!", objectives = "Collect 15 Firstborne's Light in water sources.", progress = "Only grown flowers! Little ones won't work.", completion = "SO SHINY! Kofi need shades next time!" }
WordHunterWoW_QuestEN[61196] = { title = "The Secret Ingredient", description = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common.\n\nThere is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions.\n\nWill you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", objectives = "Collect 10 Ephemeral Draught.", progress = "Were you able to find the draught?", completion = "I will put test these samples at once! You have my thanks." }
WordHunterWoW_QuestEN[61199] = { title = "Arms Day", description = "Many battles here. Especially lately!\n\nNow weapons all over. Too many. We can use!\n\nGo to big battle places and grab them. We will use better!", objectives = "Collect 20 Blessed Armaments from battlefields.", progress = "Careful with the pointy end!", completion = "These are perfect! Thank you-hoo!" }
WordHunterWoW_QuestEN[61209] = { title = "A Somber Melody", description = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters.\n\nThese memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like.\n\nTake my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", objectives = "Dissipate 15 Kyrian memories along the roads of Bastion.", completion = "The lyre thrums with power! We shall make good use of it." }
WordHunterWoW_QuestEN[61217] = { title = "Champion: Thela Soulsipper", description = "", objectives = "I remember it all! No more shall I be trapped in this place.\n\nAllow me to assist you in your endeavors Maw Walker." }
WordHunterWoW_QuestEN[61218] = { title = "Champion: Dug Gravewell", description = "", objectives = "You've done me a solid, so I'll do you one and help ya out.\n\nMe an' me shovel are at your disposal." }
WordHunterWoW_QuestEN[61219] = { title = "Champion: Nerith Darkwing", description = "", objectives = "After my vengeance it appears I am now without purpose.\n\nI would like to join you and bring terror to your enemies Maw Walker." }
WordHunterWoW_QuestEN[61220] = { title = "AHHH! Real Monsters!", description = "", objectives = "" }
WordHunterWoW_QuestEN[61221] = { title = "Champion: Stonehuck", description = "", objectives = "My Sinstone ain't been gettin' a lot of use lately.\n\nI reckon if I follow ya I might get a chance to put it to good use." }
WordHunterWoW_QuestEN[61222] = { title = "Champion: Kaletar the Mender", description = "", objectives = "Thank you for freeing me Maw Walker.\n\nAllow me to repay your kindness by assisting you." }
WordHunterWoW_QuestEN[61223] = { title = "Champion: Ayeleth the Deprived", description = "", objectives = "More! \n\nLet me drink from your enemies! \n\nUnleash me upon them!" }
WordHunterWoW_QuestEN[61226] = { title = "Extra Limbs", description = "We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit.\n\nThree individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it.\n\nThere remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her.\n\nMeet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.", objectives = "Locate and assist Navigator Xennir.", completion = "We have suffered so terribly. I must preserve what I still have." }
WordHunterWoW_QuestEN[61227] = { title = "The Other Foot", description = "It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash.\n\nBut opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections.\n\nFind this individual. An enemy deserter could make for a potential ally.", objectives = "Locate Mechanic Ansid.", completion = "So you need a mechanic? Well, you're in luck!" }
WordHunterWoW_QuestEN[61228] = { title = "Dug's Missing Shovel", description = "", objectives = "" }
WordHunterWoW_QuestEN[61230] = { title = "Outside Influence", description = "It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir.\n\nBut Baroness Vashj has informed me of a means to acquire a new helmsman.\n\nFollow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require.\n\nI suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.", objectives = "Meet with Khaliiq at the House of Eyes' communications pillar.", completion = "I appreciate your punctuality." }
WordHunterWoW_QuestEN[61234] = { title = "Stonehuck's Sinstone", description = "", objectives = "" }
WordHunterWoW_QuestEN[61243] = { title = "Thela's Memory Stone", description = "", objectives = "" }
WordHunterWoW_QuestEN[61246] = { title = "Power of the Chosen", description = "The necropolis is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.", objectives = "Destroy the Bilebloat Juggernauts.", progress = "Every moment the juggernauts remain standing, our position is in jeopardy!", completion = "Such power! Gharmal will have no choice but to face us now." }
WordHunterWoW_QuestEN[61248] = { title = "Kaletar's Freedom", description = "", objectives = "" }
WordHunterWoW_QuestEN[61252] = { title = "Call In a Favor", description = "We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her.\n\nActivate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.", objectives = "Summon Helmsman Caliroux and defeat her.", completion = "My baroness's trust in you is well warranted." }
WordHunterWoW_QuestEN[61255] = { title = "RSVP: Alexandros Mograine", description = "It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. \n\nBut before I leave my post, I must ensure my comrades will be safe while I am away.\n\nFight your way into the Ossein Foundry and retrieve weapons from our rivals there.\n\nI will have them distributed among the troops while I make ready to depart.", objectives = "Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry.", progress = "Have you gotten the weapons yet?", completion = "A strong advantage. We gain additional arms and deprive our foes of the same." }
WordHunterWoW_QuestEN[61256] = { title = "RSVP: Kleia and Pelagos", description = "Oh, how wonderful! Thank you for the invitation to the Ember Court.\n\nWe were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?", objectives = "Join Kleia and Pelagos in the Meditation chamber and face the memories of your past.", progress = "Have you completed your meditation yet?", completion = "I always find meditation so relaxing and rewarding. Don't you? Now we are better prepared for our journey!" }
WordHunterWoW_QuestEN[61259] = { title = "Ayeleth's Hunger", description = "", objectives = "" }
WordHunterWoW_QuestEN[61262] = { title = "Nerith's Vengeance", description = "", objectives = "" }
WordHunterWoW_QuestEN[61265] = { title = "Blueprint: Charm of Alacrity", description = "<You have discovered plans for a charm that seems to hasten your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "Bring the Blueprint: Charm of Alacrity to Dactylis." }
WordHunterWoW_QuestEN[61269] = { title = "Blueprint: Charm of Persistence", description = "<You have discovered plans for a charm that encourages your soulbinds to persevere in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "Bring the Blueprint: Charm of Persistence to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[61272] = { title = "Blueprint: Charm of Discord", description = "<You have discovered plans for a charm that seems to damage your soulbinds' enemies in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "Bring the Blueprint: Charm of Discord to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[61303] = { title = "It's Raining Sparkles", description = "", objectives = "" }
WordHunterWoW_QuestEN[61304] = { title = "Blueprint: Kyrian Smith's Kit", description = "<You have discovered plans for a kit that lets you repair a piece of armor while out adventuring.\n\nDactylis should be able to help you with crafting this kit.>", objectives = "Bring the Blueprint: Kyrian Smith's Kit to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[61313] = { title = "Champion: Kythekios", description = "", objectives = "I can fight once more! Allow me to test my mettle against your enemies!" }
WordHunterWoW_QuestEN[61314] = { title = "REUSE ME - SCS", description = "You'll need a vessel to hold the anima you need to collect, but one that will also allow you to channel said anima.\n\nThere was once such a device ages ago, but as of late they've become much more rare.\n\nIn my travels through the Maw, I have seen one once. It is in the (AREA NAME), held by (CREATURE).\n\nYou'll need luck on your side in order to retrieve it.", objectives = "Obtain the Anima Focuser." }
WordHunterWoW_QuestEN[61317] = { title = "Champion: Teliah", description = "", objectives = "This new weapon is lacking one thing, the blood of my enemies! Allow me to rectify that." }
WordHunterWoW_QuestEN[61318] = { title = "Champion: Telethakas", description = "", objectives = "Honor has been satisfied. Now I require a new master to serve. I would like that to be you." }
WordHunterWoW_QuestEN[61319] = { title = "Champion: Hala", description = "", objectives = "You have returned my sword to me. I am indebted to you Maw Walker. Allow me to assist you further." }
WordHunterWoW_QuestEN[61320] = { title = "Champion: Molako", description = "", objectives = "I cannot thank you enough for my freedom. I would like to help you further in your tasks." }
WordHunterWoW_QuestEN[61321] = { title = "Champion: Ispiron", description = "", objectives = "I am whole once more. I would be nothing if it were not for you. I shall dedicate my power to your cause." }
WordHunterWoW_QuestEN[61322] = { title = "Kythekios' Memory Stone", description = "", objectives = "" }
WordHunterWoW_QuestEN[61323] = { title = "See What You've Done", description = "We have gathered what forces we can. I hope it is enough.\n\nWithin the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus.\n\nTo preserve all that remains to us, we must end her. \n\nLead the attack, and the Eyes will join you. We will reclaim our home.", objectives = "Slay Gorgantus the Gutter.", completion = "I shall execute Akarek's will once more." }
WordHunterWoW_QuestEN[61326] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61327] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61328] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61329] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61330] = { title = "Teliah's Stolen Spear", description = "", objectives = "" }
WordHunterWoW_QuestEN[61331] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", objectives = "Rescue Souls in the Maw.", completion = "Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald." }
WordHunterWoW_QuestEN[61332] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", objectives = "Rescue 5 Souls from the Maw.", completion = "Well done. They have been spared a truly cruel existence." }
WordHunterWoW_QuestEN[61333] = { title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", objectives = "Rescue Souls in the Maw.", completion = "Excellent Maw Walker. Our armies here will grow stronger with each soul you return." }
WordHunterWoW_QuestEN[61334] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", objectives = "Rescue Souls in the Maw.", completion = "A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear, their fate is better in our hands than the Jailer's." }
WordHunterWoW_QuestEN[61335] = { title = "Rage Against the Cage", description = "You're looking for a mechanic, are you? Look no further!\n\nI've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods.\n\nBut now you need help, right? I'm your construct!\n\nYou get me out of here, and you've got yourself a new mechanic!", objectives = "Free Ansid the Mechanic from his cage using Toc's key.", progress = "Got a way to free me?", completion = "Thanks for the rescue! I owe you one." }
WordHunterWoW_QuestEN[61337] = { title = "March of the Eternal Protector", description = "", objectives = "" }
WordHunterWoW_QuestEN[61340] = { title = "Telethakas' Revenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[61342] = { title = "Battles Won Long Ago", description = "", objectives = "" }
WordHunterWoW_QuestEN[61343] = { title = "Battles Won Long Ago", description = "", objectives = "" }
WordHunterWoW_QuestEN[61346] = { title = "Cyrixia the Willbreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[61347] = { title = "Molako's Freedom", description = "", objectives = "" }
WordHunterWoW_QuestEN[61348] = { title = "Hala's Sword", description = "", objectives = "" }
WordHunterWoW_QuestEN[61351] = { title = "Ancient Sinstone (+Formal)", description = "", objectives = "<Prince Renathal looks at the Ancient Sinstone you're carrying with great interest.>\n\nNow where did you find that old sinstone?", progress = "<Prince Renathal looks at the Ancient Sinstone you're carrying with great interest.>\n\nNow where did you find that old sinstone?", completion = "I truly appreciate you bringing this sinstone to me, <name>.\n\nIt is almost as old as I am." }
WordHunterWoW_QuestEN[61352] = { title = "All Will Be Consumed", description = "", objectives = "" }
WordHunterWoW_QuestEN[61353] = { title = "All Will Be Consumed", description = "", objectives = "" }
WordHunterWoW_QuestEN[61354] = { title = "RSVP: Lady Moonberry", description = "Of course I will attend, <name>, the Ember Court sounds like a lot of fun! \n\nBut I cannot go without a gift!\n\nHospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests.\n\n<Lady Moonberry suppresses a smirk.>\n\nNow for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones.\n\nEasy enough for someone of your prowess.", objectives = "Collect 3 Silverheart Vine Leaves, 9 Blooming Lasher Spurs, and a Gorm Pheromone Gland.", progress = "Have you found all of the components for my gift?", completion = "This will be funny. Ah, I mean festive." }
WordHunterWoW_QuestEN[61355] = { title = "Rule 2: Keep a Low Profile", description = "Though you may wish to depart with your precious souls in tow, we now have additional matters to settle first.\n\nThe Eye of the Jailer is upon you. And that does not bode well for either of us.\n\nTake this device. You will reinforce my wards to ensure he does not take notice of me as well.\n\nThe last thing I need is a loud, inelegant mortal bringing more attention my way. I can't have the Jailer capturing me, after all.\n\nI'm far too valuable.", objectives = "Reinforce 4 Soul Wards.", progress = "Our business is not yet complete. Attend to my wards.", completion = "That should be enough to hide us from the Jailer's sight.\n\nI need you alive. For the time being, at least.\n\nNow, back to business." }
WordHunterWoW_QuestEN[61356] = { title = "Echthra, Dame of Hatred", description = "We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds.\n\nShe has requested a special anointment oil used in kyrian ceremonies in return for her memory.", objectives = "We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds.\n\nShe has requested a special anointment oil used in kyrian ceremonies in return for her memory.", progress = "We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds.\n\nShe has requested a special anointment oil used in kyrian ceremonies in return for her memory.", completion = "That should satisfy our contact. Well done." }
WordHunterWoW_QuestEN[61357] = { title = "Hatred Abated", description = "As agreed, you may take my memory for the trials you seek.\n\nHeed this warning, mortal--even as an echo of my physical form I will attack without hesitation. Expect no mercy, for I will show none.\n\nYou have done me a great service this day. See to your business.", objectives = "Capture Echthra's memory.", completion = "A worthy acquisition--you did what you must. I will inform Adrestes of this spy network." }
WordHunterWoW_QuestEN[61358] = { title = "Alderyn and Myn'ir", description = "The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest.\n\nWe have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", objectives = "The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest.\n\nWe have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", progress = "The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest.\n\nWe have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", completion = "This spear should be exactly what they need to take down their quarry." }
WordHunterWoW_QuestEN[61359] = { title = "Power of the Primus", description = "As a Necrolord, your duty is to defend the Shadowlands. To carry out such service, the Primus grants us his strength.\n\nStand upon the altar of the Primus. Let his power become your own.", objectives = "Kneel before the Primus and receive his power!", progress = "It is a great gift to wield the Primus's power.", completion = "You are a Necrolord, <name>. We stand strong." }
WordHunterWoW_QuestEN[61360] = { title = "The Hunt's Gratitude", description = "The forests of Ardenweald are safer with your help, envoy of the kyrian.\n\nAs a reward for your aid, we shall allow you to capture our memory. It is an honor to be chosen to help train the mighty warriors of Bastion.\n\nWhenever you are ready.", objectives = "Capture Alderyn and Myn'ir's memories.", completion = "The Wild Hunt are incredible hunters. I look forward to seeing what your soulbinds learn." }
WordHunterWoW_QuestEN[61361] = { title = "Nuuminuuru", description = "The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed.\n\nOne tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", objectives = "The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed.\n\nOne tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", progress = "The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed.\n\nOne tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", completion = "Though their request was quite nonstandard, I am sure this fountain will be exactly what they need." }
WordHunterWoW_QuestEN[61362] = { title = "Caretaker of Faeries", description = "Tirnenn and faeries hold many dissimilarities.\n\nWhile tirnenn stand patient and calm, like the trees that grow tall and protect us, faeries dance and dart and declare their desires directly.\n\nDespite these differences, we stand together. Learning, growing, evolving.\n\nWe will help you and yours achieve the same symbiotic serenity.", objectives = "Capture Nuuminuuru's memory.", completion = "It seems you have already learned from the tirnenn. I look forward to seeing what else they have to share!" }
WordHunterWoW_QuestEN[61363] = { title = "Mad Mortimer", description = "An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst.\n\nIf we lend him aid, he has agreed to allow you to capture his memory for the Path.", objectives = "An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst.\n\nIf we lend him aid, he has agreed to allow you to capture his memory for the Path.", progress = "An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst.\n\nIf we lend him aid, he has agreed to allow you to capture his memory for the Path.", completion = "<Dactylis inspects the catalyst.>\n\nWell crafted. This should work perfectly for the scientist's needs." }
WordHunterWoW_QuestEN[61364] = { title = "Oozing with Opportunity", description = "They called me mad! As a matter of fact, they still do!\n\nAh, but none of them have the mental acuity of Doctor James Mortimus of the very much in-tact House of Plagues, nor his handsome smile! Fools!\n\nWith the catalyst you have so kindly provided, dear...whatever you are...certainly not a kyrian...\n\nI digress!\n\nWe shall get to whatever it is you wanted in a moment, for now is the time of SCIENCE! Come, come, let me show you the wondrous fruits of my labors!", objectives = "Aid Mad Mortimer in his experiment, then capture his memory using the Soul Mirror.", completion = "It appears you were successful. Well done, as always." }
WordHunterWoW_QuestEN[61365] = { title = "Splinterbark Nightmare", description = "Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald.\n\nIf we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon, we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", objectives = "Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald.\n\nIf we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon, we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", progress = "Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald.\n\nIf we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon, we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", completion = "May a great blow be struck to the drust this day." }
WordHunterWoW_QuestEN[61366] = { title = "Tactical Operation", description = "Your target lies near the Oaken Assembly in Ardenweald on the Elder Strand. Take caution, for powerful drust forces lurk nearby.\n\nOnce your target is in sight, activate the beacon and protect the praetors that arrive as they work to subdue the beast. You will only be able to capture its memory once it has been fully incapacitated.\n\nMake haste, and good luck. Follow the path.", objectives = "Activate the Praetor Resonance Beacon at the Splinterbark Nightmare at the Elder Strand in Ardenweald, protect the praetors, then capture the Splinterbark Nightmare's memory.", completion = "The Nightmare's memory will prove a formidable opponent. May its physical form remain at rest." }
WordHunterWoW_QuestEN[61367] = { title = "Thran'tiok", description = "Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. \n\nTraining against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", objectives = "Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. \n\nTraining against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", progress = "Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. \n\nTraining against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", completion = "This crystal will be useful in finding and capturing the memory you seek." }
WordHunterWoW_QuestEN[61368] = { title = "Filching Phylacteries", description = "This phylactery holds the soul of Thran'tiok... her very essence.\n\nBe quick in whatever you need to do. I must get this piece of her soul away from here before she returns.\n\nHer paranoia shall truly be her end.", objectives = "Capture Thran'tiok's memory through the Phylactery of Pain.", completion = "It is fortunate that you were able to capture the lich's memory without encountering her herself.\n\nSuch a powerful being is not to be underestimated." }
WordHunterWoW_QuestEN[61369] = { title = "Craven Corinth", description = "One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward.\n\nHis memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", objectives = "One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward.\n\nHis memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", progress = "One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward.\n\nHis memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", completion = "I am pleased that I retained the designs for this venthyr key for all those millenia. It was not easy to come by." }
WordHunterWoW_QuestEN[61370] = { title = "No Other Way", description = "Corinth will not surrender his memory willingly. You must weaken him sufficiently before he will relent to the soul mirror's energy.\n\nYou will find him deep within the Desiccation in Revendreth, locked away among the other light-scarred venthyr. Once you free him, he will surely attack in his confused rage.\n\nSubdue him, and capture his memory. He may then roam free among his kind.", objectives = "Subdue Craven Corinth in the Desiccation in Revendreth, then capture his memory.", completion = "Another worthy acquisition. Corinth will be a worthy test of your skills." }
WordHunterWoW_QuestEN[61371] = { title = "Athanos", description = "For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos.\n\nIt has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard. The blade was disassembled upon his departure, as is tradition.\n\nShould Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", objectives = "For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos.\n\nIt has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard. The blade was disassembled upon his departure, as is tradition.\n\nShould Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", progress = "For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos.\n\nIt has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard. The blade was disassembled upon his departure, as is tradition.\n\nShould Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", completion = "May Athanos' return be upon us at last." }
WordHunterWoW_QuestEN[61372] = { title = "Back to Him", description = "Even with Humility's Guard in hand, if you are to convince Athanos to join the Path of Ascension once more then you must prove yourself a worthy adversary.\n\nEnter the ring and wield the spear against him. Even with its power you cannot hope to defeat him, but it should be able to parry his mighty stomp.\n\nThwart his assault for long enough, and he will surely allow you to capture his memory.", objectives = "Block Athanos' Power Stomp 6 times, then capture his memory.", completion = "<Dactylis' face expresses what appears to be surprise.>\n\nYou actually did it? Very well! A most worthy opponent indeed." }
WordHunterWoW_QuestEN[61373] = { title = "Azaruux, the Realm Ender", description = "You must act at once!\n\nA devourer of incredible strength has opened a rift in the coliseum and even now threatens to consume it! What few fighters were present at the time struggle to keep the creature at bay.\n\nIf this horror is not stopped, it will continue into the rest of the spires. You must take what anima you can in the area and subdue it.\n\nOnce the threat has been negated, take this spare mirror and capture its memory so we may learn more of its kind for future encounters.", objectives = "Absorb anima to activate the Anima Confluxes to subdue Azaruux, then capture its memory.", progress = "You must not delay!", completion = "A heroic effort! We will learn much from battling its kind." }
WordHunterWoW_QuestEN[61388] = { title = "A Journey Made Together", description = "Binding souls is but the first step. \n\nOver time, the power of our bond will grow in strength and manifest itself in the form of amazing new abilities!\n\nTo tap into this newfound strength, all you must do is place your hand upon the Forge of Bonds. There is no price to pay--the only limitation is your connection to Necrolords.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", progress = "This device is merely a conduit to the strength that lies within us both.", completion = "May we prove worthy allies for the battles to come." }
WordHunterWoW_QuestEN[61391] = { title = "The Eye of the Jailer", description = "<The air around you stands still. A chill of domination suffuses your being. You hear a voice.>\n\nYes... I remember you...\n\nDo you think that because you evaded my grasp once, that I would let it happen again?\n\nNo. The Maw answers to me. All that befalls you here will be because I willed it so.\n\nDeath comes for you, mortal. Everywhere you go, my eye is upon you.", objectives = "Speak with Ve'nari about what you just heard.<The air around you stands still. A chill of domination suffuses your being. You hear a voice.>\n\nYes... I remember you...\n\nDo you think that because you evaded my grasp once, that I would let it happen again?\n\nNo. The Maw answers to me. All that befalls you here will be because I willed it so.\n\nDeath comes for you, mortal. Everywhere you go, my eye is upon you.You will learn:" }
WordHunterWoW_QuestEN[61394] = { title = "Gormling Toss: Tranquil Pools", description = "", objectives = "" }
WordHunterWoW_QuestEN[61395] = { title = "Spare Parts", description = "", objectives = "" }
WordHunterWoW_QuestEN[61396] = { title = "Dark Developments", description = "<The torn document appears to have been written by Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to your kyrian allies.>", objectives = "Bring the Abhorrent Design to Artemede.\n\nProvided item:", completion = "Allow me to read this for a moment." }
WordHunterWoW_QuestEN[61397] = { title = "Opportunity Strikes", description = "This sanctum cannot function on anima alone. It will take many willing souls working in harmony to unlock the full potential of the Seat of the Primus.\n\nOur Soul Warden is always in search of new souls to induct into the sanctum. Your ability to travel back and forth from the Maw will undoubtedly prove useful to him.\n\nYou should pay him a visit to see what assistance you can offer.", objectives = "Speak to Osbourne Black.", completion = "With your unique abilities, we have an opportunity we've never had before." }
WordHunterWoW_QuestEN[61398] = { title = "Ember Court: Traditional", description = "Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court.\n\nVenthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity.\n\nOur resources are stretched thin, {name}. We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom. There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.", objectives = "Collect 50 Candle Wax and 20 Death Blossoms. Death Blossoms can be harvested with the herbalism skill.", progress = "Have you managed to gather the raw materials for our artisans yet?", completion = "We had best get to work right away. Thank you." }
WordHunterWoW_QuestEN[61399] = { title = "Ember Court: Mortal Reminders", description = "For a reasonable renumeration, Ta Cartel can supply the decorations you require. \n\nRestocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer.\n\nYour world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.", objectives = "Help Keeper Ta'saran replenish stock by retrieving the items on the list he's provided you.", progress = "Have you found something that fits each item on the list?", completion = "Yes, yes, this is excellent work. Our clients will love these." }
WordHunterWoW_QuestEN[61400] = { title = "Ember Court: Mystery Mirrors", description = "I support Prince Renathal's efforts and will certainly help the Ember Court!\n\nMystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time.\n\nYou will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.", objectives = "Collect 12 Shrouded Mirror Shards, 12 Scorched Mirror Fragments, and 3 Molten Cores.", progress = "Have you found the mirror fragments and an Ashen Core?", completion = "Thank you for collecting the necessary ingredients to make the mirrors." }
WordHunterWoW_QuestEN[61401] = { title = "Ember Court: Venthyr Volunteers", description = "Oh, hello again!\n\nDid you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits.\n\nI need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.", objectives = "Place 6 Recruiting Posters and test 3 Sinfall Recruits.", progress = "Those posters need to be put in visible locations and the recruits need to be tested.", completion = "Hah! I anticipate some fun with this. I will test the remaining recruits!" }
WordHunterWoW_QuestEN[61402] = { title = "Ember Court: Stoneborn Reserves", description = "To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them.\n\nWe will also need weapons for them.\n\nSort that out and I will make sure the Prince and his guests are well protected.", objectives = "Fill the anima canister by defeating enemy stoneborn in Dominance Keep. Collect 12 Stoneborn Glaives.", progress = "Have you filled the anima canister and found enough weapons to equip our new comrades?", completion = "Good. This will be sufficient for me to get those reserves ready." }
WordHunterWoW_QuestEN[61403] = { title = "Ember Court: Maldraxxus Army", description = "So your prince's little parties have attracted unwanted attention?\n\n<Emeni laughs.>\n\nI have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards!\n\nBut I have finally found a solution.\n\nTake this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.", objectives = "Release Emeni's projection in Vol'dun and help her defeat her ancient sethrak enemies.", progress = "What are you waiting for? Those sethrak won't impale themselves.", completion = "So much slaughter... So many names removed from my list...\n\nA whole new generation of sethrak will fear my name!" }
WordHunterWoW_QuestEN[61404] = { title = "Ember Court: Tubbins's Tea Party", description = "Theotar need tea for party? Tubbins make best!\n\nSpecial tea. Very special. Only I can make. Recipe need very good water from garden place. Good pool on special floaty island!\n\nYou go get and Tubbins makes tea!", objectives = "Collect Pristine Water from Ardenweald's Distant Grotto.", progress = "Need special water to make special tea. Makes sense.", completion = "Mmm, water taste clean...\n\nLike me! I'm cleanest!" }
WordHunterWoW_QuestEN[61405] = { title = "Ember Court: Divine Desserts", description = "Recipes very important. Must not be lost!\n\nI learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn.\n\nI bring desserts to Ember Court.\n\nFair, yes?", objectives = "Collect a sample of Banana Beef Pudding, 30 Aethereal Meat, and 20 Phantasmal Haunch. Then taste-test Stewart's concoction.", progress = "You ready to give ingredients and taste test?", completion = "Ones that seem simple are harder. All ingredients must be perfect." }
WordHunterWoW_QuestEN[61406] = { title = "Ember Court: Mushroom Surprise!", description = "I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court!\n\nHmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me.\n\nLet's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps. You'll need to grapple your way up there.", objectives = "Collect 18 Feather Caps, 24 Lacy Bell Morels, and 4 Violet Frills.", progress = "Have you filled the foraging bag?", completion = "Well, those smell good and ripe! You're pretty good at this, <name>." }
WordHunterWoW_QuestEN[61407] = { title = "Ember Court: Atoning Rituals", description = "If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement.\n\nHowever, I must ask for your assistance preparing the necessary components quickly.\n\nCapture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose.\n\nSinstone fragments will also help us identify the sins of these lost souls.", objectives = "Collect 125 Sinstone Fragments and deliver 2 Fugitive Souls to Avowed Ritualists.", progress = "Fugitive souls can be found hiding in the darkest corners of the Halls of Atonement.", completion = "Thank you, <name>. The Accuser and I will personally lead the rituals during the Ember Court.\n\nWe will remind everyone of Revendreth's true purpose." }
WordHunterWoW_QuestEN[61408] = { title = "Ember Court: Glimpse of the Wilds", description = "It would be wonderful to show Revendreth the wild creatures of Ardenweald!\n\nYou can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. \n\nHere's a net to use to subdue the Territorial Waders. They should follow you once you've caught them.\n\nHighland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly.\n\nWe will get others to help too. This sounds like fun.", objectives = "Bring 3 Highland Runestags, 8 Radiant Groupers and 4 subdued Territorial Waders to Niya.", progress = "We need Radiant Groupers, Highland Runestags, and Territorial Waders please.", completion = "Thank you <name>." }
WordHunterWoW_QuestEN[61411] = { title = "Our Heart Will Go On", description = "", objectives = "" }
WordHunterWoW_QuestEN[61412] = { title = "An Early End", description = "Within the Hall of Chains lie more constructs that are nearly complete. As we speak, the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, then the destruction we have wrought thus far will make little difference in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any of these abominations you encounter.", objectives = "Destroy 6 Inert Butchers.", completion = "Every abomination denied is one less foe to contend with when we face Gharmal." }
WordHunterWoW_QuestEN[61414] = { title = "Faulty Fireworks (+Safe)", description = "", objectives = "<Prince Renathal looks at the Flimsy Firework you're carrying with great concern.>\n\nThis cheap party favor could send all of Sinfall up in flames!", progress = "<Prince Renathal looks at the Flimsy Firework you're carrying with great concern.>\n\nThis cheap party favor could send all of Sinfall up in flames!", completion = "I truly appreciate you bringing these fireworks to me, <name>.\n\nSuch cheap favors have no place at our party." }
WordHunterWoW_QuestEN[61421] = { title = "Champion: Blisswing", description = "", objectives = "You have rescued both Enothia and myself. Allow me to repay your kindness and join you on your quest." }
WordHunterWoW_QuestEN[61422] = { title = "Champion: Duskleaf", description = "", objectives = "Finally revenge is served. Or is that justice? Something has been served for me, and maybe now I can serve you." }
WordHunterWoW_QuestEN[61423] = { title = "Champion: Karynmwylyann", description = "", objectives = "My memories have been restored and now I need a new path. I shall join you along yours for a time if you wish." }
WordHunterWoW_QuestEN[61424] = { title = "Champion: Chalkyth", description = "", objectives = "Allow me and my saber to thrash your enemies once more!" }
WordHunterWoW_QuestEN[61425] = { title = "Champion: Lloth'wellyn", description = "", objectives = "Thank you for the help, I made a note of it. I believe I may also be able to help you further as well." }
WordHunterWoW_QuestEN[61426] = { title = "Champion: Yira'lya", description = "", objectives = "Please take me back to Ardenweald. I can do nothing to help from here." }
WordHunterWoW_QuestEN[61427] = { title = "Blisswing's Rescue", description = "", objectives = "" }
WordHunterWoW_QuestEN[61428] = { title = "Duskleaf's Revenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[61429] = { title = "Karynmwylyann's Roots", description = "", objectives = "" }
WordHunterWoW_QuestEN[61430] = { title = "Chalkyth's Saber", description = "", objectives = "" }
WordHunterWoW_QuestEN[61431] = { title = "Lloth'wellyn's Breakthrough", description = "", objectives = "" }
WordHunterWoW_QuestEN[61432] = { title = "Lost Journals", description = "", objectives = "What is that you have found?", progress = "What is that you have found?", completion = "I recognize that handwriting, are these actually the prince's pages? I will make sure they make their way to Sinfall, the court is grateful you returned them." }
WordHunterWoW_QuestEN[61433] = { title = "Giant Lungcap", description = "", objectives = "Is that... a lungcap?\n\nHow did you possibly find one of those here in Revendreth?\n\nNo matter. Throw it on a platter!\n\nPerhaps they will not notice how terrible it tastes.", progress = "Is that... a lungcap?\n\nHow did you possibly find one of those here in Revendreth?\n\nNo matter. Throw it on a platter!\n\nPerhaps they will not notice how terrible it tastes.", completion = "What it lacks in flavor, it more than compensates for in size.\n\nI should be able to fill three platters with this if carve it correctly." }
WordHunterWoW_QuestEN[61434] = { title = "Alchemy: Flask of Measured Discipline", description = "", objectives = "" }
WordHunterWoW_QuestEN[61435] = { title = "Blacksmithing: Stalker Arrowheads", description = "", objectives = "" }
WordHunterWoW_QuestEN[61436] = { title = "Field Trip", description = "Now that you have the catalyst, you need only bring it to Mortimer in Maldraxxus. Our last correspondence indicates that his laboratory is still in-tact within the former House of Plagues.\n\nExercise caution in your journey--what remains of the house is fraught with danger, and Mortimer himself has earned a less than pristine reputation among his peers.", objectives = "Bring the Catalyst of Creation to Mad Mortimer in the House of Plagues in Maldraxxus.\n\nProvided item:", completion = "Ah, yes! You must be the one from Bastion! Marvelous!" }
WordHunterWoW_QuestEN[61439] = { title = "Cooking: Steward Stew", description = "", objectives = "" }
WordHunterWoW_QuestEN[61440] = { title = "Enchanting: Boundless Basket", description = "", objectives = "" }
WordHunterWoW_QuestEN[61441] = { title = "Engineering: Power Hammer", description = "", objectives = "" }
WordHunterWoW_QuestEN[61442] = { title = "Fishing: Glorious Shimmerfin", description = "", objectives = "" }
WordHunterWoW_QuestEN[61443] = { title = "Herbalism: Windswept Rising Glory", description = "", objectives = "" }
WordHunterWoW_QuestEN[61445] = { title = "Court Gossip (+Relaxing)", description = "", objectives = "<Prince Renathal extends an arm while keeping his head held high.>\n\nI will take that off of your hands.", progress = "<Prince Renathal extends an arm while keeping his head held high.>\n\nI will take that off of your hands.", completion = "This court is no place for such idle gossip. I will discard the scroll at once!" }
WordHunterWoW_QuestEN[61446] = { title = "Inscription: Invocation of Duty", description = "", objectives = "" }
WordHunterWoW_QuestEN[61447] = { title = "Jewelcrafting: Gleaming Kyranite Necklace", description = "", objectives = "" }
WordHunterWoW_QuestEN[61448] = { title = "Blob of Slime (+Clean)", description = "", objectives = "<Prince Renathal leans back and turns away while extending an arm forward.>\n\nThis filth must be disposed of immediately!", progress = "<Prince Renathal leans back and turns away while extending an arm forward.>\n\nThis filth must be disposed of immediately!", completion = "Thank you for ensuring our party is as pristine as it should be." }
WordHunterWoW_QuestEN[61449] = { title = "Leatherworking: Steelhide Leather Harness", description = "", objectives = "" }
WordHunterWoW_QuestEN[61450] = { title = "Cluster of Seeds (+Humble)", description = "", objectives = "What do we have here? An assortment of seeds?", progress = "What do we have here? An assortment of seeds?", completion = "While not known for their flavor, I'm sure these morsels will please one of the picky palates in attendance." }
WordHunterWoW_QuestEN[61467] = { title = "Mining: Luminous Solenium Cluster", description = "", objectives = "" }
WordHunterWoW_QuestEN[61468] = { title = "Skinning: Plush Copperfur Pelts", description = "", objectives = "" }
WordHunterWoW_QuestEN[61469] = { title = "Tailoring: Woven Gossamer Tunic", description = "", objectives = "" }
WordHunterWoW_QuestEN[61473] = { title = "Sourcing Your Own Materials", description = "I can aid you in crafting many pieces of equipment for your soulbinds.\n\nThough they may only equip one at a time, each piece grants a new ability that they may not have without it.\n\nThis time you must source your own materials from around the Shadowlands. When you have collected them, return to me and we can create the footpads!", objectives = "Craft the Herald's Footpads with Dactylis. Check the materials in the crafting window to learn where you can gather them.", progress = "You find materials okay? Blueprint can help!", completion = "Boots? Very nice! I hold on for safe keeping." }
WordHunterWoW_QuestEN[61475] = { title = "The Heart of the Forest", description = "I knew we were gonna get along! Welcome to our covenant. Well, almost.\n\nThere's just a few details left. Little things. You know. Oaths to be made, blood pacts to sort out, firstborns to be promised.\n\n<Moonberry snorts a laugh.>\n\nI'm just kidding!\n\nWell, not about the oaths part. We take those seriously around here.\n\nI'll meet you at the camp outside the Heart of the Forest!", objectives = "Meet Lady Moonberry at the Refugee Camp beside the Heart of the Forest in Ardenweald.", completion = "This is going to be such fun!" }
WordHunterWoW_QuestEN[61477] = { title = "Calling the Champions", description = "", objectives = "" }
WordHunterWoW_QuestEN[61478] = { title = "Humble Beginnings", description = "With Humility's Guard whole once more, you may be able to coax Athanos back into the arena.\n\nTravel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone--she guides all those who seek an encounter with Athanos.\n\nPresent the spear to her. She will know your intent and instruct you further.", objectives = "Bring Humility's Guard to Forgelite Sophone in Aspirant's Crucible.", progress = "What is that you have there?", completion = "I never thought I would see this spear again! This will be most interesting." }
WordHunterWoW_QuestEN[61479] = { title = "The Boon of Shapes", description = "<Moonberry looks serious.>\n\nMortal though you are, you have chosen to become one of our champions. While you uphold our cause, we are obligated to extend hospitality to you within our sacred hall and grant you certain boons.\n\nAs a member of the Court of Night, I can bestow our powers on chosen mortals.\n\n{name}, {class} of Azeroth,  I bid you welcome to the first tree, Tirna Achiad, the Heart of the Forest.\n\nPlease, follow me.", objectives = "Accompany Lady Moonberry into the Heart of the Forest and take part in the ceremony.", progress = "Accept this boon and use it for the benefit of Ardenweald.", completion = "May this boon aid you in the trials ahead, <name>.\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... traditions which we must uphold." }
WordHunterWoW_QuestEN[61485] = { title = "I'll Only Say This Once", description = "At last, we are fully prepared to enact the baroness's plan.\n\nNow that you have arrived, I will recount our roles one final time. Then we will seize our fate.\n\nListen closely.", objectives = "Speak with Whisperer Vyn about the plan.", completion = "Let us put our plan into motion." }
WordHunterWoW_QuestEN[61486] = { title = "The Banshee's Champion", description = "I... we... I mean... he's...\n\n<The young courier gulps.>\n\nWe found him. We found the Blightcaller.\n\nI was on patrol like I'd done a hundred times before only there he was sitting on the front porch of that old house with those terrible dogs and I swear he smirked at me and stared with those fiery red eyes and--\n\n<The young courier wipes his brow.>\n\nHe's at the Marris Stead. Our forces have him surrounded, but, uh...\n\nYou should probably gather your friends. I don't think he plans to surrender.", objectives = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.", progress = "What news do you bring of the Blightcaller?", completion = "At long last, one of the most notorious enemies of the Alliance has met his end.\n\nWell done, <name>. Well done indeed." }
WordHunterWoW_QuestEN[61488] = { title = "The Banshee's Champion", description = "<The messenger appears visibly shaken.>\n\nWord has reached us of... well, I'm not quite sure how to put it...\n\nThe Blightcaller has been found.\n\nHorde forces have been scouring Azeroth for any sign of him. Determined to make him answer for his crimes.\n\nOne of our Argent patrols has found him. Not hiding in some distant land. Just... waiting at his old homestead.\n\nWe have him surrounded, but, uh, I confess I don't like our odds.\n\nPerhaps you could gather your allies and bring him to justice.", objectives = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.", completion = "<A wry smile crosses the Regent Lord's face.>\n\nA fitting end to the Blightcaller. I only wish I had been there to see it." }
WordHunterWoW_QuestEN[61489] = { title = "Of Hearsay and Heresy", description = "Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus.\n\nBring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger.\n\nGood luck, Maw Walker.", objectives = "Find Echthra in the House of Eyes in Maldraxxus.", progress = "Be cautious. There are many in the House of Eyes who would not tolerate your presence.", completion = "Let us have words quickly--before I change my mind." }
WordHunterWoW_QuestEN[61490] = { title = "War of Information", description = "Ah, the anointment oil. I had expected one of Adrestes' recruits.\n\nNo matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice.\n\nWith our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end.\n\nInformation is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions.\n\nThen can we resolve payment.", objectives = "Place Eyes of Hatred in the House of Rituals in Maldraxxus, Eonian Archives in Bastion, Tirna Vaal in Ardenweald, and Castle Nathria in Revendreth.", progress = "There will be no negotiation in this matter.", completion = "Already my vision grows. The pact is sealed." }
WordHunterWoW_QuestEN[61492] = { title = "The Princeguard", description = "Renathal carries himself well, but hides great pain. His wounds from Denathrius have not healed.\n\nHe is vulnerable.\n\nHe intends to send you to secure his old fortress of Darkwall Tower with banners and rely on his own strength to deter enemies. This is a poor tactical choice.\n\nTake this small reserve of anima with you and revive Chelra the Bladewall. She was last seen at Darkwall. Revive her and she can aid you in taking the tower.", objectives = "Revive Chelra the Bladewall and drive enemies out of Darkwall Tower.", progress = "I have suffered in stillness for months. I worried I would never wake again.", completion = "Well fought. That will not hold them for long, but it should buy Renathal the time he needs.\n\nThank you, mortal, for the infusion. I shall put this precious anima to good use while it lasts." }
WordHunterWoW_QuestEN[61496] = { title = "A Familiar Energy", description = "<The soul looks at you, thankful but curious.>\n\nI saw another living mortal in the Maw. He had the same... aura as you. Almost as if you were kin... no. Allies. Adventurers, bound by shared acts of courage.\n\nThat broker had him in her refuge. As for why, I cannot say.\n\nPerhaps you should find out.", objectives = "" }
WordHunterWoW_QuestEN[61509] = { title = "Shinies of Bastion", description = "Chordy is bored, boooored!\n\nYou want to go look for luckydos? Go on adventure with Chordy?\n\nWe go to land of wing people, go look for valuable luckydos there.\n\nReady?", objectives = "Use Chordy to locate and collect 10 valuable salvage around Bastion.", progress = "Did we find anything good?", completion = "Interesting, these are in better condition than most of Chordy's finds.\n\nThese will serve us well. Thank you, Maw Walker." }
WordHunterWoW_QuestEN[61510] = { title = "A Bountiful Haul", description = "Chordy want to go on adventure! You want to go too, yes?\n\nI scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days.\n\nWe go to land of tree people! If we search together, we'll find many luckydos!", objectives = "Use Chordy to locate and collect 10 valuable salvage in Ardenweald.", progress = "Did we find anything good?", completion = "Where did you find these? They're positively covered in filth!\n\nUgh, that smell! Here, take this and go clean yourself up." }
WordHunterWoW_QuestEN[61511] = { title = "Things They Leave Behind", description = "Chordy bored. Chordy want to go on adventure! You want to go too, yes?\n\nPale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves!\n\nYou ready to go?", objectives = "Use Chordy to locate and collect 10 valuable salvage in Revendreth.", progress = "Did we find anything good?", completion = "Interesting finds. These will be quite useful.\n\nThank you, Maw Walker." }
WordHunterWoW_QuestEN[61517] = { title = "zz", description = "", objectives = "" }
WordHunterWoW_QuestEN[61518] = { title = "Follow Me", description = "Assuming the others are in position, we are prepared to steal the necropolis.\n\nYou and I must push forward to rendezvous with Ansid. Khaliiq will regroup with Vyn once their tasks are complete.\n\nCome along, {name}, and stay near. I will shroud the both of us in shadow, so long as you are at my side.", objectives = "Follow Navigator Xennir to the rendezvous point.", progress = "Keep your eyes open.", completion = "It seems we've been discovered. Times like these demand flexibility." }
WordHunterWoW_QuestEN[61520] = { title = "Enemy of My Mnemis", description = "", objectives = "" }
WordHunterWoW_QuestEN[61522] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", progress = "Yes? Did you find anything on your supply run?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>" }
WordHunterWoW_QuestEN[61523] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", progress = "Yes? Did you find anything on your supply run?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>" }
WordHunterWoW_QuestEN[61524] = { title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?" }
WordHunterWoW_QuestEN[61525] = { title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?" }
WordHunterWoW_QuestEN[61526] = { title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?" }
