WordHunterWoW_QuestEN[61541] = { title = "The Forge of Bonds", description = "{name}, are you ready for another gift?\n\nThe next boon we grant thee is one of bonds. As you have bound yourself to us, we shall bind to you. In the binding of souls, we become something greater.\n\n<Moonberry leans in close.>\n\nSounds scary, huh? Don't worry! You and your soulbind will both strengthen each other.\n\nWhen I asked for volunteers, many fae stepped forward. I picked someone I just know you're going to like. And this will be a boon for her, too.\n\nGo to Flutterby. She'll help you both.", objectives = "Meet Flutterby at the Forge of Bonds.", completion = "Oh, wow! I love guiding soulbinding! It's my favorite duty!" }
WordHunterWoW_QuestEN[61542] = { title = "The Boon of Binding", description = "<Flutterby clasps her hands before her and assumes an air of tranquility.>\n\nSoulbinding is not an irrevocable act. However, such a bond must be carefully considered before it is made.\n\nYou and your soulbind will know each other's hearts and minds. Your hopes and fears; your dreams and memories; all will be shared between you. \n\nAs long as the bond exists, you are intertwined; always together even when apart.\n\nOnce complete, your connection will transcend physical space and empower you both.", objectives = "Complete the soulbinding ritual.", progress = "When you are ready, we may proceed.", completion = "You... have lived a very interesting life." }
WordHunterWoW_QuestEN[61543] = { title = "Herbalism: Lambent Vigil's Torch", description = "", objectives = "" }
WordHunterWoW_QuestEN[61544] = { title = "Herbalism: Lush Widowbloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[61545] = { title = "Herbalism: Engorged Marrowroot", description = "", objectives = "" }
WordHunterWoW_QuestEN[61548] = { title = "Set Me Free", description = "Ansid has been captured and imprisoned by the foundry's guards.\n\nIt seems they were expecting us, completely shattering the element of surprise. My baroness would be disappointed in my lack of foresight.\n\nThis plan cannot succeed without Ansid. One of these soldiers is bound to possess the key to his cage.\n\nShould you find it, we may yet carry out my baroness's will.", objectives = "Find the Ossein Key on one of the Ossein Strongarms and use it to free Ansid.", progress = "Take caution.", completion = "Expertly navigated. Perhaps you should pilot the necropolis." }
WordHunterWoW_QuestEN[61549] = { title = "Drought Conditions", description = "", objectives = "" }
WordHunterWoW_QuestEN[61550] = { title = "Strengthening the Bond", description = "I know how you feel... and what you have endured for the sake of your world. \n\nYou now know of my own triumphs and tragedies as well.\n\nOur bond will grow stronger over time. But for now, let us see what it has granted us.\n\nArdenweald has needs of us. We must do everything in our power to save it.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", progress = "We are stronger together.", completion = "Together, we can do anything." }
WordHunterWoW_QuestEN[61551] = { title = "Crush 'Em All", description = "The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us.\n\nEnforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered.\n\nShe is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.", objectives = "Use Ansid's Explosive to kill Enforcer Borgulla.", completion = "Your strength never fails to impress me." }
WordHunterWoW_QuestEN[61552] = { title = "The Hunt Watches", description = "The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets.\n\nWatcher Vesperbloom directs the eyes and ears of the forest.\n\nSeek out our new growth, then turn to her for guidance.", objectives = "Activate Adventures then seek out Watcher Vesperbloom.", progress = "Ah. You're here. Good.", completion = "We have much to do." }
WordHunterWoW_QuestEN[61553] = { title = "Know Where to Strike", description = "It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove.\n\nThis is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen.\n\nAllow me to demonstrate...", objectives = "Use the Command Table to send your forces on an adventure.", progress = "Every victory furthers our cause.", completion = "They will succeed in their mission, I have no doubt." }
WordHunterWoW_QuestEN[61554] = { title = "The Play's The Thing", description = "You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt.\n\n<Vesperbloom could be smirking... Or it could be a trick of the light.>\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold.\n\nLady Moonberry awaits you in the Sanctum Hall with more information.\n\nBreak a leg.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Seek out Lady Moonberry in the Heart of the Forest central hall.You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt.\n\n<Vesperbloom could be smirking... Or it could be a trick of the light.>\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold.\n\nLady Moonberry awaits you in the Sanctum Hall with more information.\n\nBreak a leg.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[61555] = { title = "High Inquisitor Vetar", description = "", objectives = "" }
WordHunterWoW_QuestEN[61556] = { title = "Party Crashers", description = "", objectives = "" }
WordHunterWoW_QuestEN[61557] = { title = "An Echo in the Darkness", description = "{name}, I... I am beset by dark visions. A power emanating from within Torghast.\n\nA familiar sensation. One I have not felt since...\n\nCome to Oribos. Do not delay.", objectives = "Meet Bolvar Fordragon in Oribos.", completion = "<Bolvar grimaces in pain.>" }
WordHunterWoW_QuestEN[61558] = { title = "The Highlord's Vision", description = "<Thrall's brow is furrowed.>\n\nWe were speaking with the Highlord when he was struck by a jolt of agony.\n\nHe said he could see something stirring in the Maw. Inside the Jailer's tower.\n\nThe pain seems to be getting worse. We need to find out what he's sensing.", objectives = "Find out what Bolvar senses inside Torghast.", progress = "We must know the truth.", completion = "This is dire indeed." }
WordHunterWoW_QuestEN[61559] = { title = "A Mourneblade Born", description = "While his father was missing, I cared for Anduin like a son. To see him like that, at the mercy of Sylvanas...\n\n<Bolvar's eyes flare with fire.>\n\nSomething must be done.\n\nTake a moment. Let me know when you are ready to discuss what comes next.", objectives = "Discuss the vision with Bolvar and the others.", completion = "We have to save Bolvar!" }
WordHunterWoW_QuestEN[61564] = { title = "Blacksmithing: Polished Kyrian Shield", description = "", objectives = "" }
WordHunterWoW_QuestEN[61565] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[61567] = { title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally their troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", objectives = "Destroy the Southwestern, Northwestern, and Notheastern Astral Projectors.", completion = "Gharmal's influence runs deep in this place, but it will fade more quickly thanks to your efforts." }
WordHunterWoW_QuestEN[61569] = { title = "Keys to the Ruin", description = "At last, our target is within reach.\n\nThe necropolis rests above us, moored to this platform by a necrotic restraining bolt.\n\nTwigin can fly you to the apex of the necropolis. It will be ours to command once you insert this keystone.\n\nWe will prepare for our departure. Rejoin us when you are done.\n\nVictory will soon be ours.", objectives = "Fly with Twigin to the necropolis's apex and plug in the Runic Keystone.", progress = "Our mission is nearly complete.", completion = "Come, <name>. Would you not witness your success firsthand?" }
WordHunterWoW_QuestEN[61586] = { title = "Machinations of War", description = "With Bastion as our ally, we have the strength to crush Gharmal and the House of Constructs.\n\nWe'll gather the supplies for the attack, but our soldiers need a great champion to follow into battle.\n\nProve to them that you are the champion they seek.", objectives = "Increase your Renown.", completion = "Well done, Maw Walker. Our forces are prepared to strike." }
WordHunterWoW_QuestEN[61593] = { title = "A Crisis of Memory", description = "", objectives = "" }
WordHunterWoW_QuestEN[61594] = { title = "This Way Out", description = "We are fully prepared to launch the necropolis. We must hurry before Margrave Gharmal tries to interfere.\n\nSpeak with Vyn when you are prepared, but we mustn't waste time.\n\nWe will cast our shadow upon all of Maldraxxus.", objectives = "Tell Whisperer Vyn to launch the necropolis.", completion = "It is time to depart." }
