WordHunterWoW_QuestEN[61616] = { title = "The Ember Court", description = "We've got everything we need to host our first real Ember Court whenever you're ready, Maw Walker.\n\nTake a moment to finalize everything, and then we'll open court!\n\nRemember, we're trying to impress Cryptkeeper Kassir and convince him that we know what we're doing, so make sure you choose the refreshments and entertainment we hired for him!\n\nOnce everything's ready, let me know and I'll open the court!", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress your guest.", progress = "Cryptkeeper Kassir is going to love this!", completion = "Incredible! Flawless! The perfect party herald!\n\nAnd you did well too.\n\nLet's do this again next week!" }
