WordHunterWoW_QuestEN[61635] = { title = "Troubled Souls", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "Take the construct requests from the souls present.", completion = "So many souls, we have much work to do!" }
WordHunterWoW_QuestEN[61636] = { title = "PH - UNUSED", description = "You have proven your dedication to not only your soulbinds and their training, but to the ways of the kyrian.\n\nStand proudly in your accomplishments, but know that there is no end to what you can learn.\n\nYour accomplishments have not gone unnoticed. The Archon requests your presence.", objectives = "Present yourself to the Archon." }
WordHunterWoW_QuestEN[61637] = { title = "Unity", description = "A unique construct has chosen to join us, but its unethical creation leaves it most unsettled.\n\nThe fusing of fragmented Kyrian souls within this construct, gives it pain and suffering. We must find a way to harmonize these souls so they can live together in peace.\n\nCreate the Bindings of Wellbeing and bring ease to the Soulfused Construct.", objectives = "Bring ease to the Soulfused Construct.", progress = "Have you helped this construct?", completion = "So many souls now in harmony. Perhaps with time this construct will find happiness and a home here." }
WordHunterWoW_QuestEN[61638] = { title = "Iron Solution", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "Take the construct requests from the souls present.", completion = "So many souls, we have much work to do!" }
WordHunterWoW_QuestEN[61667] = { title = "Forged in Secret", description = "", objectives = "" }
WordHunterWoW_QuestEN[61689] = { title = "A Crisis of Memory", description = "", objectives = "" }
WordHunterWoW_QuestEN[61697] = { title = "A New Age", description = "With the final empowerment in place, our renewed Crest of Ascension stands bolstered by the might of not just Bastion, but all covenants.\n\nSoon new Ascended will grace these halls once more as aspirants finish their long-awaited trials.\n\nNone of this would be possible without your aid, Maw Walker. The honor of activating the Crest at last is yours.", objectives = "Activate the Crest of Ascension.", progress = "This is a glorious moment for all kyrian.", completion = "With the Crest complete at last, we must next turn our eyes back to the Forsworn.\n\n<You notice Grubby looking at you expectantly.>" }
WordHunterWoW_QuestEN[61699] = { title = "Not Much to Goo On", description = "", objectives = "" }
WordHunterWoW_QuestEN[61701] = { title = "Searching the Grove", description = "It is clear that a struggle took place here. I fear that Kivarr may have been taken by the Drust.\n\nI scouted the surrounding area before you arrived. Eventide Grove has been overrun.\n\nThe Drust cannot have taken her far. We may yet be able to find her. I just pray that we are not too late...", objectives = "Search for Kivarr at Eventide Grove in Ardenweald.", completion = "Ulfar sent you to find me? Free me from this cage, and I will do what I can to aid you." }
WordHunterWoW_QuestEN[61702] = { title = "A Swift Intervention", description = "The Drust just took Kivarr away. They said they were going to sacrifice her in one of their rituals!\n\nIf we hurry, you may still be able to save her! I've seen where the Drust keep their sacrificial altar... it's scary, but I can take you there!\n\nThere's no time to waste! Follow me!", objectives = "Rescue Kivarr from Eventide Grove in Ardenweald.", completion = "Not a moment too soon! I appreciate your punctuality.\n\nMy den is not far away. We should hurry before more Drust arrive." }
WordHunterWoW_QuestEN[61703] = { title = "Nox Root", description = "In order to perform the ritual, I will need some nox root from Darkreach.\n\nIt is a unique plant that only grows within soil that has been corrupted by Drust magic.\n\nDarkreach lies to the west, not far from my den. What was once a peaceful, verdant grove is now filled with blight and ruin.\n\nI will travel to the Heart of the Forest to prepare the ritual. Meet me there when you have gathered the nox root.", objectives = "Collect 12 Nox Root from Darkreach in Ardenweald.", progress = "Have you brought the reagents?", completion = "Good, you were able to find enough nox root for the ritual. Unfortunately, we have another problem..." }
WordHunterWoW_QuestEN[61704] = { title = "Ember Court: Guest RSVPs", description = "Prince Renathal will wish to invite certain guests to each Ember Court.\n\nIn the future, we'll be able to adjust the guest list to make it easier to please everyone in attendance. But, we should follow the Prince's lead on this first one.\n\nWork with Lord Garridan and Lady Ilinca to ensure that Cryptkeeper Kassir is able to attend and returns his RSVP.\n\nIf you haven't met Cryptkeeper Kassir yet in your adventures, you may need to introduce yourself before he'll listen to you.", objectives = "Speak with Lord Garridan to see your Guest List, then meet Cryptkeeper Kassir to earn his RSVP.", completion = "The prince is wise to hold court. A timeless tradition of influence and prestige in this realm." }
WordHunterWoW_QuestEN[61705] = { title = "Ember Court: Refreshments", description = "We should always serve refreshments in the Ember Court, tailoring our choice of refreshment type to the preferences of our guests.\n\nLuckily, I know our first guest well. Like Theotar, he prefers it to be Formal.\n\nWork with Picky Stefan to acquire everything we need to throw a fancy tea party.", objectives = "Speak with Picky Stefan to see your Refreshment options, then complete Tubbins's quest to earn the tea party contract.", completion = "You smart! Tubbins tea is best tea!" }
WordHunterWoW_QuestEN[61706] = { title = "Ember Court: Entertainment", description = "Everyone loves entertainment!\n\nOur first guest is from the Halls of Atonement, so he will certainly appreciate a presentation of the powerful rituals the Accuser is capable of.\n\nWork with Hips to acquire everything we need to host atoning rituals at the Ember Court.", objectives = "Speak with Hips to see your Entertainment options, then complete Gresit's quest to earn the rituals contract.", completion = "A new court in Revendreth? The Accuser must be pleased that you chose to include rituals of atonement in the festivities." }
WordHunterWoW_QuestEN[61707] = { title = "Crumbled Reality", description = "As the drought and devourers eat our buildin's, the structures lose their hold on reality. Thing is, it ain't a clean process. Some of that debris is still infused with anima.\n\nWhen your out, be a stoneback an' bring us whatever infused debris you can find.\n\nSee, we can recycle it into new structures as you hero types go and get the anima flowin' again.\n\nBring it here an we'll get it sorted.", objectives = "Recover 100 Infused Rubble.", progress = "Impressed 'ow much you can carry with 'em 'itty bitty arms.", completion = "Everythin's bricks n' mortar with you. Love it." }
WordHunterWoW_QuestEN[61708] = { title = "Drawing Out the Poison", description = "", objectives = "" }
WordHunterWoW_QuestEN[61709] = { title = "Witch's Satchel", description = "I sent Ara'lon to steal a witch's satchel from the Drust... a dangerous task from which he has yet to return.\n\nThe Drust's nightscreamers carry many reagents we need to perform the ritual. We cannot proceed without one.\n\nYou must go to the Oaken Assembly to procure one of their satchels... and find Ara'lon, if you can.", objectives = "Collect 1 Witch's Satchel from the Oaken Assembly in Ardenweald.", progress = "Do you have the satchel? And what of Ara'lon?", completion = "This contains everything we need. Give me a moment and I will prepare the reagents for our ritual." }
WordHunterWoW_QuestEN[61710] = { title = "The Broken Spear", description = "<The shattered remains of a sylvari spear litter the ground. You recognize the spear as belonging to Ara'lon.\n\nThis confirms that Ara'lon was here. Unfortunately, he is nowhere to be found.\n\nLord Herne will want to know of your discovery.>", objectives = "Deliver the remains of Ara'lon's spear to Lord Herne at Heart of the Forest in Ardenweald.", progress = "What news do you bring?", completion = "Though this bodes ill, I am not ready to give up hope that Ara'lon survived. He may still be out there.\n\nI will assemble a search party. We will find him and bring him home... no matter what fate has befallen him. Thank you." }
WordHunterWoW_QuestEN[61711] = { title = "Ritual of Purification", description = "I have finished making preparations for the ritual. The moment of truth has come.\n\nThe Drust fetish that Ulfar gave you will channel the ritual's power into Gweyir. It should counteract the curse that imprisons her mind.\n \nThis will not be pleasant. It may not even work. But this is the only chance we have to free her.", objectives = "Complete the Ritual of Purification.", progress = "The ritual is our only hope of freeing Gweyir. We must try...", completion = "You performed the ritual admirably, but the Gorak Zhar's power was too strong for Gweyir to withstand. There is nothing more we can do, I am afraid.\n\nIt seems the masked fae are lost to us after all..." }
WordHunterWoW_QuestEN[61713] = { title = "Blueprint: Charm of Quickness", description = "<You have discovered plans for a charm that seems to make your soulbinds fleet of foot in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "Bring the Blueprint: Charm of Quickness to Dactylis.\n\nProvided item:", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting." }
WordHunterWoW_QuestEN[61714] = { title = "Gilded Abacus", description = "<A beautifully crafted abacus rests in your hands. Its frame glimmers and shines in the light, its beads smooth auric orbs.\n\nYour steward will appreciate this as not only a useful gift, but an exquisite one.>", objectives = "Summon your steward companion via Summon steward, then give them the Gilded Abacus.\n\nProvided item:", completion = "<Your companion stares in awe.>\n\nNo words to say... so beautiful! Can keep track of much more now. But what to count...\n\nAha! Count your things! No worry, am excellent counter. Woo-woo!" }
WordHunterWoW_QuestEN[61715] = { title = "Request of the Highlord", description = "The information you uncovered in Maldraxxus should quell the drums of war between the Necrolords and the Kyrian.\n\nAnd this message from the Primus... extraordinary!\n\nI would advise you to enlist Highlord Fordragon's counsel, but he appears preoccupied. Visitors from your world have come to seek him out. Quite insistently, I might add.\n\nThe nuances of mortal interaction elude me. But it seems the nature of their dialogue was rather... intense.\n\nPerhaps you can assist the Highlord with this matter.", objectives = "Speak to Bolvar Fordragon.", completion = "<Even through his scarred, molten visage, the emotion on Bolvar's face is plain.>\n\nMy daughter... here. I never thought..." }
WordHunterWoW_QuestEN[61716] = { title = "A Glimpse into Darkness", description = "When I put the Lich King's crown upon my head, I wanted the world to believe I was dead. Even my daughter, Taelia. I... thought a lie would be kinder than the truth.\n\nBut she is no longer the little girl I left in Kul Tiras. I see my choice was a selfish one.\n\n<Bolvar pauses.>\n\nShe and Lady Menethil have asked me to peer into the Maw to see if our allies yet live. It is a dangerous request, but one I cannot refuse.\n\nHelp me focus on the broken helm. Together, we may find a glimpse of truth.", objectives = "Witness Bolvar's vision of the Maw.", progress = "There is much to do.", completion = "A troubling vision indeed. But we must not give up hope." }
WordHunterWoW_QuestEN[61717] = { title = "Gormling Piper: Tranquil Pools", description = "", objectives = "" }
WordHunterWoW_QuestEN[61725] = { title = "Stolen Mementos", description = "", objectives = "I anticipate the timely return of our stolen merchandise, Maw Walker.\n\nTheir pilfering leaves a blemish on what could otherwise be a perfectly satisfying event.", progress = "I anticipate the timely return of our stolen merchandise, Maw Walker.\n\nTheir pilfering leaves a blemish on what could otherwise be a perfectly satisfying event.", completion = "<Keeper Ta'saran carefully inspects each memento.>\n\nThese are all in adequate condition. Their return shall be noted in the logs.\n\nYou needn't fear a reprisal for their theft any longer." }
WordHunterWoW_QuestEN[61728] = { title = "Valis the Cruel", description = "", objectives = "" }
WordHunterWoW_QuestEN[61729] = { title = "Adventurer: Rahel", description = "", objectives = "Rahel has arrived from Darkhaven to assist us with, and I quote, \"killing anybody.\" She is quite eager to enter the fray.\n\nShe seemed rather upbeat at the prospect of working with you again, <name>." }
WordHunterWoW_QuestEN[61730] = { title = "The Captive King", description = "King Anduin has not been found inside Torghast. I fear we could spend eternity searching those endless corridors to no avail.\n\nWe must know what fate has befallen him. To peer into the tower represents a grave risk, yet we have little choice.\n\nStand with me, {name}. We will use the broken Helm of Domination to see into that hellish place.\n\nPerhaps together we can hold back the hungry darkness.", objectives = "Use the Helm of Domination to peer into Torghast.", progress = "We must peer into Torghast before Anduin is lost to us.", completion = "Anduin may appear unharmed, but his soul is imperiled.\n\nSylvanas Windrunner cannot be allowed to carry out her plan." }
WordHunterWoW_QuestEN[61731] = { title = "Magical Curios", description = "", objectives = "Curious. Most curious trinkets...\n\nMay I keep to study? Will learn much.", progress = "Curious. Most curious trinkets...\n\nMay I keep to study? Will learn much.", completion = "Most intriguing! Thank you!\n\n<Mikanikos immediately begins disassembling one of the trinkets to study.>" }
WordHunterWoW_QuestEN[61732] = { title = "Old Habits Never Die", description = "Your redistribution of anima has been commendable so far.\n\nBut venthyr are still venthyr. They may spend eons educating souls on the folly of greed and hoarding, but they often fail to acknowledge the return of that trait in themselves, given enough time.\n\nMy scouts have witnessed a number of venthyr siphoning the anima you have redistributed and hoarding it within their estates and dwellings. \n\nSearch these places and recover this hoarded anima so that we might put it to better use.", objectives = "Recover 10 Hoarded Anima Cages.", completion = "Greed. One of the few sins not fully purged but actually encouraged in the venthyr by Sire Denathrius in recent ages. \n\nWe have watched as he used this as a tool to control his populous, to keep them stagnant and un-unified. \n\nRenathal's methods are the only way forward." }
WordHunterWoW_QuestEN[61733] = { title = "Big Bag of Creepers", description = "Right. You've been a polished bit of gray so far and it's appreciated from the bottom up for sure.\n\nWell, now I got a task for 'ou that would help all of us dredgers put that anima you obtained to good use.\n\nCreepers.\n\nNot just any creepers, but 'em mire creepers. 'Ey got a look about 'em and a taste about 'em that just sings when you put it to good use.\n\nAs you go trippin' around Revendreth, grab any creepers ya find an' stick 'em in this here sack. I'll pay ya.", objectives = "Collect 20 Mire Creepers.", progress = "Creepers. 'Ey like chewin' on the mortar at holds all these walls up.", completion = "Well then, look at that!\n\nA big ol' bag of Creepers, with their squinty eyes and mold smellin' breath.\n\nAin't 'ey cute? \n\nHavin' a few a these around the lads while they work will really help morale. Much appreciated from all of us." }
WordHunterWoW_QuestEN[61734] = { title = "Census of Sins", description = "The Curator once knew the contents and locations of every sinstone in Revendreth dating back to the founding of this realm.\n\nSadly, her time in the Maw disrupted those essential parts of her vast intellect and we can no longer rely upon her for such knowledge. At least, not for a while. And so it falls to me to rebuild a 'living' archive.\n\nAs you venture into Revendreth I would ask that you recover the contents and location of certain sinstones. This will help us orient our archive.", objectives = "Inspect 7 Lost Sinstones.", completion = "With time and enough information we may be able to anchor the Curator's knowledge so that she once again becomes the invaluable resource that she once was." }
WordHunterWoW_QuestEN[61735] = { title = "Awaken Our Allies", description = "I have need of your services.\n\nI have identified a collection of stoneborn throughout Revendreth whom may be swayed to our cause, or were already members of our cause before returning to their stone slumber.\n\nYou have provided us with the anima we needed, now it is time to put it to use. Seek out our allies and awaken them. I have fashioned an anima container for easier transport to aid in this endeavor. \n\nWe need an army if we are to face an army.", objectives = "Awaken 15 Allied Stoneborn.", completion = "Terrifying, aren't they? Magnificent weapons crafted by the finest arts perfected since the coalescing of the Shadowlands themselves. \n\nThey shall prove invaluable in the times to come." }
WordHunterWoW_QuestEN[61736] = { title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Whitemane. She can tell you the rest.", objectives = "Speak to Sally Whitemane about the abductions.There is much you need to be told, <name>.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Whitemane. She can tell you the rest.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[61737] = { title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Nazgrim. He can tell you the rest.", objectives = "Speak to Nazgrim about the abductions.There is much you need to be told, <name>.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Nazgrim. He can tell you the rest.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[61738] = { title = "Ember Court: Lost Chalice Band", description = "Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw!\n\nThe band is not quite ready to tour yet, however.\n\nThe musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities!\n\nNoise complaints and all that.\n\nHelp me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!", objectives = "Use band posters to recruit 10 groupies and 10 roadies and recover 3 Confiscated Band Supplies.", progress = "Any venthyr or dredger will do. We are not picky about our fans.", completion = "I do not know what promotional tricks you used, but it worked.\n\nA whole stream of dredgers and venthyr stopped by to join the band crew!\n\nThe Lost Chalice Band is ready to tour!" }
WordHunterWoW_QuestEN[61739] = { title = "The Wayward Baron", description = "It has come to my attention that you seek to uncover a plot by the baron Kel'Thuzad. \n\nThat upstart has been a thorn in my side since he arrived at the House of Rituals. Not only did he pilfer my rightfully earned title, he has since shut me out of the house's dealings.\n\nI have yet to find evidence that would mar Sin'dane's adoration for her new baron, and thus I offer an arrangement. I grant you access to the House of Rituals, and in return you help me bring down Kel'Thuzad.\n\nDo we have an accord?", objectives = "Open Balmedar's Supplies at the tower near the Scaplian Ridge.", completion = "<Balmedar's voice resonates from the floating eye.>\n\nYou didn't really think I would risk meeting you here in person, did you?\n\nCome, we have much work to do." }
WordHunterWoW_QuestEN[61740] = { title = "Playing Favorites", description = "We will have to construct an illusion to allow you entry into the House of Rituals. However, not just any illusion will do. In order to join Kel'Thuzad's inner circle, we require something... specific.\n\nWe're going to need a body.\n\nFortunately for us, one of the baron's favorite acolytes is performing a ritual outside of the house itself. You'll need to fight your way to her, but of that I'm sure you're capable.", objectives = "Defeat Acolyte Nelesis and bring her corpse back to the tower near Scaplian Ridge.", progress = "Don't you have a corpse to procure?", completion = "I must say it was satisfying watching you wipe the smug look off of Nelesis's face. She always thought she was so superior.\n\nBut enough revelry. We have work to do." }
WordHunterWoW_QuestEN[61741] = { title = "Pilfered Power", description = "The illusion ritual will require a substantive amount of anima to complete. Since such a resource isn't simply lying around these days, we will need to take some.\n\nThe abominations from the House of Constructs recently arrived with a delivery of anima-rich spoils from the raid on Bastion. \n\nUse the maldracite crystal I've included in the parcel to extract enough anima for our ritual.", objectives = "Drain anima from the Kyrian Spoils in the House of Rituals to fill the maldracite crystal.", completion = "This should be sufficient.\n\nLet us prepare for the ritual." }
WordHunterWoW_QuestEN[61742] = { title = "A Fitting Guise", description = "The ritual to complete your disguise should be quite simple with the assistance of my oculus. Even a {class} like you should be able to manage it.\n\nWhen you are ready, simply hold the empowered crystal above Nelesis's corpse. My oculus will do the rest.", objectives = "Meet Balmedar in the Hall of Blades at the House of Rituals.", completion = "An impressive resemblance. You may just be able to pull this off.\n\nWell, what are you waiting for?" }
WordHunterWoW_QuestEN[61743] = { title = "The Pupil Returns", description = "Now that you have your disguise--and I have assurance of your loyalty--it is time you reported to your new master.\n\nFind Kel'Thuzad within the Vault of Souls. Do whatever tasks he requires of you, but keep your eyes open for anything untoward.\n\nMy oculus will continue to accompany you so that I can provide guidance when the time is right.\n\nWe will uncover this new baron's true intentions.", objectives = "Meet Kel'Thuzad within the Vault of Souls.", completion = "Ah, you've returned. I take it the ritual went well?\n\nCome, we have much to accomplish." }
WordHunterWoW_QuestEN[61744] = { title = "The Baron's Plan", description = "You have done well in my service, Nelesis. When the time has come to take my rightful place, you will be well rewarded.\n\nUntil then, I will require your utmost devotion and secrecy.\n\nOur preparations are almost complete. Come, walk with me, and I will show you the splendor of our works.", objectives = "Walk with Kel'Thuzad.", progress = "Walk with me, acolyte.", completion = "There are but a few tasks remaining before we can complete our ritual.\n\nYou must begin immediately." }
WordHunterWoW_QuestEN[61745] = { title = "Mistress of Tomes", description = "The kyrian will no doubt make a worthy sacrifice for our ritual, but I am not entirely versed with the magics of his kind. I have requested that the Baroness Ninadar assemble a list of appropriate literature, so that I can ensure my ritual will have the desired effect.\n\nAs you know, the baroness enjoys exploiting her title, so expect to be faced with some manner of mundane tasks in exchange for her cooperation. \n\nReturn when you have procured the tomes, acolyte.", objectives = "Speak with Baroness Ninadar in the Grimoirium.", completion = "Kel'Thuzad always seems to have the most studious of pets, doesn't he?\n\nWhat is it the baron wishes of me, acolyte?" }
WordHunterWoW_QuestEN[61746] = { title = "Cantrip Collections", description = "One of the... more regrettable duties of the Mistress of Tomes is the collation and maintenance of our scroll library. Unfortunately, many of our acolytes are less than prompt when it comes to returning items they have borrowed, which requires me to seek them out and retrieve them myself.\n\nOf course, this is far too menial a task for a baroness, but that is why lackeys like you exist.\n\nGo, and retrieve my scrolls. Feel free to use whatever persuasive means you have at your disposal.", objectives = "Collect 6 Overdue Scrolls from Necrotic Acolytes in the Grimoirium.", progress = "Have you found my scrolls?", completion = "Wonderful. Kel'Thuzad's pets are nothing if not reliable.\n\nWe are done here." }
WordHunterWoW_QuestEN[61747] = { title = "Errant Enchantments", description = "The House of Rituals is a place of constant study. Every day, new incantations and formulae are concocted to further the arts of necromancy. \n\nIt can be difficult to keep track of such innovation. To aid in cataloguing our progress, our sorcerers have applied the use of enchanted quills and parchment. Unfortunately, if not properly stored, these implements tend to run amok. \n\nOf course, they were not properly stored.  Find the implements and return them to where they belong.", objectives = "Retrieve 4 Errant Quills and 6 Rampant Grimoires in the Grimoirium.", progress = "Enchanted quills will not collect themselves, now will they?", completion = "Much better!\n\nI simply cannot abide a disorganized Grimoirium." }
WordHunterWoW_QuestEN[61748] = { title = "The Hall of Tomes", description = "Very well, you can have your list. The volumes you seek can be found in the Hall of Tomes.\n\nNow, run back to your master like a good little pet.", objectives = "Collect the required volumes from the Hall of Tomes and return them to Kel'Thuzad in the Vault of Souls.", progress = "You have returned? Do you have my tomes?", completion = "Ah yes, these will do.\n\nIt will take some time to study these tomes. In the meantime, I have more need of you." }
WordHunterWoW_QuestEN[61749] = { title = "Necessary Ingredients", description = "As you are well aware, a ritual of this complexity requires several reagents. I have asked that Carver Jor'dan prepare what I'll need.\n\nSeek him out in the Reagentry, and provide whatever assistance he requests.", objectives = "Speak with Jor'dan the Powerful in the Reagentry.", completion = "You are Kel'Thuzad's acolyte, are you not?" }
WordHunterWoW_QuestEN[61750] = { title = "Heart of the Forest", description = "The baron requests a veilwing's heart, but procuring one is going to be something of a problem. \n\n<Jor'dan gestures to the disarray nearby.>\n\nAs you can plainly see, one of our sorcerers proved incapable of restraining the beast. I regret to inform you that our only specimen has escaped.\n\nIt cannot have gone far, though. If you follow its tracks you should be able to catch up with it and retrieve the heart yourself.\n\nI assure you the baron will not be able to perform his ritual without it.", objectives = "Collect a Veilwing's Heart from the Elusive Veilwing in the House of Rituals.", progress = "Did you find the veilwing?", completion = "This specimen should work nicely for the baron's ritual.\n\nI will add it to his parcel." }
WordHunterWoW_QuestEN[61751] = { title = "Cage Free Spores", description = "I will need your assistance with the collection of one other reagent for your master. These spore clusters he requests--while normally a trivial matter--will require a bit of work.\n\nYou see, as the veilwing rampaged throughout the Reagentry, it toppled and broke several nearby cages hosting the blightrays from which we harvest the clusters.\n\nYou will have to collect them through more... conventional means. \n\nThe clusters are fragile, however, so try not to damage them while subduing the creatures.", objectives = "Collect 6 Intact Spore Clusters from Escaped Blightrays in the Reagentry.", progress = "Do you have the spore clusters?", completion = "This should do.\n\nI will assemble the reagents together to return to your master posthaste." }
WordHunterWoW_QuestEN[61752] = { title = "The Final Reagent", description = "I have gathered most of the remaining reagents on your master's list. All that remains is the special shipment he requested from Oribos.\n\nThe brokers have yet to deliver the shipment. When it arrives, your master will have all he needs to complete his ritual.", objectives = "Bring the Bundle of Reagents to Balmedar in the House of Rituals.", progress = "Let us see what we have here.", completion = "Let me hold onto these for now.\n\nI will need you to get your hands on that shipment!" }
WordHunterWoW_QuestEN[61753] = { title = "Explosive Schemes", description = "The brokers deal in objects most exotic and profound. If Kel'Thuzad requires reagents from them, his ritual must be outside the normal scope of the House of Rituals.\n\nThis mysterious reagent could be the key to unlocking Kel'Thuzad's plan. We must get a hold of this delivery from Oribos. \n\nI have taken the liberty of concocting an alchemical bomb. Use it to ambush the caravan and retrieve whatever they are transporting.", objectives = "Use the Alchemical Explosive to ambush the Broker caravan at the Scaplian Ridge.", progress = "The caravan will arrive any moment now. Make haste!", completion = "Well done.\n\nNow we must work quickly, before we are discovered." }
WordHunterWoW_QuestEN[61754] = { title = "No Crate Unturned", description = "That explosion will likely bring onlookers from the House of Rituals. We must act quickly.\n\nSearch through the debris for anything that looks out of the ordinary. It is likely that Kel'Thuzad's mystery reagent won't be hard to spot.", objectives = "Search the Broker's Crates for Kel'Thuzad's special reagent.", completion = "The runes on this blade... they are a hallmark of domination magic!\n\nThis is not good, <class>." }
WordHunterWoW_QuestEN[61755] = { title = "Blinding the Brokers", description = "We cannot allow Kel'Thuzad to discover who stopped his shipment. \n\nNone must be left to tell the tale of what transpired here.", objectives = "Kill 8 broker witnesses in the Scaplian Ridge.", completion = "The guards have been dealt with? Good.\n\nWe have more pressing matters, now." }
WordHunterWoW_QuestEN[61756] = { title = "Designed to Fail", description = "The pieces are all coming together. The kyrian, the Paths of the First Ones, and runes of domination? \n\nKel'Thuzad is looking to breach the Maw!\n\nWe cannot allow this to happen! The Maw has been locked away from the Shadowlands for good reason. Opening that floodgate could be catastrophic!\n\nThe baron is too powerful to confront headlong, so we will stop his ritual instead. Return to him with his reagents. I have made some \"modifications\" that should provide a calamitous end to his scheme.", objectives = "Bring the Bundle of \"Modified\" Reagents to Kel'Thuzad in the Vault of Souls.", progress = "My acolyte returns. What have you brought me?", completion = "I see you managed to procure the reagents from Jor'dan, and... wait, what's this?\n\nI am impressed that you managed to procure the shipment from the brokers when my sorcerers could not!  \n\nYou are quite the resourceful one, acolyte!" }
WordHunterWoW_QuestEN[61757] = { title = "Caught in the Act", description = "Well then, since it was you who managed to procure the missing reagent, I find it only fair that you assist me with the final ritual! \n\nI can guarantee that this incantation will see you promoted to a full sorcerer of the house!\n\nThe preparations are already made. We can begin as soon as you are ready.", objectives = "Assist Kel'Thuzad in completing the ritual." }
WordHunterWoW_QuestEN[61758] = { title = "Improvised Implements", description = "There must be some way we can get ourselves out of these cells. \n\nI don't see anything I can use over here. Search your cell for anything that can facilitate our escape.", objectives = "Search your cell for something that can be used to escape." }
WordHunterWoW_QuestEN[61759] = { title = "A Helpful Hand", description = "It takes but a simple act of necromancy to animate a hand. Unfortunately, since you will be in closest proximity, you must be the one to command it.\n\nWhen you are ready, I will reanimate the hand. Once you have control, use it to pull the lever at the end of the hall. \n\nCouldn't be simpler, right?", objectives = "Navigate the Reanimated Hand to the end of the hall and activate the Corroded Lever.", completion = "We have no time to lose!" }
WordHunterWoW_QuestEN[61760] = { title = "The Traitor Unmasked", description = "We must waste no time in warning the margrave of Kel'Thuzad's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond!\n\nLet us put an end to this!", objectives = "Confront Kel'Thuzad in the Hall of Sorcery.", progress = "We must stop Kel'Thuzad before it's too late!", completion = "I didn't think we would make it out of that encounter intact.\n\nYou are truly a skilled <class>, <name>." }
WordHunterWoW_QuestEN[61761] = { title = "The Better Part of Valor", description = "We now have no choice but to make a strategic retreat. Kel'Thuzad is far too fortified within the necropolis, and if Ninadar is his ally, then the House of Rituals is firmly in his grasp.\n\nIt will take nothing short of an army to save the margrave now.", objectives = "Return to the Seat of the Primus.", completion = "The margrave has been captured? So Kel'Thuzad has seized control of the house!\n\nThis changes things." }
WordHunterWoW_QuestEN[61762] = { title = "Making a Smarter Dredger", description = "If he be hostin' fancy courts with you and Temel, this dredger's gotta be special...\n\nSmarter. Stronger. Quicker to apologize when they accidentally knock over the refreshments table and spill anima all over some poor duchess...\n\nI got an idea! Broker bloke at the Night Market was tryin' to sell me some important drinks. Kaja'Extreme or somethin'.\n\nSays it bigguns the brain, yeah? That's just what we need! \n\nTake these Scorchshrooms, that broker loves them, but note he rotates his costs each week.", objectives = "Purchase a bottle of Kaja'Extreme from Ta'tru at the Night Market.", progress = "You got the Kaja'Extreme?", completion = "Alright, <name>, let's make some muck!" }
WordHunterWoW_QuestEN[61763] = { title = "Dredging up an Assistant", description = "Here we go, onto the dredging part.\n\nJust like we made that biggun here earlier!\n\nI mean we don't need the stone of binding or three other dredgers, but you'll still be throwing stuff into the muck!\n\nSo it's the same. \n\nYou head to the shore with this here Kaja-Infused Dredger Mix I whipped up for you.\n\nToss it into that muck pool and let's meet that new dredger butler of yours!", objectives = "Throw the Kaja-Infused Dredger Mix into the muck pool to create your dredger butler.", completion = "It worked! Of course I knew it would. Now what to name this guy... but first I am go'n to dismiss him so y'can test out the binding of the contract." }
WordHunterWoW_QuestEN[61764] = { title = "Dredging up a Name", description = "Oi, why aren't you addressing me by my proper name? Wait, I don't remember my name, proper or other. Does this mean I have amnesias? Oh no, I don't have a name, please, help!", objectives = "Talk with your assistant and decide on a name for them.", completion = "Oh yeah, that name totally fits my personality, or at least I think it does." }
WordHunterWoW_QuestEN[61765] = { title = "Words of Warding", description = "The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes.\n\nThe Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware.\n\nThe runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require.\n\nGood luck.", objectives = "Steal an Assassin's Soulcloak and dispel 4 Runes of Warding within Perdition Hold in The Maw.\n\nSuggested Players [3]", progress = "Are the wards gone? I am eager to resume surveillance of our enemy.", completion = "I trust you did not let your eyes wander while wearing the soulcloak? It can reveal some truly terrible things..." }
WordHunterWoW_QuestEN[61766] = { title = "Homegrown Help", description = "Every good party herald needs an assistant. Which is why I have you!\n\nBut every good party herald's assistant... also needs an assistant.\n\nWhich is why I procured permission from the prince for you to create your own dredger butler. We can start him on security while we cozy up to the guests and procure the necessary reading materials to train him on the social protocols of the different realms. He'll be entertaining the whole court in no time. \n\nNo, don't thank me. You've earned this!", objectives = "Meet Rendle in Dredgewood to make a dredger butler.", completion = "You ready to get your hands dirty?\n\nMakin' dredgers ain't pretty work." }
WordHunterWoW_QuestEN[61767] = { title = "A Perilous Journey", description = "Mograine has rallied the House of the Chosen to strike at Margrave Gharmal and his House of Constructs. They grow in strength with each passing day--this may be our only chance.\n\nWe will join them on the field of battle. We will have justice for the fallen at my temple, as well as Mograine's own fallen kin.\n\nRendezvous at Spider's Watch within Maldraxxus' northern reaches. We will move from there.", objectives = "Meet Xandria at Spider's Watch in Maldraxxus.", completion = "Now we can join our new allies." }
WordHunterWoW_QuestEN[61768] = { title = "Stronger Together", description = "We are to meet Baroness Draka aboard the Zerekriss above this position. Trust our allies' judgment in the battle ahead--true courage is knowing when to rely on the wisdom of others.\n\nThe plan is simple. Clear out our flanks to ensure Gharmal's forces do not interfere with our true goal, then assault the Margrave himself.\n\nIf we fail, we fail in the name of justice.", objectives = "Fly with Xandria into the necropolis Zerekriss.", completion = "Welcome to Zerekriss, Maw Walker." }
WordHunterWoW_QuestEN[61769] = { title = "Fight and Flight", description = "Alexandros and Emeni will lead the Chosen assault on the western gate. \n\nYou and Xandria will direct your forces at the eastern gate. Secure the area and eliminate any resistance. \n\nOnce both flanks are secured we can attack Gharmal directly.", objectives = "Fly with Xandria to the House of Constructs.", completion = "This place is filled with horrors... horrors we will purge." }
WordHunterWoW_QuestEN[61770] = { title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these things?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure they see it!", objectives = "Kill 10 House of Constructs forces in the Separation Chamber.", progress = "Go bravely, <name>.", completion = "All this bloodshed will not bring them back... but it may spare others the same fate." }
WordHunterWoW_QuestEN[61771] = { title = "Justice from Above", description = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts.\n\nThe Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once.\n\nI shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", objectives = "Destroy 5 Maldracite Cores.", completion = "You have done a great service here." }
WordHunterWoW_QuestEN[61772] = { title = "Dark Developments", description = "<The torn design document appears to be written by the late Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to Artemede.>", objectives = "Bring the Abhorrent Design to Artemede outside the Hall of Chains.\n\nProvided item:", completion = "Allow me to read this for a moment." }
WordHunterWoW_QuestEN[61773] = { title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", objectives = "Slay Woeblade the Atrocity.", completion = "May our victory bring them peace." }
WordHunterWoW_QuestEN[61774] = { title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's abomination constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", objectives = "Collect 6 Stitchflesh Designs.", progress = "This foul work must be destroyed.", completion = "Well done. I will see that these are destroyed personally." }
WordHunterWoW_QuestEN[61775] = { title = "An Early End", description = "Within the Hall of Chains lie more abominations that are nearly complete. As we speak the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, the constructs we have destroyed so far will mean little in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any abominations you come across.", objectives = "Destroy 6 Inert Butchers.", progress = "May your blade strike true.", completion = "Every abomination denied is one less foe to contend with when we face Gharmal." }
WordHunterWoW_QuestEN[61776] = { title = "Trouble on the Western Front", description = "Alexandros and our Maldraxxi allies need reinforcement at the western gate on the Margrave's opposite flank. They are barely holding on!\n\nOur forces will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks we cannot hope to achieve victory.", objectives = "Fly with Kynthia to report to Alexandros at the Stitchyard.", completion = "I am glad Kynthia found you so quickly." }
WordHunterWoW_QuestEN[61777] = { title = "Charging The Blade", description = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest, but conventional weapons do nothing against their imbued hides.\n\nThankfully, I have an idea.\n\nYour old runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", objectives = "Charge your runeblade by killing enemy constructs in the Stitchyard.", completion = "This is a long shot, but it just might work..." }
WordHunterWoW_QuestEN[61778] = { title = "Aerial Advantage", description = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. The Zerekriss can't get into position until they are cleared out!\n\nI would take care of them myself, but I'm not much of a flier. Don't have the balance for it!\n\nTake my riding hook and latch onto a roc. Once you're riding, just start hitting it 'til the job is done.", objectives = "Grapple 6 Battlesewn Rocs out of the sky.", progress = "Teach 'em a lesson!", completion = "I could hear their cries from here. Nice work!" }
WordHunterWoW_QuestEN[61779] = { title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally his troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", objectives = "Destroy the Southwestern, Northwestern, and Northeastern Astral Projectors.", progress = "A blow inflicted to the enemy's morale can be as effective as traditional combat.", completion = "Gharmal's influence runs deep in this place, but it will fade more quickly thanks to your efforts." }
WordHunterWoW_QuestEN[61780] = { title = "Power of the Chosen", description = "The Zerekriss is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once he leaves his blighted tower, we can finish him once and for all.", objectives = "Destroy the Bilebloat Juggernauts.", progress = "Every moment the juggernauts live our position is in jeopardy!", completion = "Such power! Gharmal will have no choice but to face us now." }
WordHunterWoW_QuestEN[61781] = { title = "The End is Now", description = "Our forces have control of the House of Constructs, thanks to your intervention.\n\nNow, all that remains is the fall of the instigator themselves--Margrave Gharmal.\n\nThis battle has been long in the making, {name}. I am at your side without hesitation.\n\nLet us go to this monster. We will join Xandria to see him slain.", objectives = "Meet with Xandria near the central chamber of the House of Constructs.", completion = "It is time." }
WordHunterWoW_QuestEN[61782] = { title = "Pursuit of Justice", description = "Draka stands ready to unleash the power of the Zerekriss upon Gharmal. We need only buy her time to focus its weapon.\n\nWhat we do now, we do for all of us. Bastion and Maldraxxus have both lost many to these fiends.\n\nHe will not be defeated easily, but united our forces will finally bring him to justice!", objectives = "Defeat Margrave Gharmal.", completion = "Our fallen may finally rest in peace." }
WordHunterWoW_QuestEN[61783] = { title = "Mega Bite", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61784] = { title = "Cliffs of Bastion", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61785] = { title = "An Expected Visitor", description = "One Alexandros Mograine of Maldraxxus is meeting with the Paragon of Courage in Archon's Rise. Xandria has requested you join them.\n\nThe two worked together recently to repel a nascent secondary assault on the Temple of Courage. Xandria seems to trust him well enough, so we have granted him access to the hold...for now.\n\nI suspect they will not stay here long. You should make haste.", objectives = "Speak with Xandria in Archon's Rise.", completion = "Good. Now we can begin the mission." }
